/** === Three.js 渲染基座（HDRi + SSAO + Bloom + 自定义 PostFx） === */
function setupScene(container: HTMLElement): {
  renderer: THREE.WebGLRenderer;
  composer: EffectComposer;
  scene: THREE.Scene;
  camera: THREE.PerspectiveCamera;
  vignettePass: VignetteCAGrainPass;
} {
  const renderer = new THREE.WebGLRenderer({ antialias: false, powerPreference: 'high-performance' });
  renderer.setSize(container.clientWidth, container.clientHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.25));
  // ─── 物理光照管线（决定材质能否"被看见正确反射"）───
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  // r155+ 默认 useLegacyLights=false（物理灯）；显式声明以防工程依赖旧行为
  (renderer as unknown as { useLegacyLights?: boolean }).useLegacyLights = false;
  // ACES 电影色调映射
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  // 旧值 2.0 在加 HDRi 后会过曝；HDRi 已自带能量，曝光回归 1.05
  renderer.toneMappingExposure = 1.05;
  container.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  // 深蓝灰雾，距离拉远；HDRi 提供整体冷调环境光
  scene.fog = new THREE.Fog(0x111826, 22, 75);

  // ─── HDRi 环境贴图（决定 PBR 金属是否"活"）───
  // 用 three 内置 RoomEnvironment：无外部资产，零下载，立即可用。
  // PMREMGenerator 把环境烘成 mipmap 链，金属/光泽材质拿来当反射源。
  const pmrem = new THREE.PMREMGenerator(renderer);
  pmrem.compileEquirectangularShader();
  const roomEnv = new RoomEnvironment();
  scene.environment = pmrem.fromScene(roomEnv, 0.04).texture;
  pmrem.dispose();

  const camera = new THREE.PerspectiveCamera(
    75,
    container.clientWidth / container.clientHeight,
    0.05,
    100,
  );
  camera.position.set(0, 1.65, 3);
  camera.layers.enable(1);

  // ── 后期处理管线 ──────────────────────────────────────────────
  const w = container.clientWidth;
  const h = container.clientHeight;
  const composer = new EffectComposer(renderer);

  // 1. 场景渲染
  composer.addPass(new RenderPass(scene, camera));

  // 2. SSAO —— 接缝处暗角，瞬间从"扁平"变"立体"
  //    采样 8（性能优先），半径 0.6（机房尺度），minDistance 防止武器/UI 自我遮蔽
  const ssao = new SSAOPass(scene, camera, w, h);
  ssao.kernelRadius = 0.6;
  ssao.minDistance = 0.0008;
  ssao.maxDistance = 0.10;
  ssao.output = SSAOPass.OUTPUT.Default;
  composer.addPass(ssao);

  // 3. Bloom：机架LED/SmartX蓝光带/枪口火光发光
  //    strength 0.65 / radius 0.55 / threshold 0.78 —— LED 真正发光，但白墙不溢出
  const bloom = new UnrealBloomPass(new THREE.Vector2(w, h), 0.65, 0.55, 0.78);
  composer.addPass(bloom);

  // 4. OutputPass：读取 renderer.toneMapping + sRGB 转换
  const output = new OutputPass();
  composer.addPass(output);

  // 5. 自定义 PostFx：色散 + 影调分级 + 暗角 + 胶片颗粒（一遍合成，省 fbo）
  const vignettePass = new VignetteCAGrainPass();
  composer.addPass(vignettePass);
  // ──────────────────────────────────────────────────────────────

  window.addEventListener('resize', () => {
    const nw = container.clientWidth;
    const nh = container.clientHeight;
    renderer.setSize(nw, nh);
    composer.setSize(nw, nh);
    bloom.resolution.set(nw, nh);
    ssao.setSize(nw, nh);
    camera.aspect = nw / nh;
    camera.updateProjectionMatrix();
  });

  return { renderer, composer, scene, camera, vignettePass };
}

/** === 键盘/鼠标输入聚合 === */
const APP_START_TIME = Date.now();
function setupInput(domElement: HTMLElement): {
  getInput: () => InputState;
  isPointerLocked: () => boolean;
} {
  const keys = new Set<string>();
  let mouseDX = 0;
  let mouseDY = 0;

  domElement.addEventListener('click', () => {
    domElement.requestPointerLock?.();
  });
  document.addEventListener('mousemove', (e) => {
    if (document.pointerLockElement === domElement) {
      mouseDX += e.movementX ?? 0;
      mouseDY += e.movementY ?? 0;
    }
  });
  window.addEventListener('keydown', (e) => keys.add(e.code));
  window.addEventListener('keyup', (e) => keys.delete(e.code));

  const getInput = (): InputState => {
    const forward = (keys.has('KeyW') ? 1 : 0) - (keys.has('KeyS') ? 1 : 0);
    const strafe = (keys.has('KeyD') ? 1 : 0) - (keys.has('KeyA') ? 1 : 0);
    const input: InputState = {
      forward,
      strafe,
      jump: keys.has('Space'),
      sprint: keys.has('ShiftLeft'),
      crouch: keys.has('ControlLeft'),
      mouseDX,
      mouseDY,
    };
    mouseDX = 0;
    mouseDY = 0;
    return input;
  };

  return { getInput, isPointerLocked: () => document.pointerLockElement === domElement };
}

/** === 事件驱动迁移控制器 === */
class MigrationFlowController {
  private task: MigrationTask | null = null;
  private envResult: ESXiScanResult | null = null;
  private primaryVm: (DiscoveredVM & { workloadType: VMWorkloadType }) | null = null;
  /** 外部注入的"当前场上存活敌人数"回调，用于 Act6 守门 */
  private getAliveEnemies: () => number = () => 0;
  private clearAllEnemies: () => void = () => {};

  private envScan = new EnvScanPhase();
  private compat = new CompatibilityCheckPhase();
  private networkPhase: NetworkMappingPhase | null = null;
  private storagePhase: StorageMappingPhase | null = null;

  private storagePools: StoragePool[] = [
    {
      id: 'pool-nvme',
      name: 'NVMe-Pool-01',
      tier: 'nvme',
      totalTB: 10,
      availableTB: 8,
      maxIOPS: 400000,
      avgLatencyMs: 0.3,
      ioLocalitySupport: true,
      rdmaSupport: true,
      color: '#FFD700',
    },
    {
      id: 'pool-ssd',
      name: 'SSD-Pool-01',
      tier: 'ssd',
      totalTB: 20,
      availableTB: 15,
      maxIOPS: 120000,
      avgLatencyMs: 1.0,
      ioLocalitySupport: true,
      rdmaSupport: false,
      color: '#C0C0C0',
    },
    {
      id: 'pool-hdd',
      name: 'HDD-Pool-01',
      tier: 'hdd',
      totalTB: 50,
      availableTB: 35,
      maxIOPS: 2500,
      avgLatencyMs: 12,
      ioLocalitySupport: false,
      rdmaSupport: false,
      color: '#CD7F32',
    },
  ];

  constructor(
    private readonly fsm: MigrationStateMachine,
    private readonly scoring: ScoringSystem,
    private readonly checkpoints: CheckpointResumeSystem,
    private readonly quizGate: () => Promise<{ passed: boolean; pct: number }>,
  ) {}

  attachEnemyProbe(fn: () => number): void {
    this.getAliveEnemies = fn;
  }

  attachEnemyClear(fn: () => void): void {
    this.clearAllEnemies = fn;
  }

  private setObjective(text: string): void {
    uiStore.patchHud({ objective: text });
  }

  get stage(): 'idle' | 'awaiting-scan' | 'awaiting-network' | 'awaiting-storage' | 'awaiting-cutover' | 'running' | 'done' {
    if (!this.task) return 'idle';
    const s = this.task.state;
    if (s === 'IDLE') return 'awaiting-scan';
    if (s === 'COMPATIBILITY_CHECK' || s === 'NETWORK_MAPPING') return 'awaiting-network';
    if (s === 'STORAGE_MAPPING') return 'awaiting-storage';
    if (s === 'PRE_SNAPSHOT') return 'awaiting-cutover';
    if (s === 'COMPLETED' || s === 'FAILED') return 'done';
    return 'running';
  }

  /** 阶段 1+2：登录 + 扫描 + 兼容性报告 */
  async onCommandConsole(): Promise<void> {
    if (this.stage !== 'idle' && this.stage !== 'awaiting-scan') {
      UIManager.toast('info', '当前阶段不需要回到指挥台 vCenter 控制台');
      return;
    }
    if (!this.task) {
      this.task = this.fsm.createTask('vm-1000', 'vm-db-01', 60);
      uiStore.patchHud({ state: this.task.state });
    }
    this.setObjective('在 UI 中输入 vCenter 凭据');
    const cred = await UIManager.showVCenterLoginPanel();
    this.fsm.transition(this.task.id, 'ENV_SCAN');
    uiStore.patchHud({ state: 'ENV_SCAN' });

    uiStore.openScanProgress();
    const env = await this.envScan.execute(cred);
    uiStore.closeScanProgress();
    this.envResult = env;
    await UIManager.showScanResultsPanel(env);

    // 兼容性检查
    this.fsm.transition(this.task.id, 'COMPATIBILITY_CHECK');
    uiStore.patchHud({ state: 'COMPATIBILITY_CHECK' });
    await this.compat.execute(env.vms);
    const issues = env.vms
      .filter((v) => v.snapshotExists)
      .map((v) => ({
        vmName: v.name,
        severity: 'warn' as const,
        message: '存在未合并的快照，建议合并后再迁移（不阻塞）。',
      }));
    await UIManager.showCompatibilityReport(env.vms, issues);

    this.fsm.transition(this.task.id, 'NETWORK_MAPPING');
    uiStore.patchHud({ state: 'NETWORK_MAPPING' });
    this.setObjective('前往 [网络间] 与网络控制台交互（左侧走廊尽头）');
    UIManager.toast('info', '前往网络间配置 vSwitch → Bridge 映射');
  }

  /** 阶段 3：网络映射 */
  async onNetworkConsole(): Promise<void> {
    // 自动引导：前置步骤未完成时使用模拟数据就地初始化，无需先完成指挥台流程
    if (!this.task) {
      this.task = this.fsm.createTask('vm-1000', 'vm-db-01', 60);
    }
    if (!this.envResult) {
      UIManager.toast('info', '自动扫描源端环境（模拟数据）…');
      this.envResult = await this.envScan.execute({
        host: 'vcenter.local',
        port: 443,
        username: 'administrator@vsphere.local',
        password: 'auto',
      });
    }
    // 将 FSM 从任意前置状态快速推进到 NETWORK_MAPPING
    if (this.task.state === 'IDLE') this.fsm.transition(this.task.id, 'ENV_SCAN');
    if (this.task.state === 'ENV_SCAN') this.fsm.transition(this.task.id, 'COMPATIBILITY_CHECK');
    if (this.task.state === 'COMPATIBILITY_CHECK') this.fsm.transition(this.task.id, 'NETWORK_MAPPING');
    uiStore.patchHud({ state: this.task.state });
    if (this.task.state !== 'NETWORK_MAPPING') {
      UIManager.toast('info', '网络映射阶段已完成或尚未到达');
      return;
    }
    const sources: VSwitchNode[] = this.envResult.networks.map((n, i) => ({
      id: `vsw-${i}`,
      name: `vSwitch${i}`,
      portGroups: [n.name],
      vlanIds: n.vlanId ? [n.vlanId] : [],
      position3D: [-5, 1, i - 1],
      connected: false,
    }));
    const targets: BridgeNode[] = sources.map((_, i) => ({
      id: `br-${i}`,
      name: `brbond${i}`,
      type: 'distributed',
      availableBandwidthGbps: 10,
      position3D: [5, 1, i - 1],
    }));
    this.networkPhase = new NetworkMappingPhase(sources, targets);
    const { mappings } = await UIManager.showNetworkMappingPanel(sources, targets);
    // 复刻到阶段引擎内以触发校验/事件
    for (const m of mappings) {
      const src = sources.find((s) => s.name === m.sourceVSwitch);
      const tgt = targets.find((t) => t.name === m.targetBridgeName);
      if (src && tgt) this.networkPhase.attemptMapping(src.id, tgt.id);
    }
    this.task.networkMapping = mappings[0] ?? null;
    this.fsm.transition(this.task.id, 'STORAGE_MAPPING');
    uiStore.patchHud({ state: 'STORAGE_MAPPING' });
    this.setObjective('前往 [存储间] 与存储控制台交互（右侧走廊尽头）');
    UIManager.toast('info', '网络映射完成，前往存储间');
  }

  /** 阶段 4：存储映射 */
  async onStorageConsole(): Promise<void> {
    if (!this.task || !this.envResult) {
      UIManager.toast('warn', '请先完成前置步骤');
      return;
    }
    if (this.task.state !== 'STORAGE_MAPPING') {
      UIManager.toast('info', '存储映射阶段不在此时');
      return;
    }
    const primary = this.envResult.vms[0];
    this.primaryVm = { ...primary, workloadType: 'DATABASE' };
    this.storagePhase = new StorageMappingPhase(this.storagePools);
    const submission = await UIManager.showStorageMappingPanel(this.primaryVm, this.storagePools);
    const { mapping, warning } = this.storagePhase.assign(this.primaryVm, submission.poolId, {
      ioLocality: submission.ioLocality,
      rdma: submission.rdma,
    });
    this.task.storageMapping = mapping;
    this.task.storageWarning = warning;
    if (submission.ioLocality) this.scoring.apply('USED_IO_LOCALITY');
    if (submission.rdma) this.scoring.apply('USED_RDMA');
    if (!warning) this.scoring.apply('PERFECT_STORAGE_MAPPING');
    if (warning?.type === 'PERFORMANCE_DOWNGRADE') this.scoring.apply('WRONG_STORAGE_TIER');
    uiStore.patchHud({ score: this.currentScore() });

    this.fsm.transition(this.task.id, 'PRE_SNAPSHOT');
    uiStore.patchHud({ state: 'PRE_SNAPSHOT' });
    this.setObjective('返回 [指挥台] 启动切换控制台');
    UIManager.toast('info', '存储映射完成，回到指挥台启动切换');
  }

  /** 阶段 5+6+7+8：同步/驱动/切换/验证 */
  async onCutoverConsole(): Promise<void> {
    if (!this.task || !this.envResult) {
      UIManager.toast('warn', '尚未完成前置配置');
      return;
    }
    if (this.task.state !== 'PRE_SNAPSHOT') {
      UIManager.toast('info', '切换阶段不在此时');
      return;
    }
    const primary = this.envResult.vms[0];
    this.setObjective('全量同步进行中…');
    this.fsm.transition(this.task.id, 'FULL_SYNC');
    uiStore.patchHud({ state: 'FULL_SYNC' });
    uiStore.openMigrationViz('FULL_SYNC', primary.name);
    uiStore.pushMigrationVizLog('info', `开始全量同步 → 目标 VM: ${primary.name}`);
    uiStore.pushMigrationVizLog('info', `磁盘总量: ${primary.disks.reduce((s, d) => s + d.capacityGB, 0).toFixed(0)} GB · OS: ${primary.guestOS}`);

    const sync = new DataSyncPhase();
    sync.start(this.task, 2000, 200);
    // 挑战事件：同步进度到 30% 时触发
    let challengeFired = false;
    let nextMilestone = 10;
    let lastIncrementalRounds = 0;
    const progressSub = EventBus.on('migration:progress', ({ progress }: { progress: MigrationTask['progress'] }) => {
      uiStore.patchHud({
        fullSyncPercent: progress.fullSyncPercent,
        incrementalRounds: progress.incrementalRounds,
      });
      uiStore.patchMigrationViz({
        progress: {
          fullSyncPercent: progress.fullSyncPercent,
          dataTransferredGB: progress.dataTransferredGB,
          dataTotalGB: progress.dataTotalGB,
          transferSpeedMbps: progress.transferSpeedMbps,
          etaSeconds: progress.etaSeconds,
          incrementalRounds: progress.incrementalRounds,
        },
      });

      if (progress.incrementalRounds > lastIncrementalRounds) {
        lastIncrementalRounds = progress.incrementalRounds;
        uiStore.pushMigrationVizLog('info', `完成第 ${progress.incrementalRounds} 轮增量同步`);
      }

      // 每 10% 一条描述性日志
      const SYNC_MILESTONES: Record<number, string> = {
        10: '传输 MBR / 分区表',
        20: '写入系统分区基础块',
        30: '系统盘传输过半',
        40: '数据卷块传输中',
        50: '完成基础数据 50%',
        60: '数据卷写入中',
        70: '传输进入收尾阶段',
        80: '同步率 >80%，启动脏块追踪',
        90: '全量接近完成，等待最终清场',
        100: '全量同步 100% 完成',
      };
      while (progress.fullSyncPercent >= nextMilestone && nextMilestone <= 100) {
        const msg = SYNC_MILESTONES[nextMilestone] ?? `全量同步 ${nextMilestone}%`;
        uiStore.pushMigrationVizLog('info', `${nextMilestone}% · ${msg}`);
        nextMilestone += 10;
      }

      if (!challengeFired && progress.fullSyncPercent >= 30 && progress.fullSyncPercent < 80) {
        challengeFired = true;
        void this.runChallenge();
      }
    });
    await new Promise<void>((resolve) => {
      let warnedHoldout = false;
      let holdoutSince = 0; // 玩家被卡住的起始时间（ms）
      const sub = EventBus.on('migration:progress', ({ progress }: { progress: MigrationTask['progress'] }) => {
        if (progress.fullSyncPercent >= 90) {
          // 同时要求：全部竞品突击队已清除，否则提示并等待
          const aliveEnemies = this.getAliveEnemies();
          if (aliveEnemies > 0) {
            const now = Date.now();
            if (!warnedHoldout) {
              warnedHoldout = true;
              holdoutSince = now;
              UIManager.toast('warn', `⚠ 还有 ${aliveEnemies} 名敌人未清除，全量同步冻结在 ${Math.floor(progress.fullSyncPercent)}%`);
              uiStore.patchMigrationViz({
                blocker: {
                  type: 'ENEMIES_REMAIN',
                  message: `等待清场：剩余 ${aliveEnemies} 名竞品突击队`,
                  remainingEnemies: aliveEnemies,
                },
              });
              uiStore.pushMigrationVizLog('warn', `同步受阻：剩余 ${aliveEnemies} 名敌人未清除`);
              synthAudio.speak('仍有敌方厂商突击队未清除，请全部击毙再继续同步。', { priority: true });
            }
            uiStore.patchMigrationViz({
              blocker: {
                type: 'ENEMIES_REMAIN',
                message: `等待清场：剩余 ${aliveEnemies} 名竞品突击队`,
                remainingEnemies: aliveEnemies,
              },
            });
            // 安全网：若玩家僵持超过 25 秒（说明剩余敌人可能不可达），强制清场放行
            if (now - holdoutSince > 25_000) {
              UIManager.toast('info', `自动清除剩余 ${aliveEnemies} 名不可达敌人，放行迁移流程`);
              uiStore.pushMigrationVizLog('warn', `安全网触发：自动清除 ${aliveEnemies} 名不可达敌人`);
              this.clearAllEnemies();
              sub();
              resolve();
            }
            return;
          }
          uiStore.patchMigrationViz({
            blocker: { type: 'NONE', message: '', remainingEnemies: null },
          });
          uiStore.pushMigrationVizLog('success', '清场完成，全量同步继续推进');
          sub();
          resolve();
        }
      });
    });
    sync.stop();
    progressSub();
    this.checkpoints.saveCheckpoint(this.task);

    this.setObjective('增量同步中…');
    this.fsm.transition(this.task.id, 'INCREMENTAL_SYNC');
    uiStore.patchHud({ state: 'INCREMENTAL_SYNC' });
    uiStore.patchMigrationViz({
      phase: 'INCREMENTAL_SYNC',
      blocker: { type: 'NONE', message: '', remainingEnemies: null },
    });
    uiStore.pushMigrationVizLog('info', '进入增量同步：仅传输变更数据');
    await sync.runIncrementalRounds(this.task);
    uiStore.patchMigrationViz({
      phase: 'PRE_QUIZ_WAIT',
      blocker: { type: 'QUIZ_NOT_STARTED', message: '增量完成，等待进入迁移知识考核', remainingEnemies: null },
    });
    uiStore.pushMigrationVizLog('success', '增量同步完成，进入切换前验证');

    // —— Quiz Gate：实战迁移知识考核，击退所有竞品后必须先通过 ——
    this.setObjective('迁移知识考核中…');
    uiStore.patchMigrationViz({ phase: 'QUIZ_RUNNING' });
    uiStore.pushMigrationVizLog('info', '开始迁移知识考核');
    synthAudio.speak(
      '敌方竞品突击队已清除。在执行停机切换前，进入 SMTX 迁移知识考核，答对 80% 以上方可继续。',
      { priority: true },
    );
    const quizResult = await this.quizGate();
    if (quizResult.passed) {
      this.scoring.apply('USED_CHECKPOINT_RESUME'); // 复用已有 key 作为"考核通过"加分项
      UIManager.toast('info', `✓ 知识考核通过（${Math.round(quizResult.pct * 100)}%），继续切换流程`);
      uiStore.pushMigrationVizLog('success', `考核通过：${Math.round(quizResult.pct * 100)}%`);
    } else {
      UIManager.toast('warn', `△ 考核 ${Math.round(quizResult.pct * 100)}%，未达标但仍将继续（会扣分）`);
      uiStore.pushMigrationVizLog('warn', `考核未达标：${Math.round(quizResult.pct * 100)}%`);
    }

    this.setObjective('注入 VirtIO 驱动…');
    this.fsm.transition(this.task.id, 'DRIVER_INJECTION');
    uiStore.patchHud({ state: 'DRIVER_INJECTION' });
    const driver = new DriverInjectionPhase();
    const plan = driver.planFor(primary.guestOS, primary.moRef);
    await driver.execute(this.task, plan);

    this.setObjective('切换中…');
    this.fsm.transition(this.task.id, 'CUTOVER_READY');
    this.fsm.transition(this.task.id, 'CUTOVER_EXECUTING');
    uiStore.patchHud({ state: 'CUTOVER_EXECUTING' });
    const director = new CutoverDirector();
    await director.executeCutover(this.task);

    this.fsm.transition(this.task.id, 'POST_CHECK');
    uiStore.patchHud({ state: 'POST_CHECK' });
    const pc = new PostCheckPhase();
    await pc.runAuto();

    this.fsm.transition(this.task.id, 'COMPLETED');
    uiStore.patchHud({ state: 'COMPLETED' });
    this.scoring.apply('ZERO_DOWNTIME');
    this.scoring.apply('AGENTLESS_AWARENESS');
    const breakdown = this.scoring.finalize();
    uiStore.patchHud({ score: breakdown.total });
    this.setObjective('迁移完成！');
    UIManager.showScorePanel(breakdown);
    console.log('[SmartX] Migration completed. Score:', breakdown);

    // 上报排行榜（异步、失败不阻塞）
    if (apiClient.hasBackend()) {
      const playerName =
        localStorage.getItem('smartx.playerName') ?? window.prompt('上传到排行榜的玩家名：', 'Player') ?? 'Player';
      localStorage.setItem('smartx.playerName', playerName);
      const durationMs = Date.now() - APP_START_TIME;
      apiClient
        .submitLeaderboard({
          playerName,
          score: breakdown.total,
          durationMs,
        })
        .then(async (r) => {
          uiStore.pushToast('info', `🏆 已登榜 · 当前第 ${r.rank} 名`);
          try {
            const board = await apiClient.fetchLeaderboard(10);
            uiStore.setLeaderboard(board.entries, r.rank);
          } catch (e) {
            uiStore.setLeaderboardError(String(e));
          }
        })
        .catch((e) => {
          console.warn('[SmartX] leaderboard upload failed:', e);
          uiStore.pushToast('warn', '排行榜上报失败：' + String(e));
        });
    }
  }

  private async runChallenge(): Promise<void> {
    const ch = SYNC_CHALLENGES[0];
    EventBus.emit('ui:show_sync_challenge', ch);
    const resp = await UIManager.showSyncChallengeModal(ch);
    if (resp.isSmartXWay) {
      this.scoring.apply('USED_CHECKPOINT_RESUME');
    } else if (resp.id === 'restart_transfer') {
      this.scoring.apply('MANUAL_RESTART_TRANSFER');
    }
    uiStore.patchHud({ score: this.currentScore() });
    UIManager.toast(resp.isSmartXWay ? 'info' : 'warn', resp.effect);
  }

  private currentScore(): number {
    return this.scoring.finalize().total;
  }
}

/** === 启动 === */
async function bootstrap(): Promise<void> {
  const container = document.getElementById('app')!;
  const uiRoot = document.getElementById('ui-root')!;
  mountReactUi(uiRoot);

  const { renderer, composer, scene, camera, vignettePass } = setupScene(container);
  const collision = new CollisionSystem();

  // 系统
  new DataCenterAudio();
  const scoring = new ScoringSystem();
  const checkpoints = new CheckpointResumeSystem();
  const fsm = new MigrationStateMachine();

  // —— Quiz Gate：返回 Promise<{passed, pct}> ——
  const quizGate = (): Promise<{ passed: boolean; pct: number }> => {
    const session = new QuizSession(MIGRATION_QUIZ);
    const toUiQ = (q: QuizQuestion) => ({ id: q.id, stem: q.stem, options: q.options });
    const first = session.current();
    if (!first) return Promise.resolve({ passed: true, pct: 1 });
    uiStore.openQuiz(
      '迁移知识考核 · CUTOVER EXAM',
      toUiQ(first),
      0,
      session.total(),
    );
    return new Promise((resolve) => {
      let lastCorrectKey = first.answer;
      const onAnswer = (e: Event): void => {
        const { key } = (e as CustomEvent).detail;
        const q = session.current();
        if (!q) return;
        lastCorrectKey = q.answer;
        const r = session.answer(key);
        uiStore.setQuizFeedback({
          correct: r.correct,
          explanation: r.explanation,
          chosenKey: key,
          correctKey: lastCorrectKey,
        });
      };
      const onNext = (): void => {
        const nextQ = session.current();
        if (nextQ) {
          uiStore.setQuizQuestion(toUiQ(nextQ), session.currentIndex());
        } else {
          uiStore.setQuizFinal(session.score());
        }
      };
      const onClose = (): void => {
        document.removeEventListener('smartx:quiz_answer', onAnswer);
        document.removeEventListener('smartx:quiz_next', onNext);
        document.removeEventListener('smartx:quiz_close', onClose);
        const s = session.score();
        uiStore.closeQuiz();
        resolve({ passed: s.pct >= 0.8, pct: s.pct });
      };
      document.addEventListener('smartx:quiz_answer', onAnswer);
      document.addEventListener('smartx:quiz_next', onNext);
      document.addEventListener('smartx:quiz_close', onClose);
    });
  };

  const flow = new MigrationFlowController(fsm, scoring, checkpoints, quizGate);

  const player = new PlayerController(camera, collision);
  player.state.position.set(0, 0, 3);
  const bob = new HeadBobSystem();
  const tools = new ToolSystem();
  const interaction = new InteractionSystem(player);
  interaction.attach();

  // 构建教程关
  const level = buildTutorialLevel(scene, collision, {
    onCommandConsole: () => void flow.onCommandConsole(),
    onNetworkConsole: () => void flow.onNetworkConsole(),
    onStorageConsole: () => void flow.onStorageConsole(),
    onCutoverConsole: () => void flow.onCutoverConsole(),
  });
  const zoneManager = new ZoneManager(level.zones);
  player.registerInteractable(level.consoles.command);
  player.registerInteractable(level.consoles.network);
  player.registerInteractable(level.consoles.storage);
  player.registerInteractable(level.consoles.cutover);

  // === CS 风格场景装饰 + Bug 敌人 + 武器 viewmodel + 射击系统 ===
  scene.add(camera); // 让 viewmodel 能以相机为父节点渲染
  const decor = buildSceneDecor(scene, collision);
  const realistic = buildRealisticDataCenter(scene, collision);

  // —— 玩家生命值 ——
  const playerHealth = new PlayerHealth({ maxHp: 100 });

  const bugs = new BugEnemies(scene, [], {
    onHitPlayer: (dmg) => playerHealth.takeDamage(dmg),
    getPlayerPosition: () => player.state.position,
    isPlayerInvulnerable: () => playerHealth.isInvulnerable(),
    onEnemyDamaged: (pos, killed) => {
      realistic.emitSmoke(pos.x, pos.y + 1.0, pos.z, killed ? 14 : 4);
    },
  });
  bugs.setObstacles(realistic.rackMeshes);
  bugs.setCollisionCheck((pos, r) => collision.collides(pos, r));
  flow.attachEnemyProbe(() => bugs.aliveCount);
  flow.attachEnemyClear(() => bugs.clearAll());

  // 初始敌人在玩家点击"READY"后才 spawn（避免 briefing/intro 期间被攻击致死后清场）
  // spawnWave 在 smartx:start_mission 里触发（见下方监听器）

  // 启用 SWAT 敌人模型（带 Idle_Gun / Idle_Gun_Pointing / Gun_Shoot / Run_Shoot 动画）
  BugEnemies.preloadSoldier().then(() => bugs.upgradeToGLB()).catch((e) => {
    console.warn('[BugEnemies] SWAT preload failed, fallback to procedural enemies', e);
  });

  // 调试用：暴露敌人和玩家供探针读取
  (window as unknown as { __debug: unknown }).__debug = { bugs, player, scene, playerHealth };

  // R8.2: 优先加载 smg.glb 真实武器模型，失败时退回程序化几何体
  const viewmodel = await WeaponViewmodel.loadAsync('/assets/weapons/smg.glb');
  viewmodel.attachTo(camera);

  // ─── ADS（瞄准镜） ───
  const ads = new AdsSystem(camera, viewmodel, () => document.pointerLockElement === renderer.domElement);
  ads.bindSprintProbe(() => player.state.isSprinting);
  // 阻止右键菜单（ADS 占用右键）
  renderer.domElement.addEventListener('contextmenu', (e) => e.preventDefault());

  // ─── 抛壳系统（场景层，黄铜 PBR + 简易物理） ───
  const shells = new ShellEjection(scene);

  // ─── 场景级 muzzle light（layer 0，瞬时照亮机柜与墙壁） ───
  // viewmodel 自带的 muzzle PointLight 在 layer 1，只照武器；
  // 这盏在 layer 0 的瞬时灯让"开火被周围物体照亮"成立——MW 的标志性视觉。
  const sceneMuzzle = new THREE.PointLight(0xffb866, 0, 7.5, 2.0);
  sceneMuzzle.position.set(0, 0.0, -0.30);
  camera.add(sceneMuzzle);
  let sceneMuzzleTimer = 0;
  EventBus.on('weapon:fire', () => {
    sceneMuzzleTimer = 0.062; // 62ms 闪光寿命
    shells.ejectAt(camera);
  });

  // ─── 体积大气：天花板 god rays + 浮尘 motes ───
  // 几个机柜顶部 + 中央过道做 light shafts
  const beamPositions: THREE.Vector3[] = [
    new THREE.Vector3(-8, 4.6, -4),
    new THREE.Vector3(8, 4.6, -4),
    new THREE.Vector3(0, 4.6, 6),
    new THREE.Vector3(-12, 4.6, 8),
    new THREE.Vector3(12, 4.6, 8),
    new THREE.Vector3(0, 4.6, -10),
  ];
  const atmosphere = new VolumetricAtmosphere(scene, beamPositions, {
    beamColor: 0x6ec1ff,
    beamIntensity: 0.22,
    beamHeight: 4.6,
    moteCount: 1200,
    bounds: { min: new THREE.Vector3(-22, 0, -22), max: new THREE.Vector3(22, 4.6, 22) },
  });

  // ─── 机房卷积混响（程序合成 IR，无外部资产） ───
  const roomReverb = new RoomReverb();
  // SynthAudio 是懒初始化的；首次 play 之后才有 ctx。
  // 在玩家点击页面（pointerlock）之后尝试 attach，确保音频上下文已就绪。
  let reverbAttached = false;
  const tryAttachReverb = (): void => {
    if (reverbAttached) return;
    if (roomReverb.attach(synthAudio, { dry: 0.85, wet: 0.20, ir: { durationSec: 1.5, rt60Sec: 1.1 } })) {
      reverbAttached = true;
    }
  };
  document.addEventListener('pointerlockchange', tryAttachReverb);
  // 兜底：5 秒后再尝试一次（万一玩家先开 UI 再走动）
  setTimeout(tryAttachReverb, 5000);

  const shooting = new ShootingSystem(
    camera,
    scene,
    player,
    bugs,
    viewmodel,
    (ammo, reserve, reloading, weapon) =>
      uiStore.patchCombat({
        ammo,
        reserve,
        reloading,
        weaponName: weapon.name,
        weaponId: weapon.id,
      }),
    (kills) => uiStore.patchCombat({ kills }),
    (info) => {
      uiStore.triggerHitMarker(info.kind);
      // \u5c06\u4e16\u754c\u70b9\u6295\u5f71\u5230 NDC \u00b7 \u53d1\u5e03\u98d8\u5b57\u4e8b\u4ef6\uff0cUI \u5c42\u63a5\u6536
      try {
        const v = info.worldPoint.clone().project(camera);
        const sx = (v.x * 0.5 + 0.5) * window.innerWidth;
        const sy = (-v.y * 0.5 + 0.5) * window.innerHeight;
        if (Number.isFinite(sx) && Number.isFinite(sy) && v.z < 1) {
          document.dispatchEvent(
            new CustomEvent('smartx:damage_popup', {
              detail: { x: sx, y: sy, amount: info.damage, kind: info.kind },
            }),
          );
        }
      } catch {
        /* ignore projection errors */
      }
    },
    () => document.pointerLockElement === renderer.domElement,
    (remaining) => {
      uiStore.pushLog('success', `✓ VM 已标记，剩余 ${remaining}`);
      if (remaining === 0 && narrator.currentAct === 'ACT3_SCAN') {
        narrator.completeCurrent();
        uiStore.pushLog('success', '◆ 所有 VM 已标记，回到指挥台启动网络配置');
      }
    },
  );
  shooting.attach();

  // ··· 子弹弹孔系统
  const bulletImpact = new BulletImpactSystem(scene);
  shooting.setImpactSystem(bulletImpact);
  // 环境命中目标：机柜、控制台、vCenter 屏幕（vCenter 屏作为"屏幕"类型显示裂痕）
  const screenTargets: THREE.Object3D[] = [];
  if (realistic.vcenterScreen) screenTargets.push(realistic.vcenterScreen);
  const envTargets: THREE.Object3D[] = [
    ...realistic.rackMeshes,
    level.consoles.command,
    level.consoles.network,
    level.consoles.storage,
    level.consoles.cutover,
    ...screenTargets,
  ];
  shooting.setEnvironmentTargets(envTargets, screenTargets);

  // ··· 下一步指引（悬浮箭头 + 文字铭牌）
  const guidance = new GuidanceMarker(scene);

  // ··· 手雷系统
  const grenades = new GrenadeSystem(
    scene,
    camera,
    bugs,
    (stock, max) => uiStore.patchCombat({ grenadeStock: stock, grenadeMax: max }),
    (n) => uiStore.pushLog('success', `💥 手雷清除 ${n} 个 Bug`),
    (dmg) => {
      uiStore.pushLog('warn', `⚠ 手雷自伤 ${dmg} 点`);
      playerHealth.takeDamage(dmg);
    },
  );
  grenades.attach();

  // ··· 补给拾取系统：医疗包/护甲板/弹药盒/手雷补给
  const pickups = new PickupSystem(
    scene,
    () => player.state.position,
    {
      onHealth: (n) => playerHealth.heal(n),
      onArmor: (n) => playerHealth.addArmor(n),
      onAmmo: (n) => shooting.addReserve(n),
      onGrenade: (n) => grenades.addStock(n),
    },
  );
  // 起点周围的固定补给站（指挥台南侧）
  pickups.spawn('HEALTH', [-5.5, 0, 4.5]);
  pickups.spawn('ARMOR', [5.5, 0, 4.5]);
  pickups.spawn('AMMO', [0, 0, 5.0]);

  // R6 收尾：固定补给点周期性重生（每 35 秒检查一次，已存在则跳过）
  const RESPAWN_SLOTS: { kind: 'HEALTH' | 'ARMOR' | 'AMMO'; pos: [number, number, number] }[] = [
    { kind: 'HEALTH', pos: [-5.5, 0, 4.5] },
    { kind: 'ARMOR', pos: [5.5, 0, 4.5] },
    { kind: 'AMMO', pos: [0, 0, 5.0] },
  ];
  setInterval(() => {
    if (uiStore.snapshot.health.dead) return;
    if (uiStore.snapshot.briefing.open) return;
    for (const slot of RESPAWN_SLOTS) {
      if (!pickups.hasNear(slot.pos, 1.6, slot.kind)) {
        pickups.spawn(slot.kind, slot.pos);
      }
    }
  }, 35000);

  // 镜头震动监听（手雷爆炸近距离触发）
  let camShake = { intensity: 0, timeLeft: 0, total: 0 };
  EventBus.on(
    'camera:shake',
    (e: { intensity: number; durationMs: number }) => {
      const dur = (e.durationMs ?? 350) / 1000;
      // 取最大值，避免短间隔内多次叠加导致眩晕
      if (e.intensity > camShake.intensity || camShake.timeLeft <= 0) {
        camShake = { intensity: e.intensity, timeLeft: dur, total: dur };
      }
    },
  );

  // ··· 任务物件：部署台（Act1） + VM 全息影像（Act3）
  const deployPad = new DeployPad(scene, 3.0, 0.5);
  const vmHolograms: VMHologram[] = [
    { position: [-1.5, 1.4, -4] as [number, number, number], label: 'win-db-01' },
    { position: [1.8, 1.4, -4.5] as [number, number, number], label: 'linux-web-02' },
    { position: [-6.5, 1.4, -1.2] as [number, number, number], label: 'win-app-03' },
    { position: [6.2, 1.4, -0.8] as [number, number, number], label: 'linux-log-04' },
    { position: [0.0, 1.4, -7.5] as [number, number, number], label: 'bsd-cache-05' },
  ].map((s) => new VMHologram(scene, s));
  shooting.setVMTargets(vmHolograms);

  // ··· 任务语音解说员
  const narrator = new MissionNarrator();

  // ··· 教学提示系统（首次操作 / SOP 关键节点）
  const tutorial = new TutorialPrompts();
  tutorial.start();

  // ··· 解说密度增强：监听迁移进度 / 错误 / 关键阶段事件，按 key 去重投放语音 + 日志
  EventBus.on('migration:progress', ({ progress }: { progress: { fullSyncPercent: number; incrementalRounds: number } }) => {
    const p = progress.fullSyncPercent;
    if (p >= 25) narrator.nudge('sync_25', '全量同步 25%。VDDK 通道稳定，磁盘基础块已写入目标 ELF 卷。');
    if (p >= 50) narrator.nudge('sync_50', '全量同步过半。CBT 已开启，每一轮快照都会记录脏块以缩短切换窗口。');
    if (p >= 75) narrator.nudge('sync_75', '全量同步 75%。注意：90% 后若仍有竞品突击队存活，同步将被冻结。');
    if (p >= 100) narrator.nudge('sync_100', '全量同步完成。准备进入增量阶段，差异块同步开始。');
    if (progress.incrementalRounds >= 1) {
      narrator.nudge('inc_1', '增量第一轮完成。脏数据"块"会以紫色突击手形态出现，优先清除。');
    }
    if (progress.incrementalRounds >= 3) {
      narrator.nudge('inc_3', '增量第三轮。停机窗口已收敛到秒级，可考虑进入切换考核。');
    }
  });

  // 阶段变更后追加 SOP 二级解说
  EventBus.on('migration:stateChange', ({ next }: { next: string }) => {
    switch (next) {
      case 'COMPATIBILITY_CHECK':
        narrator.nudge('check_warn', '兼容性检查启动：未合并快照只是 WARN，UEFI / 虚拟硬件 v17 才会阻塞迁移。');
        break;
      case 'NETWORK_MAPPING':
        narrator.nudge('net_vlan', '网络映射进行中。请保留 VLAN 与 MTU，避免切换后业务网络中断。');
        break;
      case 'STORAGE_MAPPING':
        narrator.nudge('stg_iolocality', '存储映射进行中。数据库类负载请勾选 I/O Locality 与 RDMA，以获得最低延迟。');
        break;
      case 'PRE_SNAPSHOT':
        narrator.nudge('pre_snap', '基线快照创建中。这是切换前最重要的一致性保障，请勿手动停止 VMware 业务。');
        break;
      case 'DRIVER_INJECTION':
        narrator.nudge('virtio', '注入 VirtIO 驱动。Windows VM 必须注入磁盘 + 网卡两套驱动，否则启动会蓝屏。');
        break;
      case 'CUTOVER_EXECUTING':
        narrator.nudge('cutover_exec', '业务切换执行中：①最后一轮增量 ②源端关机 ③驱动注入 ④目标端开机 ⑤业务自检。');
        break;
      case 'POST_CHECK':
        narrator.nudge('postcheck', '迁移后校验进行中。检查项：磁盘卷在线 / 网络通 / 服务自启动 / 业务延迟。');
        break;
    }
  });

  // 玩法事件 → 战术解说（首次触发，无侵入）
  EventBus.on('player:died', () => {
    narrator.nudge('died_tip', '操作员倒地。SmartX 部署版没有真死机制，按 SPACE 复活。', { logLevel: 'warn' });
  });
  EventBus.on('grenade:explode', ({ kills }: { kills: number }) => {
    if (kills >= 3) narrator.nudge('grenade_multi', '一发手雷三杀！高价值清场技巧已记录。');
  });

  // 工具切换：数字键 1-6
  window.addEventListener('keydown', (e) => {
    const n = parseInt(e.key, 10);
    if (!Number.isNaN(n) && n >= 1 && n <= 6) {
      tools.equipBySlot(n);
      player.setEquippedTool(tools.current?.type ?? null);
    }
    if (e.code === 'Escape') {
      document.exitPointerLock?.();
    }
    // 难度切换：- = / 0 (BracketLeft / BracketRight / Backslash 也支持)
    if (e.code === 'Minus' || e.code === 'BracketLeft') {
      bugs.setDifficulty('dumb');
      uiStore.pushToast('info', '敌人难度：新手（笨）');
    } else if (e.code === 'Equal' || e.code === 'BracketRight') {
      bugs.setDifficulty('normal');
      uiStore.pushToast('info', '敌人难度：老兵（一般）');
    } else if (e.code === 'Digit0' || e.code === 'Backslash') {
      bugs.setDifficulty('elite');
      uiStore.pushToast('warn', '敌人难度：精锐（玩家级）');
    }
    // L 键查看排行榜
    if (e.code === 'KeyL') {
      if (apiClient.hasBackend()) {
        uiStore.setLeaderboardLoading();
        apiClient
          .fetchLeaderboard(10)
          .then((board) => uiStore.setLeaderboard(board.entries, null))
          .catch((err) => uiStore.setLeaderboardError(String(err)));
      } else {
        uiStore.pushToast('warn', '排行榜需要后端服务');
      }
    }
    // R 键复活：仅在死亡时有效
    if (e.code === 'KeyR' && playerHealth.isDead()) {
      bugs.clearAll();
      playerHealth.revive({
        reset: () => {
          player.state.position.set(0, 0, 3);
          player.state.velocity.set(0, 0, 0);
        },
      });
      renderer.domElement.requestPointerLock?.();
    }
  });

  // HUD 绑定
  EventBus.on('interaction:hover', ({ target }: { target: { label: string } | null }) => {
    uiStore.patchHud({ hoverHint: target?.label ?? null });
  });
  EventBus.on('migration:stateChange', ({ next }: { next: MigrationTask['state'] }) => {
    uiStore.patchHud({ state: next });
  });

  // 当 UI 模态面板打开/关闭时自动释放 / 重新获取 Pointer Lock
  let wasModalOpen = false;
  uiStore.subscribe((s) => {
    const open = uiStore.isModalOpen();
    if (open && !wasModalOpen) {
      document.exitPointerLock?.();
    } else if (!open && wasModalOpen) {
      // 面板关闭后重新请求锁定（非简报/死亡状态才锁）
      if (!s.briefing.open && !s.health.dead) {
        renderer.domElement.requestPointerLock?.();
      }
    }
    wasModalOpen = open;
  });

  // 尝试与服务端建立会话
  if (apiClient.hasBackend()) {
    try {
      await apiClient.login('Player');
      socketClient.connect();
      EventBus.on('migration:created', ({ task }: { task: { id: string } }) => {
        socketClient.subscribe(task.id);
      });
      console.log('[SmartX] backend session established:', apiClient.getBaseUrl());
    } catch (err) {
      console.warn('[SmartX] backend unavailable, falling back to local sim:', err);
    }
  }

  const { getInput } = setupInput(renderer.domElement);

  // Briefing "READY" 按钮 → 请求 pointer lock + 启动音频上下文 + 进入第一幕
  document.addEventListener('smartx:start_mission', (ev) => {
    const detail = (ev as CustomEvent<{ difficulty?: 'dumb' | 'normal' | 'elite' }>).detail;
    if (detail?.difficulty) {
      bugs.setDifficulty(detail.difficulty);
      const label =
        detail.difficulty === 'dumb' ? '笨蛋'
          : detail.difficulty === 'elite' ? '玩家水平' : '一般';
      uiStore.pushToast(detail.difficulty === 'elite' ? 'warn' : 'info', `敌人难度：${label}`);
    }
    // 玩家点击 READY 后才 spawn 初始敌人（确保 briefing/intro 期间没有敌人攻击）
    if (bugs.aliveCount === 0) {
      bugs.spawnWave(decor.bugSpawns, 'normal');
      console.log(`[main] 任务开始 spawn 完成，活敌人=${bugs.aliveCount}`);
    }
    renderer.domElement.requestPointerLock?.();
    synthAudio.ensure();
    narrator.start();
  });

  // ··· Act1 部署进度：按住 F 且站在部署台上
  let lastExtraText = '';
  let wavesSpawned = { act6: false, act7: false };

  // 监听迁移 FSM 进度以刷额外波次
  EventBus.on('migration:stateChange', ({ next }: { next: MigrationTask['state'] }) => {
    if (next === 'FULL_SYNC') {
      uiStore.patchMigrationViz({ phase: 'FULL_SYNC', open: true });
    }
    if (next === 'INCREMENTAL_SYNC') {
      uiStore.patchMigrationViz({ phase: 'INCREMENTAL_SYNC', open: true });
    }
    if (next === 'FULL_SYNC' && !wavesSpawned.act6) {
      wavesSpawned.act6 = true;
      // R3：Act6 拆 3 波递进（3 dumb → 3 normal → 2 elite），波次间留喘息窗口
      // 注意：SceneDecor 已确认 z<-5 区域（机柜阵冷/热通道）玩家可达且有掩体
      // === Wave 1：起始 0s · 3 个新手，从指挥台周边涌入 ===
      const w1: BugSpawnSpec[] = [
        { position: [-3, 0, -3] },
        { position: [3, 0, -3] },
        { position: [0, 0, 2] },
      ];
      bugs.spawnWave(w1, 'normal', 'dumb');
      synthAudio.play('danger_alert');
      synthAudio.speak('警告：竞品先头小队闯入指挥台周边！', { priority: true });
      uiStore.pushLog('danger', '❗ 第 1 波（先头）：3 名新手突入');
      // R4 补给：第 1 波后期推进点 —— 机柜阵冷通道入口丢一套拍口补给引玩家推进
      window.setTimeout(() => {
        pickups.spawn('AMMO', [-2, 0, -5.5]);
        pickups.spawn('HEALTH', [2, 0, -5.5]);
      }, 4_000);

      // === Wave 2：+10s · 3 个老兵，从机柜阵冷通道 A 入口 ===
      window.setTimeout(() => {
        if (flow.stage !== 'done' && bugs.aliveCount < 8) {
          const w2: BugSpawnSpec[] = [
            { position: [-3, 0, -6] },
            { position: [0, 0, -6.5] },
            { position: [3, 0, -6] },
          ];
          bugs.spawnWave(w2, 'normal', 'normal');
          synthAudio.play('danger_alert');
          synthAudio.speak('第二波从冷通道杀过来了，注意机柜掩体！', { priority: true });
          uiStore.pushLog('danger', '❗ 第 2 波（推进）：3 名老兵从机柜阵涌入');
          // R4 补给：第 2 波后期在机柜阵深处丢护甲+手雷，鼓励玩家冲骤
          window.setTimeout(() => {
            pickups.spawn('ARMOR', [0, 0, -8.5]);
            pickups.spawn('GRENADE', [-3.2, 0, -8.5]);
          }, 5_000);
        }
      }, 10_000);

      // === Wave 3：+22s · 2 个精英，从机柜阵深处 ===
      window.setTimeout(() => {
        if (flow.stage !== 'done' && bugs.aliveCount < 6) {
          const w3: BugSpawnSpec[] = [
            { position: [-2, 0, -10] },
            { position: [2, 0, -10] },
          ];
          bugs.spawnWave(w3, 'normal', 'elite');
          synthAudio.play('danger_alert');
          synthAudio.speak('精英突击手从机柜深处出来了，小心爆头！', { priority: true });
          uiStore.pushLog('danger', '★★ 第 3 波（精英）：2 名精英从机柜深处突入');
          uiStore.pushToast('warn', '精英波来袭：尽量爆头一击毙命');
        }
      }, 22_000);
    }
    if (next === 'INCREMENTAL_SYNC' && !wavesSpawned.act7) {
      wavesSpawned.act7 = true;
      // R3：Act7 拆 2 波（脏数据），第 2 波加一个精英头领
      // === Wave 1：从左右走廊夹击（玩家容易被两侧 crossfire） ===
      const w1: BugSpawnSpec[] = [
        { position: [-7, 0, 0] },
        { position: [7, 0, 0] },
        { position: [0, 0, -4] },
      ];
      bugs.spawnWave(w1, 'dirty');
      synthAudio.speak(
        '快照生成差异数据，紫色头套为脏数据突击手，从两侧走廊包抄过来了。',
        { priority: true },
      );
      uiStore.pushLog('warn', '★ 第 1 波（脏数据）：3 名突击手从左右走廊夹击');
      grenades.addStock(2);
      // R4 补给：走廊中点各丢一个弹药盒，帮玩家顶住两侧火力
      window.setTimeout(() => {
        pickups.spawn('AMMO', [-4.5, 0, -2]);
        pickups.spawn('AMMO', [4.5, 0, -2]);
      }, 3_000);

      // === Wave 2：+12s · 2 dirty + 1 elite 头领，从机柜阵深处包抄 ===
      window.setTimeout(() => {
        if (flow.stage !== 'done' && bugs.aliveCount < 8) {
          const w2: BugSpawnSpec[] = [
            { position: [-3, 0, -9] },
            { position: [3, 0, -9] },
          ];
          bugs.spawnWave(w2, 'dirty');
          bugs.spawnWave([{ position: [0, 0, -12] }], 'dirty', 'elite');
          synthAudio.play('danger_alert');
          synthAudio.speak('脏数据头领出现，从机柜深处包抄！', { priority: true });
          uiStore.pushLog('danger', '★★ 第 2 波（包抄）：2 脏 + 1 精英头领');
        }
      }, 12_000);
    }
    if (next === 'DRIVER_INJECTION') {
      // 增量结束进入驱动注入 = 考核通过后，清场关刷新，迎接切换
      bugs.setRespawnEnabled(false);
      bugs.clearAll();
      uiStore.pushLog('info', '✓ 机房已清场，进入 VirtIO 驱动注入与切换');
      uiStore.patchMigrationViz({ phase: 'DONE' });
      uiStore.closeMigrationViz();
    }
    if (next === 'COMPLETED') {
      synthAudio.play('objective_complete');
      uiStore.closeMigrationViz();
    }
    if (next === 'FAILED') {
      uiStore.closeMigrationViz();
    }
  });

  // 渲染循环
  const clock = new THREE.Clock();
  const keyFPressed = (): boolean => {
    // 利用 input 无法特殊捕捉 F，此处单独监听
    return keysF.has;
  };
  const keysF = { has: false };
  window.addEventListener('keydown', (e) => {
    if (e.code === 'KeyF') keysF.has = true;
  });
  window.addEventListener('keyup', (e) => {
    if (e.code === 'KeyF') keysF.has = false;
  });
  let act1Done = false;
  // 预分配，避免每帧产生 GC 对象
  const _cameraWorldPos = new THREE.Vector3();
  const tick = (): void => {
    const dt = Math.min(0.1, clock.getDelta());
    player.update(dt, playerHealth.isDead()
      ? { forward: 0, strafe: 0, jump: false, sprint: false, crouch: false, mouseDX: 0, mouseDY: 0 }
      : getInput());
    zoneManager.update(player);
    bob.apply(dt, player);
    tools.tick(dt);
    interaction.update();
    const moving =
      Math.abs(player.state.velocity.x) + Math.abs(player.state.velocity.z) > 0.1;
    viewmodel.update(dt, moving, player.state.isSprinting);
    // ADS：先推进 FOV/blend，再在 viewmodel 写完位置后叠加 ADS 偏移
    ads.update(dt);
    ads.applyAdsTransform();
    // 抛壳物理 + 体积大气推进
    shells.update(dt);
    atmosphere.update(dt);
    // 场景级 muzzle light 衰减
    if (sceneMuzzleTimer > 0) {
      sceneMuzzleTimer = Math.max(0, sceneMuzzleTimer - dt);
      const k = sceneMuzzleTimer / 0.062;
      // 6.5 → 0 强度，让墙壁/机柜在开火瞬间被强烈照亮
      sceneMuzzle.intensity = k * 6.5;
    } else if (sceneMuzzle.intensity !== 0) {
      sceneMuzzle.intensity = 0;
    }
    shooting.update(dt);
    grenades.update(dt);
    bugs.update(dt);
    playerHealth.update(dt);
    pickups.update(dt);

    // 镜头震动（手雷爆炸近距离触发）：在 player.update 写入相机旋转后叠加扰动
    if (camShake.timeLeft > 0) {
      camShake.timeLeft -= dt;
      const decay = Math.max(0, camShake.timeLeft / camShake.total);
      const amp = camShake.intensity * decay * 0.06;
      camera.rotation.x += (Math.random() - 0.5) * amp;
      camera.rotation.y += (Math.random() - 0.5) * amp;
      camera.rotation.z += (Math.random() - 0.5) * amp * 0.6;
      if (camShake.timeLeft <= 0) {
        camShake.intensity = 0;
        camShake.total = 0;
      }
    }
    for (const vm of vmHolograms) vm.update(dt);

    // 机房视觉效果（LED 闪烁 + 烟雾推进）
    realistic.update(dt);

    // === 下一步指引：根据迁移阶段 + 敌情决定悬浮箭头指向 ===
    {
      const stage = flow.stage;
      let target: THREE.Object3D | null = null;
      let text = '';
      if (!act1Done) {
        // Act1：部署台
        target = deployPad.group;
        text = '踩上平台 · 按住 F 部署';
      } else if (stage === 'idle' || stage === 'awaiting-scan') {
        target = level.consoles.command;
        text = '按 E · 连接 vCenter';
      } else if (stage === 'awaiting-network') {
        target = level.consoles.network;
        text = '按 E · 配置网络映射';
      } else if (stage === 'awaiting-storage') {
        target = level.consoles.storage;
        text = '按 E · 配置存储映射';
      } else if (stage === 'awaiting-cutover') {
        target = level.consoles.cutover;
        text = '按 E · 启动切换迁移';
      }
      // 敌人还活着时箭头在任务控制台上方也显示 —— 便于战斗后直接找路
      guidance.setTarget(target, text);
      guidance.update(dt, camera.getWorldPosition(_cameraWorldPos));

      // 同步推送 2D HUD 路点（屏幕投影 + 距离 + 离屏边缘箭头）
      if (target) {
        const targetWorld = new THREE.Vector3();
        target.getWorldPosition(targetWorld);
        const distance = camera.getWorldPosition(_cameraWorldPos).distanceTo(targetWorld);
        const ndc = targetWorld.clone().project(camera);
        const onscreen = ndc.z > -1 && ndc.z < 1 && ndc.x > -1 && ndc.x < 1 && ndc.y > -1 && ndc.y < 1;
        const sx = (ndc.x * 0.5 + 0.5) * window.innerWidth;
        const sy = (-ndc.y * 0.5 + 0.5) * window.innerHeight;
        // 离屏角度：以屏幕中心为原点的方向（0 度=右、PI/2=下）
        // 当 z > 1（在相机背后）时 ndc.x/y 会反相，需要翻转
        let dx = ndc.x;
        let dy = -ndc.y;
        if (ndc.z > 1) {
          dx = -dx;
          dy = -dy;
        }
        const edgeAngle = Math.atan2(dy, dx);
        uiStore.setWaypoint({
          active: true,
          x: sx,
          y: sy,
          distance,
          label: text,
          onscreen,
          edgeAngle,
        });
      } else {
        uiStore.setWaypoint({ active: false });
      }
    }

    // Act1 部署台交互
    if (!act1Done && narrator.currentAct === 'ACT1_DEPLOY') {
      const standing = deployPad.contains(player.state.position);
      const result = deployPad.advance(dt, standing && keyFPressed());
      const extra = standing
        ? keyFPressed()
          ? `🔧 部署中··· ${Math.floor(result.percent * 100)}%`
          : '按住 F 开始部署'
        : '前往绿色部署台';
      if (extra !== lastExtraText) {
        lastExtraText = extra;
        uiStore.patchMission({ extra });
      }
      if (result.justCompleted) {
        act1Done = true;
        narrator.completeCurrent();
        uiStore.pushLog('success', '✓ SMTX 迁移工具部署完成');
        uiStore.patchMission({ extra: '' });
        setTimeout(() => narrator.enter('ACT2_VCENTER'), 1400);
      }
    }

    uiStore.patchCombat({ bugsAlive: bugs.aliveCount });
    uiStore.patchHud({
      zone: player.state.currentZone,
      stamina: player.state.staminaPercent,
      tool: tools.current?.name ?? '',
    });
    // PostFx：每帧推进 grain 时间
    vignettePass.setTime(performance.now() * 0.001);
    composer.render();
    requestAnimationFrame(tick);
  };
  tick();
}

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => void bootstrap());
  } else {
    void bootstrap();
  }
}
