/**
 * 指引标记 —— 悬浮在当前交互目标正上方的 3D 箭头 + 发光环 + 文字铭牌。
 * 用途：明确告诉玩家下一步该去哪里按什么键。
 */
import * as THREE from 'three';

export class GuidanceMarker {
  private readonly group: THREE.Group;
  private readonly arrow: THREE.Mesh;
  private readonly ring: THREE.Mesh;
  private readonly label: THREE.Mesh;
  private labelMat: THREE.MeshBasicMaterial;
  private labelTex: THREE.CanvasTexture;
  private target: THREE.Object3D | null = null;
  private accum = 0;

  constructor(scene: THREE.Scene) {
    this.group = new THREE.Group();
    this.group.visible = false;

    // 下指箭头（圆锥）—— 放大 + 隔墙可见
    const arrowGeom = new THREE.ConeGeometry(0.4, 1.0, 8);
    arrowGeom.rotateX(Math.PI); // tip 朝下
    this.arrow = new THREE.Mesh(
      arrowGeom,
      new THREE.MeshBasicMaterial({
        color: 0x00ff99,
        transparent: true,
        opacity: 0.95,
        depthTest: false,
      }),
    );
    this.arrow.position.y = 0.6;
    this.arrow.renderOrder = 999;
    this.group.add(this.arrow);

    // 发光环（脚下光圈）
    const ringGeom = new THREE.RingGeometry(0.55, 0.85, 32);
    ringGeom.rotateX(-Math.PI / 2);
    this.ring = new THREE.Mesh(
      ringGeom,
      new THREE.MeshBasicMaterial({
        color: 0x00ff99,
        transparent: true,
        opacity: 0.7,
        side: THREE.DoubleSide,
        depthTest: false,
      }),
    );
    this.ring.position.y = -1.2;
    this.ring.renderOrder = 999;
    this.group.add(this.ring);

    // 文字铭牌（CanvasTexture）—— 更大
    const { mat, tex } = this.makeLabelMaterial('按 E · 交互');
    this.labelMat = mat;
    this.labelTex = tex;
    this.label = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 0.8), this.labelMat);
    this.label.position.y = 1.6;
    this.label.renderOrder = 1000;
    this.group.add(this.label);

    scene.add(this.group);
  }

  private makeLabelMaterial(text: string): {
    mat: THREE.MeshBasicMaterial;
    tex: THREE.CanvasTexture;
  } {
    const canvas = document.createElement('canvas');
    canvas.width = 512;
    canvas.height = 128;
    const ctx = canvas.getContext('2d');
    if (ctx) this.drawLabel(ctx, canvas.width, canvas.height, text);
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    const mat = new THREE.MeshBasicMaterial({
      map: tex,
      transparent: true,
      side: THREE.DoubleSide,
      depthTest: false, // 隔墙也看得见
    });
    return { mat, tex };
  }

  private drawLabel(ctx: CanvasRenderingContext2D, W: number, H: number, text: string): void {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = 'rgba(0, 30, 20, 0.9)';
    ctx.fillRect(0, 0, W, H);
    ctx.strokeStyle = '#00ff99';
    ctx.lineWidth = 6;
    ctx.strokeRect(3, 3, W - 6, H - 6);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 54px "Helvetica Neue", "PingFang SC", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, W / 2, H / 2 + 4);
  }

  /** 指向目标并显示文字；传 null 隐藏。 */
  setTarget(target: THREE.Object3D | null, text = '按 E · 交互'): void {
    if (!target) {
      this.target = null;
      this.group.visible = false;
      return;
    }
    this.target = target;
    const canvas = this.labelTex.image as HTMLCanvasElement;
    const ctx = canvas.getContext('2d');
    if (ctx) this.drawLabel(ctx, canvas.width, canvas.height, text);
    this.labelTex.needsUpdate = true;
    this.group.visible = true;
  }

  update(dt: number, cameraPos: THREE.Vector3): void {
    if (!this.target || !this.group.visible) return;
    this.accum += dt;
    const targetWorld = new THREE.Vector3();
    this.target.getWorldPosition(targetWorld);
    // 悬浮 + 上下浮动
    const hover = 1.3 + Math.sin(this.accum * 4) * 0.12;
    this.group.position.set(targetWorld.x, targetWorld.y + hover, targetWorld.z);
    // 整体始终面向相机（只绕 Y）
    const dx = cameraPos.x - targetWorld.x;
    const dz = cameraPos.z - targetWorld.z;
    this.label.rotation.y = Math.atan2(dx, dz);
    // 脉冲透明度
    const pulse = 0.6 + 0.35 * (0.5 + Math.sin(this.accum * 6) * 0.5);
    (this.arrow.material as THREE.MeshBasicMaterial).opacity = pulse;
    (this.ring.material as THREE.MeshBasicMaterial).opacity = pulse * 0.8;
    // 环缩放呼吸
    const s = 1.0 + Math.sin(this.accum * 4) * 0.15;
    this.ring.scale.set(s, 1, s);
  }
}
