/**
 * 教程关：数据中心 3 个主要房间 —— NETWORK_ROOM / STORAGE_ROOM / COMMAND_POST。
 *
 * 场景布局（俯视，单位米）：
 *
 *   -20 ────────────── 0 ────────────── 20
 *   ┌──────────┐    ┌──────────┐    ┌──────────┐
 *   │ NETWORK  │────│ COMMAND  │────│ STORAGE  │
 *   │  ROOM    │    │  POST    │    │  ROOM    │
 *   └──────────┘    └──────────┘    └──────────┘
 *
 * 每个房间：
 *  - 四堵墙（带门洞）+ 天花板（省略，仅地面差异化）
 *  - 一个可交互的控制台 Mesh，userData.interactable 指向流水线 hook
 *  - 一个进入触发器 Box3，供 ZoneManager 检测并切换 `currentZone`
 */
import * as THREE from 'three';
import type { PlayerController, DataCenterZone, InteractableObject } from '../fps/PlayerController';
import type { CollisionSystem } from '../fps/CollisionSystem';

export interface RoomBounds {
  zone: DataCenterZone;
  box: THREE.Box3;
}

export interface BuiltLevel {
  zones: RoomBounds[];
  consoles: {
    command: THREE.Object3D;
    network: THREE.Object3D;
    storage: THREE.Object3D;
    cutover: THREE.Object3D;
  };
}

const ROOM = { width: 10, depth: 10, wallHeight: 3, wallThickness: 0.3 };

const roomPositions: Record<Exclude<DataCenterZone, 'COLD_AISLE' | 'HOT_AISLE'>, [number, number]> = {
  NETWORK_ROOM: [-14, 0],
  COMMAND_POST: [0, 0],
  STORAGE_ROOM: [14, 0],
};

const wallMat = new THREE.MeshStandardMaterial({
  color: 0x1e2126,
  roughness: 0.95,
  metalness: 0.05,
});

const floorMat = (tint: number): THREE.MeshStandardMaterial =>
  new THREE.MeshStandardMaterial({ color: tint, roughness: 0.85 });

function addWall(
  scene: THREE.Scene,
  collision: CollisionSystem,
  x: number,
  z: number,
  w: number,
  d: number,
): void {
  const geom = new THREE.BoxGeometry(w, ROOM.wallHeight, d);
  const mesh = new THREE.Mesh(geom, wallMat);
  mesh.position.set(x, ROOM.wallHeight / 2, z);
  scene.add(mesh);
  // 直接计算 AABB，避免 setFromObject matrixWorld 时序问题
  collision.add({
    box: new THREE.Box3(
      new THREE.Vector3(x - w / 2, 0, z - d / 2),
      new THREE.Vector3(x + w / 2, ROOM.wallHeight, z + d / 2),
    ),
    solid: true,
  });
}

function buildRoomWalls(
  scene: THREE.Scene,
  collision: CollisionSystem,
  cx: number,
  cz: number,
  doorwaysOn: ('N' | 'S' | 'E' | 'W')[],
): void {
  const { width: w, depth: d, wallThickness: t } = ROOM;
  const halfW = w / 2;
  const halfD = d / 2;
  const door = 2.0; // 门洞宽度

  // North wall (−Z)
  if (doorwaysOn.includes('N')) {
    const seg = (w - door) / 2;
    addWall(scene, collision, cx - (halfW - seg / 2), cz - halfD, seg, t);
    addWall(scene, collision, cx + (halfW - seg / 2), cz - halfD, seg, t);
  } else {
    addWall(scene, collision, cx, cz - halfD, w, t);
  }
  // South wall (+Z)
  if (doorwaysOn.includes('S')) {
    const seg = (w - door) / 2;
    addWall(scene, collision, cx - (halfW - seg / 2), cz + halfD, seg, t);
    addWall(scene, collision, cx + (halfW - seg / 2), cz + halfD, seg, t);
  } else {
    addWall(scene, collision, cx, cz + halfD, w, t);
  }
  // East wall (+X)
  if (doorwaysOn.includes('E')) {
    const seg = (d - door) / 2;
    addWall(scene, collision, cx + halfW, cz - (halfD - seg / 2), t, seg);
    addWall(scene, collision, cx + halfW, cz + (halfD - seg / 2), t, seg);
  } else {
    addWall(scene, collision, cx + halfW, cz, t, d);
  }
  // West wall (−X)
  if (doorwaysOn.includes('W')) {
    const seg = (d - door) / 2;
    addWall(scene, collision, cx - halfW, cz - (halfD - seg / 2), t, seg);
    addWall(scene, collision, cx - halfW, cz + (halfD - seg / 2), t, seg);
  } else {
    addWall(scene, collision, cx - halfW, cz, t, d);
  }
}

function addConsole(
  scene: THREE.Scene,
  collision: CollisionSystem,
  x: number,
  z: number,
  color: number,
  label: string,
  interactableId: string,
  interactableType: string,
  onInteract: () => void,
  signLines?: { title: string; subtitle?: string; accent?: string },
  screenKind: 'vcenter' | 'network' | 'storage' | 'cutover' = 'vcenter',
): THREE.Object3D {
  const group = new THREE.Group();
  group.position.set(x, 0, z);

  // 控制台底座 —— 模拟 19" 工作站柜
  const base = new THREE.Mesh(
    new THREE.BoxGeometry(1.2, 0.9, 0.6),
    new THREE.MeshStandardMaterial({ color: 0x111317, roughness: 0.7, metalness: 0.3 }),
  );
  base.position.y = 0.45;
  group.add(base);

  // 桌面金属饰板
  const desk = new THREE.Mesh(
    new THREE.BoxGeometry(1.24, 0.05, 0.62),
    new THREE.MeshStandardMaterial({ color: 0x1a1d22, metalness: 0.7, roughness: 0.4 }),
  );
  desk.position.y = 0.92;
  group.add(desk);

  // 键盘（暗灰）
  const keyboard = new THREE.Mesh(
    new THREE.BoxGeometry(0.55, 0.025, 0.2),
    new THREE.MeshStandardMaterial({ color: 0x0a0b0e, roughness: 0.85 }),
  );
  keyboard.position.set(0, 0.96, 0.12);
  group.add(keyboard);

  // 显示器背壳
  const monitorBack = new THREE.Mesh(
    new THREE.BoxGeometry(1.1, 0.7, 0.08),
    new THREE.MeshStandardMaterial({ color: 0x0a0b0e, metalness: 0.6, roughness: 0.5 }),
  );
  monitorBack.position.set(0, 1.4, -0.05);
  group.add(monitorBack);

  // 显示器支柱
  const stand = new THREE.Mesh(
    new THREE.CylinderGeometry(0.03, 0.04, 0.35, 8),
    new THREE.MeshStandardMaterial({ color: 0x1a1d22, metalness: 0.5 }),
  );
  stand.position.set(0, 1.1, -0.05);
  group.add(stand);

  // —— 屏幕 —— CanvasTexture 渲染真实 UI
  const screenTex = makeConsoleScreenTexture(screenKind);
  const screen = new THREE.Mesh(
    new THREE.PlaneGeometry(1.0, 0.6),
    new THREE.MeshStandardMaterial({
      map: screenTex,
      emissiveMap: screenTex,
      emissive: 0xffffff,
      emissiveIntensity: 0.55,
      side: THREE.DoubleSide,
      roughness: 0.3,
    }),
  );
  screen.position.set(0, 1.4, 0.0);
  // 屏幕本身的 interactable 保留，但主要依靠下方的隐形触发体
  screen.userData['interactable'] = {
    id: interactableId,
    type: interactableType,
    label,
    onInteract,
  } satisfies InteractableObject;
  group.add(screen);

  // ── 隐形交互触发体：覆盖整个控制台正面，让玩家从较大角度范围内都能激活 ──
  // 尺寸 1.5m(宽) × 2.0m(高) × 0.8m(深)，中心在控制台前方，不影响视觉
  const triggerMesh = new THREE.Mesh(
    new THREE.BoxGeometry(1.5, 2.0, 0.8),
    new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }),
  );
  triggerMesh.position.set(0, 1.0, 0.3); // 比屏幕略靠前（朝玩家方向）
  triggerMesh.userData['interactable'] = {
    id: interactableId,
    type: interactableType,
    label,
    onInteract,
  } satisfies InteractableObject;
  group.add(triggerMesh);

  // —— 上方铭牌（CanvasTexture），始终面向南（玩家进入方向）——
  if (signLines) {
    const sign = makeSignMesh(signLines, `#${color.toString(16).padStart(6, '0')}`);
    sign.position.set(0, 2.15, 0.32);
    group.add(sign);
    // 背面再放一块，便于从北侧也能看到
    const signBack = makeSignMesh(signLines, `#${color.toString(16).padStart(6, '0')}`);
    signBack.position.set(0, 2.15, -0.32);
    signBack.rotation.y = Math.PI;
    group.add(signBack);
  }

  scene.add(group);
  collision.add({ box: new THREE.Box3().setFromObject(base), solid: true });
  // 返回 group，让 PlayerController 递归射线检测所有子网格（含 triggerMesh）
  return group;
}

/** 用 Canvas 模拟控制台屏幕 UI（非纯色方块，带真实软件视觉） */
function makeConsoleScreenTexture(
  kind: 'vcenter' | 'network' | 'storage' | 'cutover',
): THREE.CanvasTexture {
  const W = 1024;
  const H = 640;
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    // 整体深色背景
    ctx.fillStyle = '#0b1220';
    ctx.fillRect(0, 0, W, H);

    // 顶栏
    ctx.fillStyle = '#111a2c';
    ctx.fillRect(0, 0, W, 56);
    // 三色窗口按钮（Linux/macOS 风）
    const dots = [
      { c: '#ff5f56', x: 20 },
      { c: '#ffbd2e', x: 44 },
      { c: '#27c93f', x: 68 },
    ];
    for (const d of dots) {
      ctx.fillStyle = d.c;
      ctx.beginPath();
      ctx.arc(d.x, 28, 8, 0, Math.PI * 2);
      ctx.fill();
    }

    // 标题
    ctx.fillStyle = '#d6deeb';
    ctx.font = 'bold 22px "Helvetica Neue", Arial, sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    const titles: Record<typeof kind, string> = {
      vcenter: 'VMware vCenter — Login',
      network: 'Network Mapping — vSwitch → Bridge',
      storage: 'Datastore Mapping — VM → 存储池',
      cutover: 'SmartX Cutover Director — Sync / Cutover',
    };
    ctx.fillText(titles[kind], 110, 28);

    // 右上状态
    ctx.textAlign = 'right';
    ctx.fillStyle = '#7fe08a';
    ctx.font = 'bold 16px monospace';
    ctx.fillText('● ONLINE', W - 24, 28);

    // 主题色
    const accents: Record<typeof kind, string> = {
      vcenter: '#4f88ff',
      network: '#4cc9ff',
      storage: '#ffc760',
      cutover: '#ff5f7a',
    };
    const accent = accents[kind];

    // 左栏：导航条
    ctx.fillStyle = '#0f1829';
    ctx.fillRect(0, 56, 180, H - 56);
    ctx.strokeStyle = '#1a2540';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(180, 56);
    ctx.lineTo(180, H);
    ctx.stroke();
    const navItems = [
      { t: 'Dashboard', a: true },
      { t: 'Hosts', a: false },
      { t: 'VMs', a: false },
      { t: 'Networks', a: false },
      { t: 'Datastores', a: false },
      { t: 'Logs', a: false },
    ];
    ctx.font = '500 18px "Helvetica Neue", Arial';
    ctx.textAlign = 'left';
    for (let i = 0; i < navItems.length; i++) {
      const y = 96 + i * 36;
      if (navItems[i].a) {
        ctx.fillStyle = accent;
        ctx.fillRect(0, y - 18, 4, 32);
      }
      ctx.fillStyle = navItems[i].a ? '#ffffff' : '#6f7b94';
      ctx.fillText(navItems[i].t, 22, y);
    }

    // 主区：卡片
    const cardX = 210;
    const cardY = 90;
    const cardW = W - cardX - 30;
    ctx.fillStyle = '#0f1829';
    ctx.fillRect(cardX, cardY, cardW, 180);
    ctx.strokeStyle = accent;
    ctx.lineWidth = 2;
    ctx.strokeRect(cardX + 0.5, cardY + 0.5, cardW, 180);

    // 卡片标题
    ctx.fillStyle = '#d6deeb';
    ctx.font = 'bold 26px "Helvetica Neue", Arial';
    const cardTitles: Record<typeof kind, string> = {
      vcenter: 'vSphere 7.0 · Source Cluster',
      network: 'vSwitch Topology',
      storage: 'Datastore Pools',
      cutover: 'Migration Progress',
    };
    ctx.fillText(cardTitles[kind], cardX + 22, cardY + 36);

    // 进度/统计条
    ctx.fillStyle = '#1a2540';
    ctx.fillRect(cardX + 22, cardY + 70, cardW - 44, 18);
    ctx.fillStyle = accent;
    const pct = kind === 'cutover' ? 0.62 : kind === 'vcenter' ? 0.0 : 0.35;
    ctx.fillRect(cardX + 22, cardY + 70, (cardW - 44) * pct, 18);
    ctx.fillStyle = '#6f7b94';
    ctx.font = '16px monospace';
    ctx.fillText(`${Math.floor(pct * 100)}%`, cardX + 22, cardY + 108);

    // 状态列表
    ctx.font = '15px monospace';
    ctx.fillStyle = '#7fe08a';
    ctx.fillText('✓ Connected', cardX + 22, cardY + 140);
    ctx.fillStyle = '#ffc760';
    ctx.fillText('⚠ 2 snapshots to consolidate', cardX + 22, cardY + 162);

    // 下方日志区
    ctx.fillStyle = '#080d18';
    ctx.fillRect(cardX, cardY + 200, cardW, 300);
    ctx.strokeStyle = '#1a2540';
    ctx.strokeRect(cardX + 0.5, cardY + 200.5, cardW, 300);
    ctx.font = '13px monospace';
    const logs = [
      '[INFO]  Connecting to vcenter.mgmt.local:443',
      '[INFO]  Session established (user: administrator@vsphere.local)',
      '[OK]    Discovered 5 VMs across 2 datastores',
      '[INFO]  Reading VMFS metadata on ds-prod-01',
      '[OK]    Storage policy validated',
      '[INFO]  Checking VM snapshots...',
      '[WARN]  win-db-01: 1 snapshot pending',
      '[WARN]  linux-web-02: 1 snapshot pending',
      '[INFO]  Ready for migration wizard',
      '[_]     await operator input ▮',
    ];
    for (let i = 0; i < logs.length; i++) {
      const isOk = logs[i].startsWith('[OK]');
      const isWarn = logs[i].startsWith('[WARN]');
      const isInput = logs[i].startsWith('[_]');
      ctx.fillStyle = isOk
        ? '#7fe08a'
        : isWarn
          ? '#ffc760'
          : isInput
            ? accent
            : '#8895af';
      ctx.fillText(logs[i], cardX + 16, cardY + 226 + i * 22);
    }

    // 底部状态栏
    ctx.fillStyle = '#0a1020';
    ctx.fillRect(0, H - 28, W, 28);
    ctx.fillStyle = '#6f7b94';
    ctx.font = '12px monospace';
    ctx.textAlign = 'left';
    ctx.fillText('host: vcenter.mgmt.local  ·  TLS 1.3  ·  latency 4ms', 16, H - 14);
    ctx.textAlign = 'right';
    ctx.fillStyle = accent;
    ctx.fillText(`[E] INTERACT  `, W - 16, H - 14);
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return tex;
}

/** 用 Canvas 画一块发光铭牌：标题 + 副标题 + 强调色边框 */
function makeSignMesh(
  lines: { title: string; subtitle?: string; accent?: string },
  borderColor: string,
): THREE.Mesh {
  const W = 512;
  const H = 192;
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    // 背景
    ctx.fillStyle = 'rgba(8, 12, 22, 0.92)';
    ctx.fillRect(0, 0, W, H);
    // 边框
    ctx.strokeStyle = borderColor;
    ctx.lineWidth = 6;
    ctx.strokeRect(3, 3, W - 6, H - 6);
    // 顶部强调条
    ctx.fillStyle = borderColor;
    ctx.fillRect(3, 3, W - 6, 8);
    // 标题
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 56px "Helvetica Neue", "PingFang SC", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(lines.title, W / 2, lines.subtitle ? 78 : H / 2);
    // 副标题
    if (lines.subtitle) {
      ctx.fillStyle = lines.accent ?? borderColor;
      ctx.font = '500 28px "SF Mono", "Menlo", monospace';
      ctx.fillText(lines.subtitle, W / 2, 142);
    }
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  const mat = new THREE.MeshBasicMaterial({
    map: tex,
    transparent: true,
    side: THREE.DoubleSide,
  });
  // 1.6m × 0.6m 物理尺寸
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1.6, 0.6), mat);
  return mesh;
}

/** 房间顶部大横幅：双面可见 */
function addBanner(
  scene: THREE.Scene,
  x: number,
  z: number,
  y: number,
  title: string,
  subtitle: string,
  accent: string,
): void {
  const W = 1024;
  const H = 256;
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    const grad = ctx.createLinearGradient(0, 0, 0, H);
    grad.addColorStop(0, 'rgba(8,12,22,0.95)');
    grad.addColorStop(1, 'rgba(4,6,14,0.95)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);
    ctx.strokeStyle = accent;
    ctx.lineWidth = 6;
    ctx.strokeRect(4, 4, W - 8, H - 8);
    ctx.fillStyle = accent;
    ctx.fillRect(0, 0, W, 10);
    ctx.fillRect(0, H - 10, W, 10);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 88px "Helvetica Neue", "PingFang SC", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(title, W / 2, 110);
    ctx.fillStyle = accent;
    ctx.font = '500 36px "SF Mono", "Menlo", monospace';
    ctx.fillText(subtitle, W / 2, 190);
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  const mat = new THREE.MeshBasicMaterial({ map: tex, transparent: true, side: THREE.DoubleSide });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(6, 1.5), mat);
  mesh.position.set(x, y, z);
  scene.add(mesh);
}

/** 地面贴地标签 */
function addFloorTag(
  scene: THREE.Scene,
  x: number,
  z: number,
  text: string,
  accent: string,
): void {
  const W = 512;
  const H = 128;
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.fillStyle = 'rgba(8,12,22,0.85)';
    ctx.fillRect(0, 0, W, H);
    ctx.strokeStyle = accent;
    ctx.lineWidth = 5;
    ctx.strokeRect(3, 3, W - 6, H - 6);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 64px "Helvetica Neue", "PingFang SC", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, W / 2, H / 2);
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  const mat = new THREE.MeshBasicMaterial({ map: tex, transparent: true });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1.6, 0.4), mat);
  mesh.rotation.x = -Math.PI / 2;
  mesh.position.set(x, 0.02, z);
  scene.add(mesh);
}

function addCorridor(
  scene: THREE.Scene,
  x1: number,
  x2: number,
  width = 3,
): void {
  const len = Math.abs(x2 - x1);
  const floor = new THREE.Mesh(
    new THREE.PlaneGeometry(len, width),
    floorMat(0x0b1020),
  );
  floor.rotation.x = -Math.PI / 2;
  floor.position.set((x1 + x2) / 2, 0.001, 0);
  scene.add(floor);
}

export function buildTutorialLevel(
  scene: THREE.Scene,
  collision: CollisionSystem,
  callbacks: {
    onCommandConsole: () => void;
    onNetworkConsole: () => void;
    onStorageConsole: () => void;
    onCutoverConsole: () => void;
  },
): BuiltLevel {
  // 房间地板（不同色温暗示区域）
  const roomFloors: { zone: DataCenterZone; color: number; doors: ('N' | 'S' | 'E' | 'W')[] }[] = [
    { zone: 'NETWORK_ROOM', color: 0x0d1a30, doors: ['E'] },
    { zone: 'COMMAND_POST', color: 0x0f1726, doors: ['E', 'W', 'N'] }, // N 门通往机柜区
    { zone: 'STORAGE_ROOM', color: 0x1a1028, doors: ['W'] },
  ];

  const zones: RoomBounds[] = [];
  for (const r of roomFloors) {
    const [cx, cz] = roomPositions[r.zone as Exclude<DataCenterZone, 'COLD_AISLE' | 'HOT_AISLE'>];
    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(ROOM.width, ROOM.depth),
      floorMat(r.color),
    );
    floor.rotation.x = -Math.PI / 2;
    floor.position.set(cx, 0, cz);
    scene.add(floor);
    buildRoomWalls(scene, collision, cx, cz, r.doors);

    // COMMAND_POST 区域向北延伸到机柜区（SERVER_ROOM）
    const zoneMinZ = r.zone === 'COMMAND_POST' ? -14 : cz - ROOM.depth / 2;
    const box = new THREE.Box3(
      new THREE.Vector3(cx - ROOM.width / 2, 0, zoneMinZ),
      new THREE.Vector3(cx + ROOM.width / 2, ROOM.wallHeight, cz + ROOM.depth / 2),
    );
    zones.push({ zone: r.zone, box });
  }

  // 走廊
  addCorridor(scene, -(ROOM.width / 2) - 4, -(ROOM.width / 2));
  addCorridor(scene, ROOM.width / 2, ROOM.width / 2 + 4);

  // —— 走廊北/南封墙（填补两侧房间之间的缺口，防止玩家穿出） ——
  const half = ROOM.depth / 2; // = 5
  addWall(scene, collision, -7, -half, 4, ROOM.wallThickness);
  addWall(scene, collision, -7,  half, 4, ROOM.wallThickness);
  addWall(scene, collision,  7, -half, 4, ROOM.wallThickness);
  addWall(scene, collision,  7,  half, 4, ROOM.wallThickness);

  // —— 走廊侧墙（z=±1.5）：防止玩家跑出走廊两侧到空旷地带 ——
  addWall(scene, collision, -7, -1.5, 4, ROOM.wallThickness);
  addWall(scene, collision, -7,  1.5, 4, ROOM.wallThickness);
  addWall(scene, collision,  7, -1.5, 4, ROOM.wallThickness);
  addWall(scene, collision,  7,  1.5, 4, ROOM.wallThickness);

  // —— 机柜区（SERVER_ROOM）三面外墙：z=-5 向北延伸 9m 至 z=-14 ——
  const srvCz = -(half + 4.5); // 东西墙中心 z = -9.5
  addWall(scene, collision, -(ROOM.width / 2), srvCz, ROOM.wallThickness, 9);
  addWall(scene, collision,  (ROOM.width / 2), srvCz, ROOM.wallThickness, 9);
  addWall(scene, collision, 0, -(half + 9), ROOM.width, ROOM.wallThickness);

  // —— 整体外围边界墙：防止玩家跑出可玩区域 ——
  // 可玩区域：x ∈ [-19, 19], z ∈ [-14, 5]
  // 南墙 z=+5.15（三个房间南侧，宽 38m）
  addWall(scene, collision, 0, half + 0.15, 38, ROOM.wallThickness);
  // 北墙已有（机柜区 z=-14），不重复
  // 西墙 x=-19（NETWORK_ROOM 西侧，高度覆盖整个 z 范围）
  addWall(scene, collision, -19, -4.5, ROOM.wallThickness, 19);
  // 东墙 x=+19（STORAGE_ROOM 东侧）
  addWall(scene, collision,  19, -4.5, ROOM.wallThickness, 19);
  // 走廊南侧延伸墙：x ∈ [-9,-5] z ∈ [1.5, 5] 没有走廊侧墙覆盖的区域（走廊外侧）
  // 这里补两道从走廊侧到房间南墙之间的隔断
  addWall(scene, collision, -7,  3.25, 4, 3.5);  // 左走廊南外侧
  addWall(scene, collision,  7,  3.25, 4, 3.5);  // 右走廊南外侧
  // 走廊北侧延伸墙：x ∈ [-9,-5] z ∈ [-5, -1.5] 补北侧走廊外区域
  addWall(scene, collision, -7, -3.25, 4, 3.5);  // 左走廊北外侧
  addWall(scene, collision,  7, -3.25, 4, 3.5);  // 右走廊北外侧

  // 环境光：机房区域微弱港染（远比 SceneDecor 的环境光弱，避免叠加过亮）
  scene.add(new THREE.HemisphereLight(0x6a7380, 0x0a0c10, 0.40));
  const key = new THREE.DirectionalLight(0xbfc4cc, 0.28);
  key.position.set(5, 12, 5);
  scene.add(key);

  // 移除花花绿绿的房间氛围球：用一个小小的中性白 LED 小球代替
  const roomLight = (x: number): void => {
    const ball = new THREE.Mesh(
      new THREE.SphereGeometry(0.12, 6, 6),
      new THREE.MeshBasicMaterial({ color: 0xaab0b8 }),
    );
    ball.position.set(x, 2.6, 0);
    scene.add(ball);
  };
  roomLight(-14);
  roomLight(0);
  roomLight(14);

  // 指挥台两个控制台：vCenter 登录 + Cutover
  const command = addConsole(
    scene,
    collision,
    -2.5,
    -3.5,
    0x00e676,
    '[E] 连接 vCenter 开始迁移',
    'command-console',
    'COMMAND_CONSOLE',
    callbacks.onCommandConsole,
    { title: 'VMware vCenter 控制台', subtitle: 'SOURCE LOGIN · 源端登录', accent: '#4f88ff' },
    'vcenter',
  );
  const cutover = addConsole(
    scene,
    collision,
    2.5,
    -3.5,
    0xff1744,
    '[E] 启动数据同步与切换',
    'cutover-console',
    'CUTOVER_CONSOLE',
    callbacks.onCutoverConsole,
    { title: 'SmartX 切换控制台', subtitle: 'CUTOVER · 同步 / 切换 / 验证', accent: '#ff5566' },
    'cutover',
  );

  const network = addConsole(
    scene,
    collision,
    -14,
    -3.5,
    0x00b4ff,
    '[E] 配置 vSwitch → Bridge 映射',
    'network-console',
    'NETWORK_CONSOLE',
    callbacks.onNetworkConsole,
    { title: 'vSwitch → Bridge 映射台', subtitle: 'NETWORK MAPPING', accent: '#4cc9ff' },
    'network',
  );

  const storage = addConsole(
    scene,
    collision,
    14,
    -3.5,
    0xffb300,
    '[E] 配置 VM → 存储池 映射',
    'storage-console',
    'STORAGE_CONSOLE',
    callbacks.onStorageConsole,
    { title: 'Datastore → 存储池 映射台', subtitle: 'STORAGE MAPPING', accent: '#ffc760' },
    'storage',
  );

  // ---- 指挥台 / COMMAND POST 大横幅（悬挂在屋顶下） ----
  addBanner(scene, 0, -4.7, 2.85, '指挥台 · COMMAND POST', 'VMware → SmartX 迁移作战中心', '#00b4ff');
  // 每个控制台脚下贴地引导箭头标签
  addFloorTag(scene, -2.5, -2.6, 'vCenter 登录', '#00ff99');
  addFloorTag(scene, 2.5, -2.6, 'Cutover 切换', '#ff5566');
  addFloorTag(scene, -14, -2.6, 'Network 映射', '#4cc9ff');
  addFloorTag(scene, 14, -2.6, 'Storage 映射', '#ffc760');
  // ---- 走廊方向指示牌（面向走廊、双面可见） ----
  const addCorridorSign = (
    x: number, z: number, y: number,
    text: string, accent: string,
    rotY: number,
  ): void => {
    const W = 640; const H = 160;
    const canvas = document.createElement('canvas');
    canvas.width = W; canvas.height = H;
    const ctx = canvas.getContext('2d');
    if (ctx) {
      const grad = ctx.createLinearGradient(0, 0, 0, H);
      grad.addColorStop(0, 'rgba(6,12,22,0.97)');
      grad.addColorStop(1, 'rgba(3,6,14,0.97)');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, W, H);
      ctx.strokeStyle = accent;
      ctx.lineWidth = 6;
      ctx.strokeRect(3, 3, W - 6, H - 6);
      ctx.fillStyle = accent;
      ctx.fillRect(0, 0, W, 8);
      ctx.fillRect(0, H - 8, W, 8);
      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 68px "Helvetica Neue", "PingFang SC", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(text, W / 2, H / 2);
    }
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    const mat = new THREE.MeshBasicMaterial({ map: tex, transparent: true, side: THREE.DoubleSide });
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(3.2, 0.8), mat);
    mesh.position.set(x, y, z);
    mesh.rotation.y = rotY;
    scene.add(mesh);
  };

  // 左走廊（指挥台→网络间）：从东侧看到 "◄ 网络间" 的蓝色指示牌
  addCorridorSign(-7, 0, 2.3, '◄  网络间  NETWORK', '#4cc9ff', -Math.PI / 2);
  // 右走廊（指挥台→存储间）：从西侧看到 "存储间 ►" 的琥珀指示牌
  addCorridorSign(7, 0, 2.3, 'STORAGE  存储间  ►', '#ffc760', Math.PI / 2);

  // 走廊地面箭头（对齐到走廊中心，指向目标房间）
  addFloorTag(scene, -7, 0, '← 网络间', '#4cc9ff');
  addFloorTag(scene, 7, 0, '存储间 →', '#ffc760');

  // 走廊环境光点（让走廊更亮、更容易注意）
  const corridorLight = (x: number, color: number): void => {
    const light = new THREE.PointLight(color, 1.8, 6);
    light.position.set(x, 2.2, 0);
    scene.add(light);
    const ball = new THREE.Mesh(
      new THREE.SphereGeometry(0.08, 6, 6),
      new THREE.MeshBasicMaterial({ color }),
    );
    ball.position.copy(light.position);
    scene.add(ball);
  };
  corridorLight(-7, 0x4cc9ff);  // 网络间走廊：蓝色
  corridorLight(7, 0xffc760);   // 存储间走廊：琥珀色
  // 房间里摆几台装饰机架 —— 真实 1U × 多槽位外观
  const addRack = (x: number, z: number, rackId: string): void => {
    const group = new THREE.Group();
    group.position.set(x, 0, z);
    // 主柜体
    const body = new THREE.Mesh(
      new THREE.BoxGeometry(0.9, 2.1, 1.2),
      new THREE.MeshStandardMaterial({ color: 0x15181d, metalness: 0.6, roughness: 0.55 }),
    );
    body.position.y = 1.05;
    group.add(body);
    // 顶部通风盖
    const topCap = new THREE.Mesh(
      new THREE.BoxGeometry(0.92, 0.04, 1.22),
      new THREE.MeshStandardMaterial({ color: 0x080a0d, roughness: 0.8 }),
    );
    topCap.position.y = 2.09;
    group.add(topCap);
    // 前面板：12 个 1U 槽位（深色横条 + LED 点）
    for (let i = 0; i < 12; i++) {
      const y = 0.2 + i * 0.15;
      const slot = new THREE.Mesh(
        new THREE.BoxGeometry(0.82, 0.12, 0.02),
        new THREE.MeshStandardMaterial({ color: 0x0b0d11, roughness: 0.9 }),
      );
      slot.position.set(0, y, 0.601);
      group.add(slot);
      // 两颗 LED（绿常亮 + 琥珀闪烁）
      const led1 = new THREE.Mesh(
        new THREE.PlaneGeometry(0.02, 0.02),
        new THREE.MeshBasicMaterial({ color: 0x33ff66 }),
      );
      led1.position.set(-0.35, y + 0.02, 0.612);
      group.add(led1);
      if (i % 3 === 0) {
        const led2 = new THREE.Mesh(
          new THREE.PlaneGeometry(0.02, 0.02),
          new THREE.MeshBasicMaterial({ color: 0xff9933 }),
        );
        led2.position.set(-0.3, y + 0.02, 0.612);
        group.add(led2);
      }
      // 把手（灰色竖条）
      const handle = new THREE.Mesh(
        new THREE.BoxGeometry(0.015, 0.08, 0.015),
        new THREE.MeshStandardMaterial({ color: 0x404448, metalness: 0.6 }),
      );
      handle.position.set(0.35, y + 0.02, 0.615);
      group.add(handle);
    }
    // 机柜 ID 铭牌
    const plateCanvas = document.createElement('canvas');
    plateCanvas.width = 256;
    plateCanvas.height = 64;
    const pctx = plateCanvas.getContext('2d');
    if (pctx) {
      pctx.fillStyle = '#141618';
      pctx.fillRect(0, 0, 256, 64);
      pctx.strokeStyle = '#3a3d42';
      pctx.strokeRect(2, 2, 252, 60);
      pctx.fillStyle = '#d6deeb';
      pctx.font = 'bold 32px monospace';
      pctx.textAlign = 'center';
      pctx.textBaseline = 'middle';
      pctx.fillText(rackId, 128, 32);
    }
    const plateTex = new THREE.CanvasTexture(plateCanvas);
    plateTex.colorSpace = THREE.SRGBColorSpace;
    const plate = new THREE.Mesh(
      new THREE.PlaneGeometry(0.3, 0.075),
      new THREE.MeshStandardMaterial({
        map: plateTex,
        emissiveMap: plateTex,
        emissive: 0x666666,
        emissiveIntensity: 0.25,
      }),
    );
    plate.position.set(0, 2.0, 0.606);
    group.add(plate);
    scene.add(group);
    collision.add({ box: new THREE.Box3().setFromObject(body), solid: true });
  };
  // 网络间：交换机架 2 列
  let nId = 1;
  for (let i = 0; i < 3; i++) {
    addRack(-17, -2 + i * 2, `NET-${String(nId++).padStart(2, '0')}`);
    addRack(-11, -2 + i * 2, `NET-${String(nId++).padStart(2, '0')}`);
  }
  // 存储间：存储阵列
  let sId = 1;
  for (let i = 0; i < 3; i++) {
    addRack(11, -2 + i * 2, `STG-${String(sId++).padStart(2, '0')}`);
    addRack(17, -2 + i * 2, `STG-${String(sId++).padStart(2, '0')}`);
  }

  return {
    zones,
    consoles: { command, cutover, network, storage },
  };
}

/** 在每帧调用：根据玩家当前位置决定应进入哪个区域 */
export class ZoneManager {
  constructor(private readonly zones: RoomBounds[]) {}

  update(player: PlayerController): void {
    const p = player.state.position;
    for (const z of this.zones) {
      if (
        p.x >= z.box.min.x &&
        p.x <= z.box.max.x &&
        p.z >= z.box.min.z &&
        p.z <= z.box.max.z
      ) {
        if (player.state.currentZone !== z.zone) player.onZoneEnter(z.zone);
        return;
      }
    }
    // 不在任一房间内 → 默认走廊视作 COMMAND_POST（不切换，避免频繁 toggle）
  }
}
