/**
 * 玩家生命值系统 —— 受击、死亡、复活，含护甲层。
 * 受击 → 优先扣护甲（吸收 60%），余下打 HP；HP 0 → 死亡 overlay，按 R 复活。
 */
import { uiStore } from '../ui/uiStore';
import { synthAudio } from '../audio/SynthAudio';
import { EventBus } from '../core/EventBus';

export interface PlayerHealthOpts {
  maxHp: number;
  regenDelayMs: number; // 多久未受击后开始自动回血
  regenPerSec: number;
  maxArmor: number;
  /** 护甲吸收伤害的比例（0..1） */
  armorAbsorb: number;
}

const DEFAULTS: PlayerHealthOpts = {
  maxHp: 100,
  regenDelayMs: 6000,
  regenPerSec: 6,
  maxArmor: 100,
  armorAbsorb: 0.6,
};

export class PlayerHealth {
  private hp: number;
  private armor = 0;
  private readonly max: number;
  private readonly maxArmor: number;
  private readonly armorAbsorb: number;
  private readonly regenDelayMs: number;
  private readonly regenPerSec: number;
  private lastDamageTs = 0;
  private dead = false;
  private invulnerable = false;
  private invulnUntilTs = 0;

  constructor(opts: Partial<PlayerHealthOpts> = {}) {
    const o = { ...DEFAULTS, ...opts };
    this.hp = o.maxHp;
    this.max = o.maxHp;
    this.maxArmor = o.maxArmor;
    this.armorAbsorb = o.armorAbsorb;
    this.regenDelayMs = o.regenDelayMs;
    this.regenPerSec = o.regenPerSec;
    uiStore.patchHealth({
      hp: this.hp,
      max: this.max,
      armor: this.armor,
      armorMax: this.maxArmor,
      dead: false,
      damageFlash: 0,
    });
  }

  takeDamage(amount: number): void {
    if (this.dead || this.invulnerable) return;
    let toHp = amount;
    let absorbed = 0;
    if (this.armor > 0 && this.armorAbsorb > 0) {
      const wanted = amount * this.armorAbsorb;
      absorbed = Math.min(this.armor, wanted);
      this.armor -= absorbed;
      toHp = amount - absorbed;
    }
    this.hp = Math.max(0, this.hp - toHp);
    this.lastDamageTs = performance.now();
    uiStore.patchHealth({ hp: this.hp, armor: Math.round(this.armor), damageFlash: 1 });
    setTimeout(() => uiStore.patchHealth({ damageFlash: 0 }), 220);
    if (absorbed > 0) {
      uiStore.pushLog(
        'danger',
        `⚠ 受到 ${amount} 点伤害（护甲吸收 ${Math.round(absorbed)}，HP ${this.hp}/${this.max}）`,
      );
    } else {
      uiStore.pushLog('danger', `⚠ 受到 ${amount} 点伤害（HP ${this.hp}/${this.max}）`);
    }
    synthAudio.play('bug_hit');
    if (this.hp <= 0) this.die();
  }

  heal(amount: number): void {
    if (this.dead) return;
    const before = this.hp;
    this.hp = Math.min(this.max, this.hp + amount);
    const gained = Math.round(this.hp - before);
    uiStore.patchHealth({ hp: this.hp });
    if (gained > 0) uiStore.pushLog('success', `+${gained} HP（${Math.round(this.hp)}/${this.max}）`);
  }

  /** 拾取护甲板 */
  addArmor(amount: number): void {
    if (this.dead) return;
    const before = this.armor;
    this.armor = Math.min(this.maxArmor, this.armor + amount);
    const gained = Math.round(this.armor - before);
    uiStore.patchHealth({ armor: Math.round(this.armor), armorMax: this.maxArmor });
    if (gained > 0) {
      uiStore.pushLog('success', `+${gained} 护甲（${Math.round(this.armor)}/${this.maxArmor}）`);
    }
  }

  private die(): void {
    this.dead = true;
    uiStore.patchHealth({ dead: true });
    synthAudio.speak('任务失败。在机房被敌方厂商击倒，按 R 复活。', { priority: true });
    EventBus.emit('player:died', {});
  }

  revive(atPosition?: { reset?: () => void }): void {
    this.hp = this.max;
    this.armor = 0;
    this.dead = false;
    this.invulnerable = true;
    this.invulnUntilTs = performance.now() + 2500;
    uiStore.patchHealth({ hp: this.hp, armor: 0, dead: false, damageFlash: 0 });
    uiStore.pushLog('success', '★ 复活：短暂无敌 2.5 秒');
    atPosition?.reset?.();
    EventBus.emit('player:revived', {});
  }

  isDead(): boolean {
    return this.dead;
  }
  isInvulnerable(): boolean {
    if (this.invulnerable && performance.now() > this.invulnUntilTs) {
      this.invulnerable = false;
    }
    return this.dead || this.invulnerable;
  }

  update(dt: number): void {
    if (this.dead) return;
    const since = performance.now() - this.lastDamageTs;
    if (since > this.regenDelayMs && this.hp < this.max) {
      this.hp = Math.min(this.max, this.hp + this.regenPerSec * dt);
      uiStore.patchHealth({ hp: Math.round(this.hp) });
    }
  }
}
