/**
 * WeaponViewmodel — FPS 武器视图模型（第一人称 SMG）
 *
 * 视觉亮点（相比旧版全面提升）：
 *  · 左手握前护手 + 右手握枪柄（新增手部模型）
 *  · SMG 风格枪体（护木/枪管/消焰器/瞄具/战术手电/品牌光带）
 *  · MeshPhysicalMaterial clearcoat 高光质感
 *  · 弹簧后座系统（Z 后退 + Y 上仰 + 扭转，三轴独立弹簧）
 *  · 鼠标惯性晃动（相机转动时武器延迟跟随）
 *  · 星形枪口火焰（3 交叉平面 + 正面发光圆盘，AdditiveBlending）
 *
 * 外部接口（与旧版完全兼容）：
 *  · attachTo(camera)
 *  · fire()
 *  · update(dt, moving, sprinting, mouseDX?, mouseDY?)
 *
 * GLB 资产管线（Phase 2）：
 *  · WeaponViewmodel.loadAsync(url) — 异步工厂，优先加载 GLB，失败时退回程序化
 *  · setAnimation(name, loop?) — 播放 GLB 内嵌动画（无 GLB 时静默忽略）
 */
import * as THREE from 'three';
import type { WeaponAsset } from './WeaponAssetLoader';

export class WeaponViewmodel {
  readonly group: THREE.Group;

  private muzzle: THREE.PointLight;
  private readonly flashPlanes: THREE.Mesh[] = [];
  private flashTimer = 0;
  private time = 0;

  /* ── 弹簧后座状态 ── */
  private recoilZ = 0;     private recoilVelZ = 0;
  private recoilY = 0;     private recoilVelY = 0;
  private recoilTwist = 0; private recoilVelTwist = 0;

  /* ── 鼠标惯性晃动 ── */
  private swayX = 0; private swayVelX = 0;
  private swayY = 0; private swayVelY = 0;
  private sprintBlend = 0;
  private moveBlend = 0;

  /** 相机坐标系下的基础位置（右下角） */
  private readonly basePos = new THREE.Vector3(0.30, -0.30, -0.50);
  private readonly baseRot = new THREE.Euler(0, -0.10, 0);

  /* ── GLB 资产管线状态 ── */
  private _mixer: THREE.AnimationMixer | null = null;
  private _clips: Map<string, THREE.AnimationClip> = new Map();

  constructor() {
    this.group = new THREE.Group();
    this.group.position.copy(this.basePos);
    this.group.rotation.copy(this.baseRot);

    this.muzzle = new THREE.PointLight(0xffaa44, 0, 5);
    this._buildWeapon();

    /* 武器渲染在独立的 vmCamera 层（layer 1） */
    this.group.renderOrder = 999;
    this.group.layers.set(1);
    this.group.traverse((o) => {
      o.layers.set(1);
      if ((o as THREE.Mesh).isMesh) {
        (o as THREE.Mesh).renderOrder = 999;
        const mat = (o as THREE.Mesh).material as THREE.Material;
        if (mat) mat.depthTest = false;
      }
    });
  }

  /* ─────────────── 枪体几何体构建 ─────────────── */

  private _buildWeapon(): void {
    const g = this.group;

    /* 材质库 — 成品化金属/聚合物方案（保留适度自发光避免暗区发黑） */
    const gunMetal = new THREE.MeshPhysicalMaterial({
      color: 0x5a6673, metalness: 0.90, roughness: 0.22,
      clearcoat: 0.65, clearcoatRoughness: 0.14,
      emissive: 0x141a22, emissiveIntensity: 0.35,
    });
    const gunMetal2 = new THREE.MeshPhysicalMaterial({
      color: 0x44505d, metalness: 0.94, roughness: 0.16,
      clearcoat: 0.85, clearcoatRoughness: 0.10,
      emissive: 0x10161e, emissiveIntensity: 0.30,
    });
    const polymerDark = new THREE.MeshPhysicalMaterial({
      color: 0x252b34, metalness: 0.12, roughness: 0.62, clearcoat: 0.20,
      emissive: 0x0b0f14, emissiveIntensity: 0.22,
    });
    const magMat = new THREE.MeshStandardMaterial({
      color: 0x3d4a58, metalness: 0.76, roughness: 0.34,
      emissive: 0x0f141c, emissiveIntensity: 0.30,
    });
    const gloveMat = new THREE.MeshStandardMaterial({
      color: 0x343e49, roughness: 0.86, metalness: 0.03,
      emissive: 0x0c1015, emissiveIntensity: 0.22,
    });

    /* ── 枪身主体 (Receiver) ── */
    this._add(g, new THREE.BoxGeometry(0.14, 0.085, 0.32), gunMetal, 0, 0, 0);
    /* 下机匣 */
    this._add(g, new THREE.BoxGeometry(0.10, 0.046, 0.24), polymerDark, 0, -0.043, -0.02);
    /* 顶部皮卡汀尼导轨 */
    this._add(g, new THREE.BoxGeometry(0.040, 0.013, 0.30), gunMetal2, 0, 0.049, -0.01);

    /* ── 护木 (Handguard / Barrel Shroud) ── */
    const shroud = new THREE.Mesh(
      new THREE.CylinderGeometry(0.027, 0.027, 0.24, 12, 1), gunMetal,
    );
    shroud.rotation.x = Math.PI / 2;
    shroud.position.set(0, 0.008, -0.18);
    g.add(shroud);

    /* 护木镂空槽（装饰） */
    const slotMat = new THREE.MeshBasicMaterial({ color: 0x2a333f });
    for (let i = 0; i < 4; i++) {
      const ang = (i / 4) * Math.PI * 2 + Math.PI / 8;
      const sl = new THREE.Mesh(new THREE.BoxGeometry(0.007, 0.065, 0.085), slotMat);
      sl.position.set(Math.sin(ang) * 0.029, Math.cos(ang) * 0.029 + 0.008, -0.18);
      sl.rotation.z = -ang;
      g.add(sl);
    }

    /* ── 枪管 ── */
    const barrel = new THREE.Mesh(
      new THREE.CylinderGeometry(0.011, 0.011, 0.22, 10), gunMetal2,
    );
    barrel.rotation.x = Math.PI / 2;
    barrel.position.set(0, 0.008, -0.38);
    g.add(barrel);

    /* 消焰器（六棱） */
    const muzzleDev = new THREE.Mesh(
      new THREE.CylinderGeometry(0.015, 0.019, 0.048, 6), gunMetal2,
    );
    muzzleDev.rotation.x = Math.PI / 2;
    muzzleDev.position.set(0, 0.008, -0.50);
    g.add(muzzleDev);

    /* ── 握把 ── */
    this._add(g, new THREE.BoxGeometry(0.055, 0.116, 0.070), polymerDark,
      0, -0.103, 0.067, -0.18);
    /* 握把防滑纹 */
    this._add(g, new THREE.BoxGeometry(0.058, 0.065, 0.016),
      new THREE.MeshStandardMaterial({ color: 0x202830, roughness: 1.0 }),
      0, -0.094, 0.095);

    /* ── 弹匣 ── */
    this._add(g, new THREE.BoxGeometry(0.048, 0.132, 0.068), magMat, 0, -0.098, -0.018);
    this._add(g, new THREE.BoxGeometry(0.054, 0.012, 0.074), magMat, 0, -0.168, -0.018);

    /* 拉机柄 */
    this._add(g, new THREE.BoxGeometry(0.020, 0.014, 0.040), gunMetal2, 0.078, 0.013, 0.048);

    /* 侧面装饰面板 */
    this._add(g,
      new THREE.BoxGeometry(0.003, 0.050, 0.24),
      new THREE.MeshStandardMaterial({
        color: 0x28a8d7,
        metalness: 0.55,
        roughness: 0.38,
        emissive: 0x10638a,
        emissiveIntensity: 0.55,
      }),
      0.073, 0.008, -0.04);

    /* ── 红点瞄具 ── */
    const rdotMat = new THREE.MeshPhysicalMaterial({
      color: 0x3f4957, metalness: 0.74, roughness: 0.30, clearcoat: 0.50,
      emissive: 0x0f141a, emissiveIntensity: 0.24,
    });
    this._add(g, new THREE.BoxGeometry(0.032, 0.034, 0.085), rdotMat, 0, 0.077, -0.022);
    /* 镜片 */
    this._add(g,
      new THREE.BoxGeometry(0.023, 0.023, 0.006),
      new THREE.MeshPhysicalMaterial({
        color: 0x1040a8, metalness: 0, roughness: 0,
        transparent: true, opacity: 0.55, transmission: 0.6,
      }),
      0, 0.077, -0.065);
    /* 分划点（红色自发光） */
    this._add(g,
      new THREE.SphereGeometry(0.0022, 6, 4),
      new THREE.MeshBasicMaterial({ color: 0xff2020 }),
      0, 0.077, -0.062);

    /* ── 战术手电 ── */
    const tacLight = new THREE.Mesh(
      new THREE.CylinderGeometry(0.014, 0.016, 0.090, 8), gunMetal,
    );
    tacLight.rotation.x = Math.PI / 2;
    tacLight.position.set(-0.049, -0.009, -0.22);
    g.add(tacLight);
    this._add(g,
      new THREE.CircleGeometry(0.010, 10),
      new THREE.MeshStandardMaterial({ color: 0xffe8a0, emissive: 0xffe8a0, emissiveIntensity: 1.35 }),
      -0.049, -0.009, -0.27);

    /* ── SmartX 品牌青色光带 ── */
    this._add(g,
      new THREE.BoxGeometry(0.140, 0.009, 0.192),
      new THREE.MeshStandardMaterial({ color: 0x00b4ff, emissive: 0x00b4ff, emissiveIntensity: 1.9 }),
      0, -0.028, -0.058);

    /* ─────── 左手 + 前臂 ─────── */
    /* 前臂（CapsuleGeometry — Three.js r148+） */
    const forearm = new THREE.Mesh(
      new THREE.CapsuleGeometry(0.034, 0.165, 4, 8), gloveMat,
    );
    forearm.position.set(-0.195, -0.026, -0.155);
    forearm.rotation.set(0.44, 0.12, -1.37);
    g.add(forearm);

    /* 手腕 */
    this._add(g, new THREE.BoxGeometry(0.052, 0.042, 0.042), gloveMat,
      -0.100, 0.000, -0.196, 0.15, 0.08, 0.30);
    /* 手掌 */
    this._add(g, new THREE.BoxGeometry(0.075, 0.042, 0.064), gloveMat,
      -0.065, 0.008, -0.213, 0.10, -0.05, 0.18);

    /* 四根手指（从下方抱护木） */
    const fzArr = [-0.190, -0.210, -0.228, -0.246];
    for (let i = 0; i < 4; i++) {
      this._add(g, new THREE.BoxGeometry(0.013, 0.014, 0.048), gloveMat,
        -0.038, 0.028, fzArr[i], 0.32 + i * 0.05, 0, 0.11);
    }
    /* 拇指 */
    this._add(g, new THREE.BoxGeometry(0.038, 0.013, 0.036), gloveMat,
      -0.022, 0.018, -0.186, 0.10, 0.20, -0.38);

    /* ─────── 右手（局部：握把区域） ─────── */
    this._add(g, new THREE.BoxGeometry(0.042, 0.062, 0.042), gloveMat,
      0.046, -0.082, 0.070);
    this._add(g, new THREE.BoxGeometry(0.030, 0.014, 0.033), gloveMat,
      0.070, -0.064, 0.062, 0.25, 0.10, 0.35);

    /* ─────── 星形枪口火焰（3 平面 + 正面圆盘） ─────── */
    const flashBaseMat = new THREE.MeshBasicMaterial({
      color: 0xffcc44, transparent: true, opacity: 0,
      side: THREE.DoubleSide, depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    const flashGeo = new THREE.PlaneGeometry(0.28, 0.28);
    for (let i = 0; i < 3; i++) {
      const fp = new THREE.Mesh(flashGeo, flashBaseMat.clone());
      fp.position.set(0, 0.008, -0.54);
      fp.rotation.z = (i / 3) * Math.PI;
      this.flashPlanes.push(fp);
      g.add(fp);
    }
    const disc = new THREE.Mesh(new THREE.CircleGeometry(0.11, 12), flashBaseMat.clone());
    disc.position.set(0, 0.008, -0.57);
    this.flashPlanes.push(disc);
    g.add(disc);

    /* 枪口点光 */
    this.muzzle.position.set(0, 0.008, -0.54);
    g.add(this.muzzle);

    /* 成品化阶段保持较大可见性，但不再使用过大的调试比例 */
    g.scale.multiplyScalar(1.5);
  }

  /** 辅助：创建 Mesh 并添加到 Group（rx/ry/rz 单位弧度） */
  private _add(
    g: THREE.Group,
    geo: THREE.BufferGeometry,
    mat: THREE.Material,
    px = 0, py = 0, pz = 0,
    rx = 0, ry = 0, rz = 0,
  ): THREE.Mesh {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(px, py, pz);
    if (rx || ry || rz) m.rotation.set(rx, ry, rz);
    g.add(m);
    return m;
  }

  /* ─────────────── 外部接口 ─────────────── */

  /**
   * 静态异步工厂 — GLB 资产管线入口。
   *
   * 优先从 url 加载 GLB；加载失败（网络错误/超时/文件不存在）时
   * 静默退回程序化几何体，保证始终返回可用的 WeaponViewmodel。
   *
   * 用法（替代 `new WeaponViewmodel()`）：
   * ```ts
   * const vm = await WeaponViewmodel.loadAsync('/assets/weapons/smg.glb');
   * ```
   */
  static async loadAsync(url: string, timeoutMs = 8_000): Promise<WeaponViewmodel> {
    const vm = new WeaponViewmodel();
    try {
      const { WeaponAssetLoader } = await import('./WeaponAssetLoader');
      const asset = await WeaponAssetLoader.load(url, timeoutMs);
      vm._replaceWithAsset(asset);
    } catch (err) {
      console.warn('[WeaponViewmodel] GLB load failed, using procedural fallback:', err);
    }
    return vm;
  }

  /**
   * 用 GLB 资产替换程序化几何体。
   * muzzle 光源重新挂到 GLB 骨骼（若有），否则保留在 group 根。
   */
  private _replaceWithAsset(asset: WeaponAsset): void {
    // 移除程序化子节点（含 muzzle 光源）
    const children = [...this.group.children];
    for (const c of children) {
      this.group.remove(c);
    }

    // R8.2: 给 GLB 网格应用 PBR 金属磨损材质
    WeaponViewmodel._applyPBRMetalMaterials(asset.group);

    // R8.2: 调整 GLB 朝向/缩放使其作为右下角第一人称武器可见
    //  · smg.glb 默认坐标系常常 Y-up 朝 -Z，需要把它对齐到相机本地坐标
    //  · 经验值：缩放后让武器约占屏幕右下 1/4，绕 Y 轴 180° 让枪口朝前（-Z）
    asset.group.scale.setScalar(0.55);
    asset.group.position.set(0, -0.02, 0.05);
    asset.group.rotation.set(0, Math.PI, 0);

    // 挂入 GLB 场景，并确保渲染属性与程序化一致
    this.group.add(asset.group);

    // muzzle 光源：优先挂到 GLB 命名骨骼，否则挂回 group 根
    if (asset.muzzleBone) {
      asset.muzzleBone.add(this.muzzle);
    } else {
      this.group.add(this.muzzle);
    }

    this._mixer = asset.mixer;
    this._clips = new Map(asset.clips);
  }

  /**
   * R8.2: 给 GLB 武器网格应用 PBR 金属磨损材质。
   * 即使 smg.glb 不带贴图，也用程序化 CanvasTexture 生成磨损 roughness map，
   * 让金属感真正成立（高 metalness + 不均匀 roughness + clearcoat）。
   */
  private static _applyPBRMetalMaterials(root: THREE.Object3D): void {
    const wearTex = WeaponViewmodel._getOrCreateWearTexture();

    root.traverse((obj) => {
      const mesh = obj as THREE.Mesh;
      if (!mesh.isMesh) return;

      // 保留原色作 hint，但材质主体替换为金属 PBR
      const oldMat = mesh.material as THREE.MeshStandardMaterial | undefined;
      const baseColor = (oldMat && (oldMat.color as THREE.Color)) ?? new THREE.Color(0x4d5560);

      const metal = new THREE.MeshPhysicalMaterial({
        color: baseColor,
        metalness: 0.92,
        roughness: 0.34,
        roughnessMap: wearTex,
        clearcoat: 0.55,
        clearcoatRoughness: 0.18,
        envMapIntensity: 1.4,
      });
      // 与 viewmodel 渲染流水线一致
      metal.depthTest = false;

      mesh.material = metal;
      mesh.renderOrder = 999;
      mesh.layers.set(1);
    });
  }

  private static _wearTextureCache: THREE.Texture | null = null;
  /** 程序化磨损纹理：256×256 灰阶噪声 + 划痕带，作为 roughnessMap 使用 */
  private static _getOrCreateWearTexture(): THREE.Texture {
    if (WeaponViewmodel._wearTextureCache) return WeaponViewmodel._wearTextureCache;
    const size = 256;
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = size;
    const ctx = canvas.getContext('2d')!;
    // 底色：中等粗糙度
    ctx.fillStyle = '#7a7a7a';
    ctx.fillRect(0, 0, size, size);
    // 噪点
    const img = ctx.getImageData(0, 0, size, size);
    for (let i = 0; i < img.data.length; i += 4) {
      const n = (Math.random() - 0.5) * 60;
      img.data[i] = Math.max(0, Math.min(255, img.data[i] + n));
      img.data[i + 1] = img.data[i];
      img.data[i + 2] = img.data[i];
    }
    ctx.putImageData(img, 0, 0);
    // 划痕：少量明亮（光滑）斜线模拟磨光
    ctx.globalAlpha = 0.5;
    ctx.strokeStyle = '#cccccc';
    for (let i = 0; i < 40; i++) {
      ctx.lineWidth = Math.random() * 1.5 + 0.3;
      ctx.beginPath();
      const x = Math.random() * size;
      const y = Math.random() * size;
      ctx.moveTo(x, y);
      ctx.lineTo(x + (Math.random() - 0.5) * 80, y + (Math.random() - 0.5) * 80);
      ctx.stroke();
    }
    // 暗斑：粗糙（生锈/油污）
    ctx.globalAlpha = 0.35;
    ctx.fillStyle = '#2a2a2a';
    for (let i = 0; i < 25; i++) {
      ctx.beginPath();
      ctx.arc(Math.random() * size, Math.random() * size, Math.random() * 6 + 2, 0, Math.PI * 2);
      ctx.fill();
    }
    const tex = new THREE.CanvasTexture(canvas);
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(2, 2);
    tex.colorSpace = THREE.NoColorSpace; // roughness 不需要 sRGB
    WeaponViewmodel._wearTextureCache = tex;
    return tex;
  }

  /**
   * 播放 GLB 内嵌动画（未加载 GLB 或动画不存在时静默忽略）。
   * @param name  动画名称（须与 GLB 内 clip.name 完全匹配）
   * @param loop  是否循环，默认 true
   */
  setAnimation(name: string, loop = true): void {
    if (!this._mixer) return;
    const clip = this._clips.get(name);
    if (!clip) {
      console.warn(`[WeaponViewmodel] Animation "${name}" not found in loaded GLB.`);
      return;
    }
    const action = this._mixer.clipAction(clip);
    action.loop = loop ? THREE.LoopRepeat : THREE.LoopOnce;
    action.clampWhenFinished = !loop;
    action.reset().play();
  }

  /** 将 viewmodel 挂到相机（vmCamera）上 */
  attachTo(camera: THREE.Camera): void {
    camera.add(this.group);
  }

  /** 释放几何体/材质/动画资源，供场景重建或模式切换时调用 */
  dispose(): void {
    this._mixer?.stopAllAction();
    this._mixer = null;
    this._clips.clear();
    this.group.traverse((obj) => {
      const mesh = obj as THREE.Mesh;
      if (!mesh.isMesh) return;
      mesh.geometry.dispose();
      if (Array.isArray(mesh.material)) {
        for (const m of mesh.material) m.dispose();
      } else {
        mesh.material.dispose();
      }
    });
  }

  /** 射击时调用：启动弹簧后座 + 枪口火焰 */
  fire(): void {
    const yawKick = (Math.random() - 0.5) * 0.015;
    this.recoilVelZ += 0.128;
    this.recoilVelY += -0.055;
    this.recoilVelTwist += 0.020 + yawKick;
    this.flashTimer = 0.088;
  }

  /**
   * 每帧更新。
   * @param dt       帧时间（秒）
   * @param moving   是否移动
   * @param sprinting 是否冲刺
   * @param mouseDX  鼠标水平位移（用于惯性晃动）
   * @param mouseDY  鼠标垂直位移
   */
  update(dt: number, moving: boolean, sprinting: boolean, mouseDX = 0, mouseDY = 0): void {
    // GLB 骨骼动画推进
    this._mixer?.update(dt);

    this.time += dt;
    this.moveBlend = THREE.MathUtils.damp(this.moveBlend, moving ? 1 : 0, 9.5, dt);
    this.sprintBlend = THREE.MathUtils.damp(this.sprintBlend, sprinting ? 1 : 0, 8.0, dt);

    /* 鼠标惯性晃动（弹簧） */
    const swK = 78;
    const swD = 11;
    const swayScale = 1.0 - this.sprintBlend * 0.15;
    this.swayVelX += mouseDX * 0.00030 * swayScale + (-swK * this.swayX - swD * this.swayVelX) * dt;
    this.swayVelY += mouseDY * 0.00022 * swayScale + (-swK * this.swayY - swD * this.swayVelY) * dt;
    this.swayX = THREE.MathUtils.clamp(this.swayX + this.swayVelX * dt, -0.028, 0.028);
    this.swayY = THREE.MathUtils.clamp(this.swayY + this.swayVelY * dt, -0.018, 0.018);

    /* 弹簧后座（Z/Y/Twist 三轴） */
    const rK = 175, rD = 15;
    this.recoilVelZ     += (-rK * this.recoilZ     - rD * this.recoilVelZ)     * dt;
    this.recoilZ        += this.recoilVelZ * dt;
    this.recoilVelY     += (-rK * this.recoilY     - rD * this.recoilVelY)     * dt;
    this.recoilY        += this.recoilVelY * dt;
    this.recoilVelTwist += (-rK * this.recoilTwist - rD * this.recoilVelTwist) * dt;
    this.recoilTwist    += this.recoilVelTwist * dt;

    /* 行走/冲刺晃动 */
    const bobAmp = 0.0025 + this.moveBlend * 0.010 + this.sprintBlend * 0.010;
    const bobFreq = 2.0 + this.moveBlend * 3.6 + this.sprintBlend * 3.2;
    const bobY = Math.sin(this.time * bobFreq) * bobAmp;
    const bobX = Math.cos(this.time * bobFreq * 0.5) * bobAmp * 0.62;
    const breathe = Math.sin(this.time * 1.8) * 0.0018 * (1 - this.moveBlend * 0.7);
    const sprintPosX = this.sprintBlend * 0.040;
    const sprintPosY = this.sprintBlend * -0.040;
    const sprintPosZ = this.sprintBlend * 0.045;
    const sprintRotX = this.sprintBlend * 0.20;
    const sprintRotY = this.sprintBlend * 0.22;
    const sprintRotZ = this.sprintBlend * -0.12;

    /* 应用变换 */
    this.group.position.set(
      this.basePos.x + bobX + this.swayX + sprintPosX,
      this.basePos.y + bobY + this.swayY + breathe + sprintPosY,
      this.basePos.z + this.recoilZ + sprintPosZ,
    );
    this.group.rotation.set(
      this.baseRot.x + this.recoilY - this.swayY * 2.8 + sprintRotX,
      this.baseRot.y + this.swayX   * 2.2 + sprintRotY,
      this.baseRot.z + this.recoilTwist - this.swayX * 0.8 + sprintRotZ,
    );

    /* 枪口火焰衰减 */
    if (this.flashTimer > 0) {
      this.flashTimer = Math.max(0, this.flashTimer - dt);
      const k = this.flashTimer / 0.088;
      for (const fp of this.flashPlanes) {
        (fp.material as THREE.MeshBasicMaterial).opacity = k * 0.92;
        fp.rotation.z += dt * 11;
      }
      this.muzzle.intensity = k * 4.6;
    } else {
      for (const fp of this.flashPlanes) {
        (fp.material as THREE.MeshBasicMaterial).opacity = 0;
      }
      this.muzzle.intensity = 0;
    }
  }
}

