/**
 * ShellEjection — 抛壳系统（对象池 + 简易物理 + PBR 黄铜）
 *
 * 设计要点：
 *  · 32 个壳的循环对象池（够用 1 秒高射速 + 衰减重叠不可见）
 *  · 简易半物理：重力 + 地面反弹 + 角速度 + 寿命
 *  · 黄铜 MeshPhysicalMaterial：metalness=1.0 / roughness=0.35 / clearcoat
 *  · 抛壳点位于相机右下方约 0.18m 处（射出方向：相机右 + 上 + 微随机）
 *  · 每帧 update 推进物理；寿命满后归位回池
 *
 * 调用：ejectAt(camera) 在 weapon:fire 触发时调用。
 */
import * as THREE from 'three';

const POOL_SIZE = 32;
const SHELL_LIFE = 2.6;  // 秒
const GRAVITY = -9.8;
const FLOOR_Y = 0.0;     // 地面高度（机房地板）
const RESTITUTION = 0.35;
const FRICTION = 0.78;

interface ShellState {
  mesh: THREE.Mesh;
  vel: THREE.Vector3;
  angVel: THREE.Vector3;
  life: number;
  active: boolean;
}

export class ShellEjection {
  private readonly group: THREE.Group;
  private readonly shells: ShellState[] = [];
  private nextIdx = 0;

  constructor(scene: THREE.Scene) {
    this.group = new THREE.Group();
    this.group.name = 'shellEjection';
    scene.add(this.group);

    // 黄铜材质：单实例共享
    const brassMat = new THREE.MeshPhysicalMaterial({
      color: 0xc9a45a,
      metalness: 1.0,
      roughness: 0.35,
      clearcoat: 0.6,
      clearcoatRoughness: 0.2,
      emissive: 0x1a1006,
      emissiveIntensity: 0.2,
    });
    // 9mm 弹壳尺寸：高 1.9cm × Φ0.95cm（缩为 1.4× 便于看清）
    const shellGeo = new THREE.CylinderGeometry(0.0067, 0.0072, 0.0266, 8, 1, false);

    for (let i = 0; i < POOL_SIZE; i++) {
      const m = new THREE.Mesh(shellGeo, brassMat);
      m.visible = false;
      m.castShadow = false;
      this.group.add(m);
      this.shells.push({
        mesh: m,
        vel: new THREE.Vector3(),
        angVel: new THREE.Vector3(),
        life: 0,
        active: false,
      });
    }
  }

  /**
   * 在相机当前位置 + 朝向触发抛壳。
   * 抛出方向：相机右 +1.6m/s, 上 +1.0m/s, 随机扰动 ±0.4。
   */
  ejectAt(camera: THREE.Camera): void {
    const slot = this.shells[this.nextIdx];
    this.nextIdx = (this.nextIdx + 1) % POOL_SIZE;

    const m = slot.mesh;
    // 起点：相机本地 (0.18, -0.18, -0.30) 转到世界
    const localOrigin = new THREE.Vector3(0.18, -0.18, -0.30);
    localOrigin.applyMatrix4(camera.matrixWorld);
    m.position.copy(localOrigin);

    // 速度：相机右轴主导 + 一点上 + 一点后
    const right = new THREE.Vector3();
    const up = new THREE.Vector3();
    const fwd = new THREE.Vector3();
    camera.matrixWorld.extractBasis(right, up, fwd);
    // fwd 实际是 -Z，camera 看向 -fwd
    slot.vel
      .copy(right).multiplyScalar(1.8 + Math.random() * 0.4)
      .addScaledVector(up, 1.1 + Math.random() * 0.35)
      .addScaledVector(fwd, 0.4 + Math.random() * 0.2); // +Z 表示向相机后

    slot.angVel.set(
      (Math.random() - 0.5) * 26,
      (Math.random() - 0.5) * 22,
      (Math.random() - 0.5) * 30,
    );

    m.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI);
    m.visible = true;
    slot.life = SHELL_LIFE;
    slot.active = true;
  }

  update(dt: number): void {
    for (const s of this.shells) {
      if (!s.active) continue;
      s.life -= dt;
      if (s.life <= 0) {
        s.active = false;
        s.mesh.visible = false;
        continue;
      }

      // 半透明淡出（最后 0.5 秒）
      if (s.life < 0.5) {
        const k = s.life / 0.5;
        const mat = s.mesh.material as THREE.MeshPhysicalMaterial;
        // 共享材质，不能改透明度。改用缩放衰减作为视觉淡出。
        const sc = 0.7 + k * 0.3;
        s.mesh.scale.set(sc, sc, sc);
        void mat;
      } else {
        s.mesh.scale.set(1, 1, 1);
      }

      // 物理推进
      s.vel.y += GRAVITY * dt;
      s.mesh.position.addScaledVector(s.vel, dt);
      s.mesh.rotation.x += s.angVel.x * dt;
      s.mesh.rotation.y += s.angVel.y * dt;
      s.mesh.rotation.z += s.angVel.z * dt;

      // 地面反弹
      if (s.mesh.position.y < FLOOR_Y) {
        s.mesh.position.y = FLOOR_Y;
        s.vel.y = -s.vel.y * RESTITUTION;
        s.vel.x *= FRICTION;
        s.vel.z *= FRICTION;
        s.angVel.multiplyScalar(0.6);
        // 速度过低时固化
        if (Math.abs(s.vel.y) < 0.2 && s.vel.lengthSq() < 0.04) {
          s.vel.set(0, 0, 0);
          s.angVel.set(0, 0, 0);
          // 让壳侧躺
          s.mesh.rotation.x = Math.PI / 2;
        }
      }
    }
  }

  dispose(): void {
    for (const s of this.shells) {
      s.mesh.geometry.dispose();
    }
    const mat = this.shells[0]?.mesh.material as THREE.MeshPhysicalMaterial | undefined;
    mat?.dispose();
    this.group.parent?.remove(this.group);
  }
}
