/**
 * 子弹弹孔 decal 系统 —— 预分配 48 个小圆盘，循环使用。
 * 屏幕上显示裂痕，金属/墙面显示暗色圆点。
 */
import * as THREE from 'three';

const MAX = 48;

function makeCrackTexture(isScreen: boolean): THREE.CanvasTexture {
  const S = 128;
  const canvas = document.createElement('canvas');
  canvas.width = S;
  canvas.height = S;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.clearRect(0, 0, S, S);
    const cx = S / 2;
    const cy = S / 2;
    // 中心黑洞
    const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, S / 2);
    if (isScreen) {
      grad.addColorStop(0, 'rgba(10, 10, 20, 1)');
      grad.addColorStop(0.15, 'rgba(60, 180, 255, 0.9)');
      grad.addColorStop(0.35, 'rgba(20, 40, 80, 0.5)');
      grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
    } else {
      grad.addColorStop(0, 'rgba(0, 0, 0, 1)');
      grad.addColorStop(0.2, 'rgba(30, 30, 30, 0.9)');
      grad.addColorStop(0.5, 'rgba(60, 60, 60, 0.4)');
      grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
    }
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(cx, cy, S / 2, 0, Math.PI * 2);
    ctx.fill();
    // 裂纹放射线（屏幕更明显）
    const lineColor = isScreen ? 'rgba(120,220,255,0.9)' : 'rgba(40,40,40,0.7)';
    ctx.strokeStyle = lineColor;
    ctx.lineWidth = isScreen ? 2 : 1.2;
    const crackCount = isScreen ? 9 : 5;
    for (let i = 0; i < crackCount; i++) {
      const ang = (Math.PI * 2 * i) / crackCount + Math.random() * 0.3;
      const len = S * (0.2 + Math.random() * 0.25);
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      // zig-zag 裂纹
      let x = cx;
      let y = cy;
      const steps = 3;
      for (let s = 1; s <= steps; s++) {
        const t = s / steps;
        const jitter = (Math.random() - 0.5) * 8;
        x = cx + Math.cos(ang) * len * t + Math.cos(ang + Math.PI / 2) * jitter;
        y = cy + Math.sin(ang) * len * t + Math.sin(ang + Math.PI / 2) * jitter;
        ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    // 屏幕特效：额外的像素扰动方块
    if (isScreen) {
      for (let i = 0; i < 12; i++) {
        const ang = Math.random() * Math.PI * 2;
        const r = Math.random() * S * 0.35;
        ctx.fillStyle = `rgba(${Math.floor(Math.random() * 100 + 80)}, ${Math.floor(
          Math.random() * 160 + 80,
        )}, 255, 0.7)`;
        ctx.fillRect(cx + Math.cos(ang) * r - 2, cy + Math.sin(ang) * r - 2, 4, 4);
      }
    }
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export type ImpactKind = 'screen' | 'metal' | 'wall';

export class BulletImpactSystem {
  private readonly scene: THREE.Scene;
  private readonly pool: THREE.Mesh[] = [];
  private cursor = 0;
  private readonly matScreen: THREE.MeshBasicMaterial;
  private readonly matMetal: THREE.MeshBasicMaterial;

  constructor(scene: THREE.Scene) {
    this.scene = scene;
    this.matScreen = new THREE.MeshBasicMaterial({
      map: makeCrackTexture(true),
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    this.matMetal = new THREE.MeshBasicMaterial({
      map: makeCrackTexture(false),
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    // pool: 复用同一个 geometry
    const geom = new THREE.PlaneGeometry(0.22, 0.22);
    for (let i = 0; i < MAX; i++) {
      const mesh = new THREE.Mesh(geom, this.matMetal);
      mesh.visible = false;
      mesh.renderOrder = 2;
      this.scene.add(mesh);
      this.pool.push(mesh);
    }
  }

  /** 在命中点按法线方向贴一枚弹孔 */
  spawn(point: THREE.Vector3, normal: THREE.Vector3, kind: ImpactKind): void {
    const mesh = this.pool[this.cursor];
    this.cursor = (this.cursor + 1) % MAX;
    mesh.material = kind === 'screen' ? this.matScreen : this.matMetal;
    // 略微向外偏移避免 z-fighting
    const offset = 0.008;
    mesh.position.copy(point).addScaledVector(normal, offset);
    // 使 plane 的 +Z 朝法线方向
    const up = Math.abs(normal.y) > 0.95 ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 1, 0);
    const m = new THREE.Matrix4().lookAt(new THREE.Vector3(0, 0, 0), normal, up);
    mesh.quaternion.setFromRotationMatrix(m);
    // 随机旋转让多个弹孔不一样
    mesh.rotateZ(Math.random() * Math.PI * 2);
    // 随机大小
    const scale = kind === 'screen' ? 0.7 + Math.random() * 0.5 : 0.5 + Math.random() * 0.4;
    mesh.scale.setScalar(scale);
    mesh.visible = true;
  }
}
