export class TutorialPrompts {
  private fired: Set<string> = new Set();
  private bugKills = 0;
  private timers: number[] = [];

  start(): void {
    // 进入游戏后 6 秒，提示一次基础控制
    this.schedule(6000, () =>
      this.show('boot_basic', {
        title: '基础控制',
        body: 'WASD 移动｜Shift 冲刺｜空格跳跃｜鼠标右键瞄准｜1~6 切换工具｜Q 投手雷｜E 交互。',
        duration: 6500,
      }),
    );

    EventBus.on('weapon:fire', () => this.show('weapon_fire', PLAY_TIPS.weapon_fire));
    EventBus.on('weapon:reload_start', () => this.show('weapon_reload', PLAY_TIPS.weapon_reload));
    EventBus.on('tool:switch', () => this.show('tool_switch', PLAY_TIPS.tool_switch));
    EventBus.on('grenade:thrown', () => this.show('grenade_thrown', PLAY_TIPS.grenade_thrown));
    EventBus.on('player:died', () => this.show('player_died', PLAY_TIPS.player_died));

    EventBus.on('bug:killed', () => {
      this.bugKills++;
      if (this.bugKills === 1) this.show('bug_first_kill', PLAY_TIPS.bug_first_kill);
    });

    EventBus.on('pickup:health', () => this.show('pickup_health', PLAY_TIPS.pickup_health));
    EventBus.on('pickup:armor', () => this.show('pickup_armor', PLAY_TIPS.pickup_armor));
    EventBus.on('pickup:ammo', () => this.show('pickup_ammo', PLAY_TIPS.pickup_ammo));
    EventBus.on('pickup:grenade', () => this.show('pickup_grenade', PLAY_TIPS.pickup_grenade));

    EventBus.on('mission:change', ({ act }: { act: { id: ActId } }) => {
      const tip = ACT_SOP_TIPS[act.id];
      if (!tip) return;
      const delay = tip.delayMs ?? 0;
      this.schedule(delay, () => this.show(`act_sop_${act.id}`, tip));
    });
  }

  private schedule(delay: number, fn: () => void): void {
    const id = window.setTimeout(fn, delay);
    this.timers.push(id);
  }

  private show(key: string, tip: TipDef): void {
    if (this.fired.has(key)) return;
    this.fired.add(key);
    uiStore.setTutorialTip(tip.title, tip.body, tip.duration ?? 4500);
  }

  dispose(): void {
    for (const t of this.timers) window.clearTimeout(t);
    this.timers = [];
  }
}
