/**
 * VolumetricAtmosphere — 体积光柱 + 浮尘粒子
 *
 * 在浏览器 WebGL2 不做真正的体积渲染（性能开销过大），
 * 改用低成本视觉替身：
 *
 * 1) **God Rays / Light Shafts**：从天花板灯条向下的半透明圆锥体（叠加 Additive blending），
 *    位置由外部传入（机柜顶 LED 阵列的几个关键点），微微飘动。
 *
 * 2) **浮尘 Motes**：1500 个发光小点（Points + ShaderMaterial），
 *    充满整个机房，缓慢上升，靠近光源时变亮。
 *
 * 调用：new VolumetricAtmosphere(scene, beamPositions); update(dt) 每帧。
 */
import * as THREE from 'three';

export interface AtmosphereConfig {
  beamColor?: number;
  beamIntensity?: number;
  beamRadius?: number;
  beamHeight?: number;
  moteCount?: number;
  moteColor?: number;
  bounds?: { min: THREE.Vector3; max: THREE.Vector3 };
}

const DEFAULT_BOUNDS = {
  min: new THREE.Vector3(-30, 0, -30),
  max: new THREE.Vector3(30, 5, 30),
};

export class VolumetricAtmosphere {
  private readonly group: THREE.Group;
  private readonly beams: THREE.Mesh[] = [];
  private readonly motes: THREE.Points;
  private readonly motesGeo: THREE.BufferGeometry;
  private readonly bounds: { min: THREE.Vector3; max: THREE.Vector3 };
  private time = 0;

  constructor(
    scene: THREE.Scene,
    beamPositions: THREE.Vector3[],
    cfg: AtmosphereConfig = {},
  ) {
    const beamColor = cfg.beamColor ?? 0x6ec1ff;
    const beamIntensity = cfg.beamIntensity ?? 0.30;
    const beamRadius = cfg.beamRadius ?? 0.55;
    const beamHeight = cfg.beamHeight ?? 4.6;
    const moteCount = cfg.moteCount ?? 1500;
    const moteColor = cfg.moteColor ?? 0x9bb6d6;
    this.bounds = cfg.bounds ?? DEFAULT_BOUNDS;

    this.group = new THREE.Group();
    this.group.name = 'volumetricAtmosphere';
    scene.add(this.group);

    // —— God ray 圆锥（顶大底小，倒立）——
    const beamGeo = new THREE.CylinderGeometry(
      beamRadius * 0.20,  // 顶部小半径（聚于灯具）
      beamRadius * 1.4,   // 底部大半径
      beamHeight,
      14, 1, true,        // 开口圆柱，省 1 个面
    );
    const beamMat = new THREE.ShaderMaterial({
      uniforms: {
        color: { value: new THREE.Color(beamColor) },
        intensity: { value: beamIntensity },
        time: { value: 0 },
      },
      vertexShader: `
        varying vec3 vWorldPos;
        varying vec2 vUv;
        void main() {
          vUv = uv;
          vec4 wp = modelMatrix * vec4(position, 1.0);
          vWorldPos = wp.xyz;
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: `
        uniform vec3 color;
        uniform float intensity;
        uniform float time;
        varying vec2 vUv;
        varying vec3 vWorldPos;
        void main() {
          // 顶部 (uv.y=1) 强、底部 (uv.y=0) 弱
          float vertical = smoothstep(0.0, 1.0, vUv.y);
          // 中心强、边缘弱（柔和）
          float radial = 1.0 - abs(vUv.x * 2.0 - 1.0);
          radial = pow(radial, 1.4);
          // 噪声扰动（简易 fbm 替代）
          float n = sin(vWorldPos.y * 1.2 + time * 0.7)
                  * cos(vWorldPos.x * 0.9 - time * 0.5);
          float a = vertical * radial * (0.85 + 0.15 * n) * intensity;
          gl_FragColor = vec4(color, a);
        }
      `,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
    });

    for (const pos of beamPositions) {
      const beam = new THREE.Mesh(beamGeo, beamMat);
      beam.position.copy(pos);
      // 圆柱默认 +Y 高，需要让它从天花板下挂：position 即天花板灯位
      beam.position.y -= beamHeight / 2;
      this.beams.push(beam);
      this.group.add(beam);
    }

    // —— 浮尘 Motes ——
    const positions = new Float32Array(moteCount * 3);
    const speeds = new Float32Array(moteCount);
    const phases = new Float32Array(moteCount);
    const sz = this.bounds.max.clone().sub(this.bounds.min);
    for (let i = 0; i < moteCount; i++) {
      positions[i * 3 + 0] = this.bounds.min.x + Math.random() * sz.x;
      positions[i * 3 + 1] = this.bounds.min.y + Math.random() * sz.y;
      positions[i * 3 + 2] = this.bounds.min.z + Math.random() * sz.z;
      speeds[i] = 0.05 + Math.random() * 0.10;
      phases[i] = Math.random() * Math.PI * 2;
    }
    this.motesGeo = new THREE.BufferGeometry();
    this.motesGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    this.motesGeo.setAttribute('aSpeed', new THREE.BufferAttribute(speeds, 1));
    this.motesGeo.setAttribute('aPhase', new THREE.BufferAttribute(phases, 1));

    const moteMat = new THREE.ShaderMaterial({
      uniforms: {
        time: { value: 0 },
        color: { value: new THREE.Color(moteColor) },
        boundsMinY: { value: this.bounds.min.y },
        boundsMaxY: { value: this.bounds.max.y },
      },
      vertexShader: `
        attribute float aSpeed;
        attribute float aPhase;
        uniform float time;
        uniform float boundsMinY;
        uniform float boundsMaxY;
        varying float vAlpha;
        void main() {
          vec3 p = position;
          // 缓慢上升 + 水平摆
          float t = time * aSpeed;
          p.y = mod(p.y + t * 0.6 - boundsMinY, boundsMaxY - boundsMinY) + boundsMinY;
          p.x += sin(time * 0.4 + aPhase) * 0.04;
          p.z += cos(time * 0.32 + aPhase * 1.3) * 0.04;
          vec4 mv = modelViewMatrix * vec4(p, 1.0);
          gl_Position = projectionMatrix * mv;
          // 远的更小、更暗
          float d = -mv.z;
          gl_PointSize = clamp(2.4 / d * 60.0, 0.6, 3.0);
          vAlpha = clamp(1.0 - d / 35.0, 0.0, 1.0) * (0.4 + 0.4 * sin(time + aPhase * 4.0));
        }
      `,
      fragmentShader: `
        uniform vec3 color;
        varying float vAlpha;
        void main() {
          // 圆形 sprite
          vec2 c = gl_PointCoord - 0.5;
          float d = dot(c, c);
          if (d > 0.25) discard;
          float a = (1.0 - d * 4.0) * vAlpha * 0.65;
          gl_FragColor = vec4(color, a);
        }
      `,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });

    this.motes = new THREE.Points(this.motesGeo, moteMat);
    this.motes.frustumCulled = false;
    this.group.add(this.motes);
  }

  update(dt: number): void {
    this.time += dt;
    if (this.beams.length > 0) {
      const mat = this.beams[0].material as THREE.ShaderMaterial;
      mat.uniforms.time.value = this.time;
    }
    const mMat = this.motes.material as THREE.ShaderMaterial;
    mMat.uniforms.time.value = this.time;
  }

  dispose(): void {
    for (const b of this.beams) b.geometry.dispose();
    if (this.beams[0]) (this.beams[0].material as THREE.Material).dispose();
    this.motesGeo.dispose();
    (this.motes.material as THREE.Material).dispose();
    this.group.parent?.remove(this.group);
  }
}
