export interface QuizAttempt {
  questionId: string;
  chosen: string;
  correct: boolean;
}

export class QuizSession {
  private index = 0;
  private attempts: QuizAttempt[] = [];
  constructor(private readonly questions: QuizQuestion[]) {}

  current(): QuizQuestion | null {
    return this.questions[this.index] ?? null;
  }
  total(): number {
    return this.questions.length;
  }
  currentIndex(): number {
    return this.index;
  }

  answer(key: string): { correct: boolean; explanation: string; done: boolean } {
    const q = this.questions[this.index];
    if (!q) return { correct: false, explanation: '', done: true };
    const correct = q.answer === key;
    this.attempts.push({ questionId: q.id, chosen: key, correct });
    this.index++;
    return { correct, explanation: q.explanation, done: this.index >= this.questions.length };
  }

  score(): { correct: number; total: number; pct: number } {
    const correct = this.attempts.filter((a) => a.correct).length;
    return { correct, total: this.questions.length, pct: correct / this.questions.length };
  }

  attemptsList(): QuizAttempt[] {
    return [...this.attempts];
  }
}
