/**
 * 射击系统 —— 左键开火、raycast 命中、弹药/换弹、屏幕后座 + 击中反馈。
 *
 * 与 SmartX 迁移流程解耦：单纯提供 CS 风格的射击反馈；
 * 命中 Bug VM 敌人时通过 BugEnemies.damage 结算并加分。
 */
import * as THREE from 'three';
import { EventBus } from '../core/EventBus';
import type { BugEnemies } from '../engine/BugEnemies';
import type { VMHologram } from '../engine/MissionObjects';
import type { BulletImpactSystem, ImpactKind } from '../engine/BulletImpact';
import type { WeaponViewmodel } from './WeaponViewmodel';
import type { PlayerController } from './PlayerController';
import { synthAudio } from '../audio/SynthAudio';

export type WeaponId = 'pistol' | 'rifle' | 'scanner';

export interface WeaponProfile {
  id: WeaponId;
  name: string;
  magSize: number;

  /** 老字段：保留向后兼容（=emptyReloadMs） */
  reloadTimeMs: number;
  /** 新：弹仓未空时的战术换弹（更快） */
  tacticalReloadMs: number;
  /** 新：弹仓打空后的换弹时长 */
  emptyReloadMs: number;

  fireIntervalMs: number;
  damage: number;

  /** 基础（最小）散布角度 */
  bulletSpread: number;
  /** 新：每发开火带来的散布增量 */
  recoilSpread: number;
  /** 新：当前累积散布的最大值 */
  maxSpread: number;
  /** 新：散布从满到 0 的恢复时间（秒） */
  recoilRecoverSec: number;
  /** 新：首发精度奖励倍率（[0,1]，0=完全压点） */
  firstShotMultiplier: number;
  /** 新：连续保持极小散布的窗口（毫秒），超过这段就开始累积散布 */
  firstShotWindowMs: number;

  sfx: 'gunshot_pistol' | 'gunshot_rifle' | 'gunshot_scanner';
  canMarkVM: boolean; // 仅扫描枪可标记 VM
  tracerColor: number;
}

