/**
 * AdsSystem — Aim Down Sights（瞄准镜）系统
 *
 * 设计：
 *  · 监听鼠标右键 down/up（pointerLock 期间）
 *  · 在 ADS 时：camera.fov 从 75 平滑 lerp 到 50（150ms ease-out）
 *  · viewmodel.group 平移到屏幕中心 + 略下沉（让红点对准准星）
 *  · 散布同步收紧（外部通过 isAdsActive() 查询）
 *  · 冲刺时强制取消 ADS（cod 同款行为）
 *
 * 副作用：直接修改 camera.fov 与 viewmodel.group.position（构造时记录基础位）。
 */
import * as THREE from 'three';
import type { WeaponViewmodel } from './WeaponViewmodel';

export interface AdsConfig {
  baseFov: number;         // 默认视场角
  adsFov: number;          // ADS 视场角
  enterSec: number;        // 进入 ADS 时间
  exitSec: number;         // 退出 ADS 时间
  adsLocalPos: [number, number, number]; // ADS 时 viewmodel.basePos 偏移目标
  adsLocalRot: [number, number, number]; // ADS 时 viewmodel.baseRot 偏移目标
}

const DEFAULT_CFG: AdsConfig = {
  baseFov: 75,
  adsFov: 50,
  enterSec: 0.15,
  exitSec: 0.10,
  adsLocalPos: [0.0, -0.18, -0.32],
  adsLocalRot: [0.0, 0.0, 0.0],
};

export class AdsSystem {
  private readonly cfg: AdsConfig;
  private active = false;            // 用户意图
  private blend = 0;                 // 0=hip, 1=full ads
  private vmBasePos: THREE.Vector3 | null = null;
  private vmBaseRot: THREE.Euler | null = null;
  private isSprintingFn: () => boolean = () => false;
  private isPointerLockedFn: () => boolean;

  constructor(
    private readonly camera: THREE.PerspectiveCamera,
    private readonly viewmodel: WeaponViewmodel,
    isPointerLockedFn: () => boolean,
    cfg?: Partial<AdsConfig>,
  ) {
    this.cfg = { ...DEFAULT_CFG, ...cfg };
    this.isPointerLockedFn = isPointerLockedFn;

    // 记录 viewmodel 当前基础姿态，作为 hip 状态
    const g = viewmodel.group;
    this.vmBasePos = g.position.clone();
    this.vmBaseRot = g.rotation.clone();

    camera.fov = this.cfg.baseFov;
    camera.updateProjectionMatrix();

    // 监听右键
    window.addEventListener('mousedown', this._onDown);
    window.addEventListener('mouseup', this._onUp);
    // 失去焦点时强制松开
    window.addEventListener('blur', () => { this.active = false; });
  }

  /** 由外部传入 sprint 检测（PlayerController.state.isSprinting） */
  bindSprintProbe(fn: () => boolean): void { this.isSprintingFn = fn; }

  isAdsActive(): boolean { return this.blend > 0.5; }
  /** 用于散布乘子（0 → 1）；ADS 时收紧到 0.35× */
  spreadMultiplier(): number {
    return THREE.MathUtils.lerp(1.0, 0.35, this.blend);
  }
  /** 0..1 平滑值，可供其他系统（如灵敏度衰减）使用 */
  blendValue(): number { return this.blend; }

  private _onDown = (e: MouseEvent): void => {
    if (e.button !== 2) return;
    if (!this.isPointerLockedFn()) return;
    this.active = true;
  };
  private _onUp = (e: MouseEvent): void => {
    if (e.button !== 2) return;
    this.active = false;
  };

  update(dt: number): void {
    // 冲刺时禁用
    const desired = this.active && !this.isSprintingFn() ? 1 : 0;
    const dur = desired > this.blend ? this.cfg.enterSec : this.cfg.exitSec;
    const k = Math.min(1, dt / Math.max(0.001, dur));
    this.blend = THREE.MathUtils.lerp(this.blend, desired, k * 1.5);
    if (Math.abs(this.blend - desired) < 0.002) this.blend = desired;

    // ease-out cubic
    const t = 1 - Math.pow(1 - this.blend, 3);

    // FOV 插值
    this.camera.fov = THREE.MathUtils.lerp(this.cfg.baseFov, this.cfg.adsFov, t);
    this.camera.updateProjectionMatrix();

    // viewmodel basePos 漂移到 ADS 位（由 viewmodel update 后再次叠加 bob/recoil/sway）
    // 注意：viewmodel.update() 每帧重写 group.position/rotation 为
    // basePos + bob + sway + sprint... 所以我们这里在它之后叠加。
    // 实际方案：在 viewmodel update 之后调用 applyAdsTransform()。
    void t;
  }

  /**
   * 在 viewmodel.update() 之后叠加 ADS 偏移。
   * t = blend 值 [0,1]
   */
  applyAdsTransform(): void {
    if (!this.vmBasePos || !this.vmBaseRot) return;
    const t = 1 - Math.pow(1 - this.blend, 3);
    const g = this.viewmodel.group;
    // 在 viewmodel 写完的位置上，再向 ads 位差值漂移
    g.position.x += (this.cfg.adsLocalPos[0] - this.vmBasePos.x) * t;
    g.position.y += (this.cfg.adsLocalPos[1] - this.vmBasePos.y) * t;
    g.position.z += (this.cfg.adsLocalPos[2] - this.vmBasePos.z) * t;
    g.rotation.x += (this.cfg.adsLocalRot[0] - this.vmBaseRot.x) * t;
    g.rotation.y += (this.cfg.adsLocalRot[1] - this.vmBaseRot.y) * t;
    g.rotation.z += (this.cfg.adsLocalRot[2] - this.vmBaseRot.z) * t;
  }

  dispose(): void {
    window.removeEventListener('mousedown', this._onDown);
    window.removeEventListener('mouseup', this._onUp);
  }
}
