/**
 * 场景装饰 —— 真实机房的配线槽、PDU、顶部灯管。
 * （已移除 CS 风格木箱/金属掩体，改为数据中心原生视觉语言。）
 */
import * as THREE from 'three';
import type { CollisionSystem } from '../fps/CollisionSystem';

/** 落地式 PDU 电源分配单元（黑色细长柜） */
function addPDU(
  scene: THREE.Scene,
  collision: CollisionSystem,
  x: number,
  z: number,
): void {
  const group = new THREE.Group();
  group.position.set(x, 0, z);
  const body = new THREE.Mesh(
    new THREE.BoxGeometry(0.18, 1.6, 0.22),
    new THREE.MeshStandardMaterial({ color: 0x0e1014, metalness: 0.7, roughness: 0.45 }),
  );
  body.position.y = 0.8;
  group.add(body);
  // 插座面板
  for (let i = 0; i < 6; i++) {
    const socket = new THREE.Mesh(
      new THREE.BoxGeometry(0.1, 0.1, 0.005),
      new THREE.MeshStandardMaterial({ color: 0x222428, roughness: 0.9 }),
    );
    socket.position.set(0, 0.35 + i * 0.2, 0.113);
    group.add(socket);
    // 通电红点
    const led = new THREE.Mesh(
      new THREE.PlaneGeometry(0.015, 0.015),
      new THREE.MeshBasicMaterial({ color: 0xff5533 }),
    );
    led.position.set(0.06, 0.35 + i * 0.2 + 0.035, 0.116);
    group.add(led);
  }
  scene.add(group);
  collision.add({ box: new THREE.Box3().setFromObject(body), solid: true });
}

/** 吊顶式桥架（电缆槽） */
function addCableTray(
  scene: THREE.Scene,
  x1: number,
  x2: number,
  z: number,
  y = 2.72,
): void {
  const len = Math.abs(x2 - x1);
  const tray = new THREE.Mesh(
    new THREE.BoxGeometry(len, 0.05, 0.35),
    new THREE.MeshStandardMaterial({ color: 0x2a2d32, metalness: 0.7, roughness: 0.55 }),
  );
  tray.position.set((x1 + x2) / 2, y, z);
  scene.add(tray);
  // 桥架里多根电缆（橙/黑/蓝三色）
  const cableColors = [0x4a3020, 0x141518, 0x203848];
  for (let i = 0; i < 3; i++) {
    const cable = new THREE.Mesh(
      new THREE.CylinderGeometry(0.025, 0.025, len, 8),
      new THREE.MeshStandardMaterial({ color: cableColors[i], roughness: 0.85 }),
    );
    cable.rotation.z = Math.PI / 2;
    cable.position.set((x1 + x2) / 2, y - 0.015, z - 0.08 + i * 0.08);
    scene.add(cable);
  }
}

/** 天花板灯管 */
function addCeilingStrip(scene: THREE.Scene, x: number, z: number, len = 4): void {
  const strip = new THREE.Mesh(
    new THREE.BoxGeometry(0.12, 0.04, len),
    new THREE.MeshStandardMaterial({
      color: 0xccf2ff,
      emissive: 0xd0d4da,
      emissiveIntensity: 0.30,
    }),
  );
  strip.position.set(x, 2.92, z);
  scene.add(strip);
  // 灯管外框
  const frame = new THREE.Mesh(
    new THREE.BoxGeometry(0.18, 0.06, len + 0.08),
    new THREE.MeshStandardMaterial({ color: 0x1a1c20, metalness: 0.6, roughness: 0.5 }),
  );
  frame.position.set(x, 2.905, z);
  scene.add(frame);
}

/** 数据管线（走廊吊顶的线缆） */
function addCableRun(scene: THREE.Scene, x1: number, x2: number, y = 2.7): void {
  const tube = new THREE.Mesh(
    new THREE.CylinderGeometry(0.04, 0.04, Math.abs(x2 - x1), 8),
    new THREE.MeshStandardMaterial({
      color: 0x1a1c22,
      roughness: 0.85,
    }),
  );
  tube.rotation.z = Math.PI / 2;
  tube.position.set((x1 + x2) / 2, y, 0);
  scene.add(tube);
}

export interface DecorBugSpawn {
  position: [number, number, number];
}

/** 布置所有装饰，并返回适合放 Bug VM 敌人的出生点 */
export function buildSceneDecor(
  scene: THREE.Scene,
  collision: CollisionSystem,
): { bugSpawns: DecorBugSpawn[] } {
  // ---- 天花板灯管（柔和的主照明、每房间布 3 条）----
  for (let x = -18; x <= 18; x += 3) {
    addCeilingStrip(scene, x, 0, 2.5);
  }

  // ---- 网络间（左侧 -14, 0，10×10 房间）----
  // 这是 VMware → SmartX 迁移流程的关键房间，必须保留服务器机房的视觉语言
  // 沿后墙（x ≈ -18.3）布两台 PDU 电源柜 + 一台侧面 PDU
  addPDU(scene, collision, -18.3, -2.8);
  addPDU(scene, collision, -18.3, 2.8);
  addPDU(scene, collision, -16.0, -4.5);
  // 吊顶电缆桥架：从走廊一直延伸到网络间深处
  addCableTray(scene, -18.5, -10.5, 1.6, 2.7);
  addCableTray(scene, -18.5, -10.5, -1.6, 2.7);

  // ---- 存储间（右侧 14, 0，10×10 房间）----
  // 同样是迁移流程的关键房间，对称布置
  addPDU(scene, collision, 18.3, -2.8);
  addPDU(scene, collision, 18.3, 2.8);
  addPDU(scene, collision, 16.0, -4.5);
  addCableTray(scene, 18.5, 10.5, 1.6, 2.7);
  addCableTray(scene, 18.5, 10.5, -1.6, 2.7);

  // ---- 走廊与指挥台保持空旷（不再放阻挡物） ----

  // —— 全局环境光：柔和的暖白光，模拟普通机房灯泡照明
  // 主环境光：中性偏暖的灯泡色，充足亮度
  const ambient = new THREE.AmbientLight(0xfff2d8, 0.85);
  scene.add(ambient);
  // 天山光：从天花板均匀下夺，暖白
  const sky = new THREE.HemisphereLight(0xfff2d8, 0x2a2820, 0.65);
  sky.position.set(0, 4, 0);
  scene.add(sky);
  // 辅光：轻微冷调，避免全色塔偏黄
  const fill = new THREE.DirectionalLight(0xeef0f4, 0.18);
  fill.position.set(0, 8, 6);
  scene.add(fill);

  // ---- Bug 敌人出生点（走廊 + 各房间 + 机柜区） ----
  const bugSpawns: DecorBugSpawn[] = [
    { position: [-7, 1.2, 0] },         // 左走廊
    { position: [7, 1.2, 0] },          // 右走廊
    { position: [-14, 1.4, 2.5] },      // 网络间
    { position: [14, 1.4, 2.5] },       // 存储间
    { position: [0, 1.4, -1.5] },       // 指挥台中央
    { position: [2.0, 1.4, -6.5] },     // 机柜区冷通道 1 入口
    { position: [-1.5, 1.4, -8.0] },    // 机柜区热通道 1
    { position: [2.5, 1.4, -10.0] },    // 机柜区冷通道 2
    { position: [-2.0, 1.4, -12.0] },   // 机柜区热通道 2
  ];

  return { bugSpawns };
}
