/**
 * RoomReverb — 机房卷积混响（无外部 IR 文件，程序合成）
 *
 * 用 Web Audio API 的 ConvolverNode 给所有 SynthAudio 输出加上
 * 中等大小机房的空间感：
 *  · 长 1.6 秒 IR
 *  · 立体声两通道独立衰减
 *  · 高频快衰减 + 低频慢衰减（机房地毯/吸音棉特征）
 *  · 干湿比可调（默认 dry 0.85 / wet 0.15）
 *
 * 接入方式：从 SynthAudio 拿到 master GainNode + AudioContext，
 * 在 master 与 destination 之间插入 [dry, wet→Convolver]。
 *
 * 这是一次性插入，不可重复 attach。
 */

interface SynthAudioLike {
  getContext?: () => AudioContext | null;
  getMasterNode?: () => GainNode | null;
}

export class RoomReverb {
  private ctx: AudioContext | null = null;
  private convolver: ConvolverNode | null = null;
  private dryGain: GainNode | null = null;
  private wetGain: GainNode | null = null;
  private attached = false;

  /**
   * 在 SynthAudio 的 master 后串入混响。需要 SynthAudio 提供
   * getContext()/getMasterNode() 两个公开方法（在 SynthAudio.ts 中扩展）。
   */
  attach(synth: SynthAudioLike, opts: { dry?: number; wet?: number; ir?: { durationSec?: number; rt60Sec?: number } } = {}): boolean {
    if (this.attached) return true;
    const ctx = synth.getContext?.() ?? null;
    const master = synth.getMasterNode?.() ?? null;
    if (!ctx || !master) return false;

    const dry = opts.dry ?? 0.85;
    const wet = opts.wet ?? 0.18;

    this.ctx = ctx;
    this.convolver = ctx.createConvolver();
    this.convolver.buffer = this._buildIR(ctx, opts.ir?.durationSec ?? 1.6, opts.ir?.rt60Sec ?? 1.2);

    this.dryGain = ctx.createGain();
    this.dryGain.gain.value = dry;
    this.wetGain = ctx.createGain();
    this.wetGain.gain.value = wet;

    // 断开 master → destination 默认连线，改为 master → [dry, wet→conv] → destination
    try {
      master.disconnect();
    } catch {
      /* ignore */
    }
    master.connect(this.dryGain);
    this.dryGain.connect(ctx.destination);

    master.connect(this.convolver);
    this.convolver.connect(this.wetGain);
    this.wetGain.connect(ctx.destination);

    this.attached = true;
    return true;
  }

  /**
   * 程序合成 IR：白噪声指数衰减 + 频率滤波模拟（在时域里做简单的低通近似）。
   * 双通道独立 → 自然立体声扩散。
   */
  private _buildIR(ctx: AudioContext, durationSec: number, rt60Sec: number): AudioBuffer {
    const sr = ctx.sampleRate;
    const length = Math.floor(sr * durationSec);
    const buf = ctx.createBuffer(2, length, sr);

    // RT60 映射到指数衰减系数
    const decay = Math.log(0.001) / rt60Sec;

    for (let ch = 0; ch < 2; ch++) {
      const data = buf.getChannelData(ch);
      // 早期反射（4-6 个离散冲击）
      const earlyTimes = ch === 0
        ? [0.011, 0.023, 0.038, 0.055, 0.074]
        : [0.013, 0.025, 0.041, 0.058, 0.078];
      const earlyGains = [0.55, 0.40, 0.28, 0.20, 0.14];
      for (let i = 0; i < earlyTimes.length; i++) {
        const idx = Math.floor(earlyTimes[i] * sr);
        if (idx < length) {
          data[idx] += earlyGains[i] * (ch === 0 ? 1 : -1);
        }
      }
      // 后期混响（白噪声 + 指数衰减 + 简单 1 阶低通）
      let prev = 0;
      const lpA = 0.42; // 低通系数（越大越闷）
      for (let i = 0; i < length; i++) {
        const t = i / sr;
        const env = Math.exp(decay * t);
        const noise = (Math.random() * 2 - 1) * env * 0.32;
        // 1 阶低通（机房高频被吸收）
        prev = prev * lpA + noise * (1 - lpA);
        data[i] += prev;
      }
    }
    return buf;
  }

  setWet(wet: number): void {
    if (this.wetGain) this.wetGain.gain.value = Math.max(0, Math.min(1, wet));
  }
  setDry(dry: number): void {
    if (this.dryGain) this.dryGain.gain.value = Math.max(0, Math.min(1, dry));
  }
}
