export class MissionNarrator {
  private current: ActId = 'ACT1_DEPLOY';
  private fired: Set<ActId> = new Set();
  private nudged: Set<string> = new Set();

  constructor() {
    EventBus.on('migration:stateChange', ({ next }: { next: MigrationState }) => {
      const act = this.mapStateToAct(next);
      if (act && act !== this.current) this.enter(act);
    });
  }

  /** 开场 */
  start(): void {
    this.enter('ACT1_DEPLOY', { delay: 400 });
  }

  /** 手动进入下一幕（用于 Act1 预备阶段完成后） */
  enter(id: ActId, opts: { delay?: number } = {}): void {
    if (this.fired.has(id)) return;
    this.fired.add(id);
    this.current = id;
    const act = ACTS[id];
    const run = (): void => {
      uiStore.setMission({ act, visible: true });
      synthAudio.play('mission_title');
      synthAudio.speak(`${act.title}。${act.briefing}`, { priority: true });
      EventBus.emit('mission:change', { act });
    };
    if (opts.delay) setTimeout(run, opts.delay);
    else run();
  }

  completeCurrent(): void {
    synthAudio.play('objective_complete');
    uiStore.patchMission({ completedFlash: Date.now() });
    EventBus.emit('mission:complete', { act: this.current });
  }

  /**
   * 在当前幕过程中插入次要解说（不切幕、不放标题音）。
   * 用于阶段进度里程碑、SOP 关键步骤、警告等高密度叙事。
   *
   * @param key   去重键（同一 key 只触发一次）
   * @param text  解说原文（同时朗读 + 写入事件日志）
   * @param opts  voice 是否朗读（默认 true）；priority 朗读队列优先级（默认 false）
   */
  nudge(
    key: string,
    text: string,
    opts: { voice?: boolean; priority?: boolean; logLevel?: 'info' | 'warn' | 'success' | 'danger' } = {},
  ): void {
    if (this.nudged.has(key)) return;
    // 简报/任何模态面板打开时延迟 3 秒重试，避免与 briefing 语音冲突
    const snap = uiStore.snapshot;
    if (snap.briefing.open || uiStore.isModalOpen()) {
      setTimeout(() => this.nudge(key, text, opts), 3000);
      return;
    }
    this.nudged.add(key);
    const voice = opts.voice !== false;
    const level = opts.logLevel ?? 'info';
    uiStore.pushLog(level, text);
    if (voice) synthAudio.speak(text, { priority: opts.priority === true });
  }

  /** 重置去重状态（用于关卡重启） */
  resetNudges(): void {
    this.nudged.clear();
  }

  get currentAct(): ActId {
    return this.current;
  }

  private mapStateToAct(state: MigrationState): ActId | null {
    switch (state) {
      case 'ENV_SCAN':
        return 'ACT3_SCAN';
      case 'COMPATIBILITY_CHECK':
        return 'ACT3_SCAN';
      case 'NETWORK_MAPPING':
        return 'ACT4_NETWORK';
      case 'STORAGE_MAPPING':
        return 'ACT5_STORAGE';
      case 'PRE_SNAPSHOT':
      case 'FULL_SYNC':
        return 'ACT6_FULL_SYNC';
      case 'INCREMENTAL_SYNC':
        return 'ACT7_INCREMENTAL';
      case 'DRIVER_INJECTION':
      case 'CUTOVER_READY':
      case 'CUTOVER_EXECUTING':
      case 'POST_CHECK':
        return 'ACT8_CUTOVER';
      case 'COMPLETED':
        return 'ACT9_DONE';
      default:
        return null;
    }
  }
}
