/**
 * 合成式音效 + 中文语音广播。
 * 纯 Web Audio API + SpeechSynthesis，零资源依赖。
 */

type SfxName =
  | 'gunshot_pistol'
  | 'gunshot_rifle'
  | 'gunshot_scanner'
  | 'impact_screen'
  | 'impact_metal'
  | 'empty_click'
  | 'reload_start'
  | 'reload_end'
  | 'footstep'
  | 'jump'
  | 'land'
  | 'ui_click'
  | 'mission_title'
  | 'objective_complete'
  | 'bug_hit'
  | 'bug_kill'
  | 'bug_spawn'
  | 'grenade_throw'
  | 'grenade_bounce'
  | 'grenade_explode'
  | 'vm_marked'
  | 'danger_alert'
  | 'sangfor_scream';

export class SynthAudio {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private ambient: OscillatorNode | null = null;
  private speaking = false;
  private speechQueue: string[] = [];
  private lastFootstepAt = 0;
  private enabled = true;

  ensure(): void {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') void this.ctx.resume();
      return;
    }
    const Ctor =
      (window as unknown as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext })
        .AudioContext ??
      (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return;
    this.ctx = new Ctor();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.5;
    this.master.connect(this.ctx.destination);
    this.startAmbient();
  }

  private startAmbient(): void {
    if (!this.ctx || !this.master) return;
    // 机房低频嗡鸣：两个 osc + 低通
    const lp = this.ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 220;
    const gain = this.ctx.createGain();
    gain.gain.value = 0.05;
    lp.connect(gain);
    gain.connect(this.master);

    const o1 = this.ctx.createOscillator();
    o1.type = 'sawtooth';
    o1.frequency.value = 55;
    o1.connect(lp);
    o1.start();

    const o2 = this.ctx.createOscillator();
    o2.type = 'sine';
    o2.frequency.value = 82.4;
    const o2g = this.ctx.createGain();
    o2g.gain.value = 0.3;
    o2.connect(o2g);
    o2g.connect(lp);
    o2.start();

    this.ambient = o1;
  }

  setEnabled(on: boolean): void {
    this.enabled = on;
    if (this.master) this.master.gain.value = on ? 0.5 : 0;
  }
  isEnabled(): boolean {
    return this.enabled;
  }

  /** 暴露 AudioContext / master gain 给后插的混响/EQ 等节点。可能为 null（未初始化）。 */
  getContext(): AudioContext | null {
    return this.ctx;
  }
  getMasterNode(): GainNode | null {
    return this.master;
  }

  /** 主入口：播放一个命名音效 */
  play(name: SfxName): void {
    this.ensure();
    if (!this.ctx || !this.master || !this.enabled) return;
    switch (name) {
      case 'gunshot_pistol':
        this.gunshot('pistol');
        break;
      case 'gunshot_rifle':
        this.gunshot('rifle');
        break;
      case 'gunshot_scanner':
        this.tone(1200, 0.18, 0.35, 'sawtooth', 1800);
        break;
      case 'impact_screen':
        // 玻璃/屏幕碎裂：高频短脉冲 + 回音
        this.noiseBurst(0.05, 0.45, 3200, 'highpass');
        this.tone(1800, 0.06, 0.25, 'triangle', 900);
        break;
      case 'impact_metal':
        // 金属后跑：短途 clank + 低频波
        this.noiseBurst(0.04, 0.35, 2400, 'bandpass');
        this.tone(420, 0.08, 0.2, 'triangle', 180);
        break;
      case 'empty_click':
        this.tone(900, 0.04, 0.22, 'square');
        break;
      case 'reload_start':
        this.tone(520, 0.07, 0.22, 'square');
        setTimeout(() => this.tone(320, 0.09, 0.22, 'square'), 100);
        break;
      case 'reload_end':
        this.tone(680, 0.06, 0.28, 'square');
        setTimeout(() => this.tone(880, 0.07, 0.28, 'square'), 70);
        break;
      case 'footstep': {
        const now = performance.now();
        if (now - this.lastFootstepAt < 260) return;
        this.lastFootstepAt = now;
        this.noiseBurst(0.05, 0.25, 400, 'lowpass');
        break;
      }
      case 'jump':
        this.noiseBurst(0.04, 0.3, 700, 'lowpass');
        break;
      case 'land':
        this.noiseBurst(0.08, 0.45, 300, 'lowpass');
        this.tone(60, 0.08, 0.25, 'sine');
        break;
      case 'ui_click':
        this.tone(1100, 0.04, 0.22, 'triangle');
        break;
      case 'mission_title':
        this.tone(330, 0.18, 0.35, 'sawtooth');
        setTimeout(() => this.tone(440, 0.18, 0.35, 'sawtooth'), 140);
        setTimeout(() => this.tone(660, 0.3, 0.4, 'sawtooth'), 280);
        break;
      case 'objective_complete':
        this.tone(523, 0.12, 0.35, 'triangle');
        setTimeout(() => this.tone(659, 0.12, 0.35, 'triangle'), 100);
        setTimeout(() => this.tone(784, 0.2, 0.35, 'triangle'), 200);
        break;
      case 'bug_hit':
        this.tone(1500, 0.05, 0.25, 'square');
        break;
      case 'bug_kill':
        this.tone(900, 0.08, 0.3, 'sawtooth', 250);
        this.noiseBurst(0.18, 0.3, 800, 'bandpass');
        break;
      case 'bug_spawn':
        this.tone(220, 0.25, 0.22, 'sine', 520);
        break;
      case 'grenade_throw':
        this.tone(420, 0.06, 0.25, 'square');
        break;
      case 'grenade_bounce':
        this.tone(260, 0.04, 0.25, 'triangle');
        break;
      case 'grenade_explode':
        this.grenadeExplosion();
        break;
      case 'vm_marked':
        this.tone(880, 0.08, 0.35, 'sine');
        setTimeout(() => this.tone(1320, 0.12, 0.35, 'sine'), 60);
        break;
      case 'danger_alert':
        this.tone(740, 0.14, 0.4, 'square');
        setTimeout(() => this.tone(740, 0.14, 0.4, 'square'), 250);
        break;
      case 'sangfor_scream':
        // 深信服专属死亡惨叫：大幅颤抖的降调男声 + 嘶吼噪声
        this.scream();
        break;
    }
  }
  /** 手雷爆炸音效：超低频冲击波 + 中频爆炸主体 + 高频爆裂 + 室内回响尾音 */
  private grenadeExplosion(): void {
    if (!this.ctx || !this.master) return;
    const now = this.ctx.currentTime;

    // 1. 超低频冲击波（身体震动感）
    const sub = this.ctx.createOscillator();
    sub.type = 'sine';
    sub.frequency.setValueAtTime(48, now);
    sub.frequency.exponentialRampToValueAtTime(14, now + 0.28);
    const subGain = this.ctx.createGain();
    subGain.gain.setValueAtTime(3.8, now);
    subGain.gain.exponentialRampToValueAtTime(0.001, now + 0.32);
    sub.connect(subGain);
    subGain.connect(this.master);
    sub.start(now);
    sub.stop(now + 0.35);

    // 2. 中频爆炸主体（最响）
    const bodyDur = 0.9;
    const bodyBuf = this.ctx.createBuffer(1, Math.floor(this.ctx.sampleRate * bodyDur), this.ctx.sampleRate);
    const bd = bodyBuf.getChannelData(0);
    for (let i = 0; i < bd.length; i++) bd[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bd.length, 0.55);
    const bodySrc = this.ctx.createBufferSource();
    bodySrc.buffer = bodyBuf;
    const bodyBP = this.ctx.createBiquadFilter();
    bodyBP.type = 'bandpass';
    bodyBP.frequency.value = 260;
    bodyBP.Q.value = 0.45;
    const bodyGain = this.ctx.createGain();
    bodyGain.gain.setValueAtTime(3.2, now + 0.01);
    bodyGain.gain.exponentialRampToValueAtTime(0.001, now + bodyDur);
    bodySrc.connect(bodyBP);
    bodyBP.connect(bodyGain);
    bodyGain.connect(this.master);
    bodySrc.start(now);

    // 3. 高频爆裂勃射（碎片闪烁感）
    const crackBuf = this.ctx.createBuffer(1, Math.floor(this.ctx.sampleRate * 0.1), this.ctx.sampleRate);
    const cd = crackBuf.getChannelData(0);
    for (let i = 0; i < cd.length; i++) cd[i] = (Math.random() * 2 - 1) * (1 - i / cd.length);
    const crackSrc = this.ctx.createBufferSource();
    crackSrc.buffer = crackBuf;
    const crackHP = this.ctx.createBiquadFilter();
    crackHP.type = 'highpass';
    crackHP.frequency.value = 2800;
    const crackGain = this.ctx.createGain();
    crackGain.gain.setValueAtTime(2.0, now);
    crackGain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
    crackSrc.connect(crackHP);
    crackHP.connect(crackGain);
    crackGain.connect(this.master);
    crackSrc.start(now);

    // 4. 室内混响尾音（机房回响）
    const tailDur = 2.2;
    const tailBuf = this.ctx.createBuffer(1, Math.floor(this.ctx.sampleRate * tailDur), this.ctx.sampleRate);
    const td = tailBuf.getChannelData(0);
    for (let i = 0; i < td.length; i++) td[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / td.length, 1.4);
    const tailSrc = this.ctx.createBufferSource();
    tailSrc.buffer = tailBuf;
    const tailLP = this.ctx.createBiquadFilter();
    tailLP.type = 'lowpass';
    tailLP.frequency.value = 700;
    const tailGain = this.ctx.createGain();
    tailGain.gain.setValueAtTime(1.0, now + 0.06);
    tailGain.gain.exponentialRampToValueAtTime(0.001, now + tailDur);
    tailSrc.connect(tailLP);
    tailLP.connect(tailGain);
    tailGain.connect(this.master);
    tailSrc.start(now + 0.06);
  }
  /** 合成一声戏剧化男性惨叫（专用于深信服土匪死亡） */
  private scream(): void {
    if (!this.ctx || !this.master) return;
    const now = this.ctx.currentTime;
    const dur = 1.4;
    // 主声部：锯齿波，先高后低并带颤音
    const osc = this.ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(520, now);
    osc.frequency.exponentialRampToValueAtTime(680, now + 0.12);
    osc.frequency.exponentialRampToValueAtTime(460, now + 0.55);
    osc.frequency.exponentialRampToValueAtTime(120, now + dur);
    // 颤音 LFO
    const lfo = this.ctx.createOscillator();
    lfo.type = 'sine';
    lfo.frequency.value = 6.5;
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 35;
    lfo.connect(lfoGain);
    lfoGain.connect(osc.frequency);
    // 带通滤镜让它更像人声
    const bp = this.ctx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.value = 900;
    bp.Q.value = 1.1;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.001, now);
    g.gain.exponentialRampToValueAtTime(0.55, now + 0.08);
    g.gain.exponentialRampToValueAtTime(0.35, now + 0.9);
    g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
    osc.connect(bp);
    bp.connect(g);
    g.connect(this.master);
    osc.start(now);
    lfo.start(now);
    osc.stop(now + dur + 0.05);
    lfo.stop(now + dur + 0.05);
    // 嘶吼噪声层
    this.noiseBurst(dur * 0.7, 0.25, 1400, 'bandpass');
    // 余韵闷哼
    setTimeout(() => this.tone(110, 0.35, 0.25, 'sine', 60), 1200);
  }

  /** 更真实的枪声：transient crack + body thud + tail reverb */
  private gunshot(kind: 'pistol' | 'rifle'): void {
    if (!this.ctx || !this.master) return;
    const now = this.ctx.currentTime;
    const isRifle = kind === 'rifle';

    // ---- Layer 1: 高频 crack（击锤打火 + 音爆）---- 大幅提升初始瞬态
    const crackDur = 0.018;
    const crackBuf = this.ctx.createBuffer(
      1,
      Math.max(1, Math.floor(this.ctx.sampleRate * crackDur)),
      this.ctx.sampleRate,
    );
    const cd = crackBuf.getChannelData(0);
    for (let i = 0; i < cd.length; i++) cd[i] = (Math.random() * 2 - 1) * (1 - i / cd.length);
    const crackSrc = this.ctx.createBufferSource();
    crackSrc.buffer = crackBuf;
    const crackHP = this.ctx.createBiquadFilter();
    crackHP.type = 'highpass';
    crackHP.frequency.value = 1800;
    const crackGain = this.ctx.createGain();
    crackGain.gain.setValueAtTime(isRifle ? 1.8 : 1.5, now);
    crackGain.gain.exponentialRampToValueAtTime(0.001, now + crackDur);
    crackSrc.connect(crackHP);
    crackHP.connect(crackGain);
    crackGain.connect(this.master);
    crackSrc.start(now);

    // ---- Layer 2: body（主声，带通噪声）提升 body 音量和持续时间 ----
    const bodyDur = isRifle ? 0.22 : 0.16;
    const bodyBuf = this.ctx.createBuffer(
      1,
      Math.max(1, Math.floor(this.ctx.sampleRate * bodyDur)),
      this.ctx.sampleRate,
    );
    const bd = bodyBuf.getChannelData(0);
    for (let i = 0; i < bd.length; i++) bd[i] = Math.random() * 2 - 1;
    const bodySrc = this.ctx.createBufferSource();
    bodySrc.buffer = bodyBuf;
    const bodyBP = this.ctx.createBiquadFilter();
    bodyBP.type = 'bandpass';
    bodyBP.frequency.value = isRifle ? 700 : 1000;
    bodyBP.Q.value = 0.7;
    const bodyGain = this.ctx.createGain();
    bodyGain.gain.setValueAtTime(isRifle ? 1.6 : 1.3, now + 0.003);
    bodyGain.gain.exponentialRampToValueAtTime(0.01, now + bodyDur);
    bodySrc.connect(bodyBP);
    bodyBP.connect(bodyGain);
    bodyGain.connect(this.master);
    bodySrc.start(now + 0.002);

    // ---- Layer 3: sub-bass boom（炮口低频冲击，让人感受到物理震动）----
    const boom = this.ctx.createOscillator();
    boom.type = 'sine';
    boom.frequency.setValueAtTime(isRifle ? 55 : 70, now);
    boom.frequency.exponentialRampToValueAtTime(20, now + 0.18);
    const boomGain = this.ctx.createGain();
    boomGain.gain.setValueAtTime(isRifle ? 1.8 : 1.4, now);
    boomGain.gain.exponentialRampToValueAtTime(0.001, now + 0.20);
    boom.connect(boomGain);
    boomGain.connect(this.master);
    boom.start(now);
    boom.stop(now + 0.22);

    // ---- Layer 4: low thump（胸口撞击感，中频冲击）----
    const thump = this.ctx.createOscillator();
    thump.type = 'sine';
    thump.frequency.setValueAtTime(isRifle ? 120 : 140, now + 0.008);
    thump.frequency.exponentialRampToValueAtTime(50, now + 0.14);
    const thumpGain = this.ctx.createGain();
    thumpGain.gain.setValueAtTime(isRifle ? 1.4 : 1.1, now + 0.008);
    thumpGain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
    thump.connect(thumpGain);
    thumpGain.connect(this.master);
    thump.start(now + 0.008);
    thump.stop(now + 0.20);

    // ---- Layer 5: 回响尾（机房反射）延长尾音模拟室内混响 ----
    const tailDur = isRifle ? 0.9 : 0.65;
    const tailBuf = this.ctx.createBuffer(
      1,
      Math.max(1, Math.floor(this.ctx.sampleRate * tailDur)),
      this.ctx.sampleRate,
    );
    const td = tailBuf.getChannelData(0);
    for (let i = 0; i < td.length; i++) {
      td[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / td.length, 1.8);
    }
    const tailSrc = this.ctx.createBufferSource();
    tailSrc.buffer = tailBuf;
    const tailBP = this.ctx.createBiquadFilter();
    tailBP.type = 'bandpass';
    tailBP.frequency.value = 600;
    tailBP.Q.value = 2.0;
    const tailGain = this.ctx.createGain();
    tailGain.gain.setValueAtTime(0.55, now + 0.04);
    tailGain.gain.exponentialRampToValueAtTime(0.001, now + tailDur);
    tailSrc.connect(tailBP);
    tailBP.connect(tailGain);
    tailGain.connect(this.master);
    tailSrc.start(now + 0.04);
  }

  /** 中文广播（TTS） */
  speak(text: string, opts: { priority?: boolean } = {}): void {
    if (!this.enabled) return;
    if (typeof speechSynthesis === 'undefined') return;
    if (opts.priority) {
      speechSynthesis.cancel();
      this.speechQueue = [];
      this.speaking = false;
    }
    // 队列上限：避免高密度解说堆积。优先级文案已在上面清空队列，普通追加最多保留 4 条。
    const MAX_QUEUE = 4;
    if (this.speechQueue.length >= MAX_QUEUE) {
      this.speechQueue.splice(0, this.speechQueue.length - MAX_QUEUE + 1);
    }
    this.speechQueue.push(text);
    this.pump();
  }
  private pump(): void {
    if (this.speaking) return;
    const next = this.speechQueue.shift();
    if (!next) return;
    this.speaking = true;
    const u = new SpeechSynthesisUtterance(next);
    u.lang = 'zh-CN';
    u.rate = 1.05;
    u.pitch = 1.0;
    u.volume = 0.95;
    u.onend = () => {
      this.speaking = false;
      this.pump();
    };
    u.onerror = () => {
      this.speaking = false;
      this.pump();
    };
    speechSynthesis.speak(u);
  }

  // --- 合成辅助 ---
  private tone(
    freq: number,
    dur: number,
    gain: number,
    type: OscillatorType = 'sine',
    sweepTo?: number,
  ): void {
    if (!this.ctx || !this.master) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, now);
    if (sweepTo !== undefined) osc.frequency.exponentialRampToValueAtTime(Math.max(10, sweepTo), now + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, now);
    g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
    osc.connect(g);
    g.connect(this.master);
    osc.start(now);
    osc.stop(now + dur + 0.05);
  }

  private noiseBurst(
    dur: number,
    gain: number,
    filterFreq: number,
    type: BiquadFilterType,
  ): void {
    if (!this.ctx || !this.master) return;
    const now = this.ctx.currentTime;
    const bufSize = Math.floor(this.ctx.sampleRate * dur);
    const buf = this.ctx.createBuffer(1, bufSize, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < bufSize; i++) data[i] = Math.random() * 2 - 1;
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = filterFreq;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, now);
    g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.master);
    src.start(now);
    src.stop(now + dur + 0.02);
  }
}

export const synthAudio = new SynthAudio();
