/**
 * 部署台 & VM 全息影像 —— Act 1 / Act 3 使用的互动物件。
 *
 * - DeployPad: 绿色发光平台，玩家站在上面按住 F 3 秒即"部署 SMTX 工具"。
 * - VMHologram: 漂浮的绿色/紫色 VM 全息影像，被扫描枪命中后标记。
 */
import * as THREE from 'three';

export class DeployPad {
  readonly group: THREE.Group;
  readonly box: THREE.Box3;
  private ring: THREE.Mesh;
  private progress = 0;
  private complete = false;
  private time = 0;

  constructor(scene: THREE.Scene, x: number, z: number) {
    this.group = new THREE.Group();
    this.group.position.set(x, 0, z);

    // 地台圆盘
    const pad = new THREE.Mesh(
      new THREE.CylinderGeometry(1.2, 1.2, 0.08, 32),
      new THREE.MeshStandardMaterial({
        color: 0x0a1a12,
        emissive: 0x00e676,
        emissiveIntensity: 0.5,
        metalness: 0.5,
        roughness: 0.3,
      }),
    );
    pad.position.y = 0.04;
    this.group.add(pad);

    // 进度环
    this.ring = new THREE.Mesh(
      new THREE.RingGeometry(1.0, 1.15, 48, 1, 0, Math.PI * 2),
      new THREE.MeshBasicMaterial({
        color: 0x00e676,
        side: THREE.DoubleSide,
        transparent: true,
        opacity: 0.8,
      }),
    );
    this.ring.rotation.x = -Math.PI / 2;
    this.ring.position.y = 0.09;
    this.group.add(this.ring);

    // 中央浮动立方（表示迁移工具 VM 包）
    const crate = new THREE.Mesh(
      new THREE.BoxGeometry(0.5, 0.5, 0.5),
      new THREE.MeshStandardMaterial({
        color: 0x00b4ff,
        emissive: 0x0066cc,
        emissiveIntensity: 1.0,
        transparent: true,
        opacity: 0.85,
      }),
    );
    crate.position.y = 1.0;
    crate.userData['__deployCrate'] = true;
    this.group.add(crate);

    // 移除 PointLight，crate 本身的 emissive 已够视觉效果

    scene.add(this.group);

    this.box = new THREE.Box3().setFromCenterAndSize(
      new THREE.Vector3(x, 0, z),
      new THREE.Vector3(2.4, 2, 2.4),
    );
  }

  /** 玩家是否在台面上 */
  contains(p: THREE.Vector3): boolean {
    return (
      p.x >= this.box.min.x &&
      p.x <= this.box.max.x &&
      p.z >= this.box.min.z &&
      p.z <= this.box.max.z
    );
  }

  /** 推进部署：返回是否刚刚完成 */
  advance(dt: number, holding: boolean): { justCompleted: boolean; percent: number } {
    this.time += dt;
    if (this.complete) return { justCompleted: false, percent: 1 };
    if (holding) this.progress = Math.min(1, this.progress + dt / 3.0);
    else this.progress = Math.max(0, this.progress - dt / 1.5);

    // 进度环仅显示已完成角度
    const geom = new THREE.RingGeometry(1.0, 1.15, 48, 1, -Math.PI / 2, -this.progress * Math.PI * 2);
    this.ring.geometry.dispose();
    this.ring.geometry = geom;
    (this.ring.material as THREE.MeshBasicMaterial).color.setHex(
      holding ? 0x00ff99 : 0xffaa33,
    );

    // 工具包漂浮
    const crate = this.group.children[2] as THREE.Mesh;
    crate.position.y = 1.0 + Math.sin(this.time * 2) * 0.1;
    crate.rotation.y += dt * 1.5;

    if (this.progress >= 1 && !this.complete) {
      this.complete = true;
      (this.ring.material as THREE.MeshBasicMaterial).color.setHex(0x00ff99);
      return { justCompleted: true, percent: 1 };
    }
    return { justCompleted: false, percent: this.progress };
  }
}

export interface VMHologramOpts {
  position: [number, number, number];
  label: string;
}

export class VMHologram {
  readonly group: THREE.Group;
  readonly core: THREE.Mesh;
  marked = false;
  private time = 0;

  constructor(scene: THREE.Scene, opts: VMHologramOpts) {
    this.group = new THREE.Group();
    this.group.position.set(...opts.position);

    // 全息立方体（绿色半透明）
    this.core = new THREE.Mesh(
      new THREE.BoxGeometry(0.6, 0.9, 0.6),
      new THREE.MeshStandardMaterial({
        color: 0x00e676,
        emissive: 0x00e676,
        emissiveIntensity: 1.2,
        transparent: true,
        opacity: 0.45,
      }),
    );
    this.core.userData['__vmHologram'] = this;
    this.group.add(this.core);

    // 线框外壳
    const wire = new THREE.LineSegments(
      new THREE.EdgesGeometry(this.core.geometry),
      new THREE.LineBasicMaterial({ color: 0xaaffcc, transparent: true, opacity: 0.9 }),
    );
    this.group.add(wire);

    const base = new THREE.Mesh(
      new THREE.CylinderGeometry(0.5, 0.5, 0.04, 16),
      new THREE.MeshBasicMaterial({ color: 0x00e676, transparent: true, opacity: 0.6 }),
    );
    base.position.y = -0.6;
    this.group.add(base);

    scene.add(this.group);
  }

  mark(): void {
    if (this.marked) return;
    this.marked = true;
    const mat = this.core.material as THREE.MeshStandardMaterial;
    mat.color.setHex(0x00b4ff);
    mat.emissive.setHex(0x00b4ff);
    mat.opacity = 0.8;
  }

  update(dt: number): void {
    this.time += dt;
    this.group.position.y = this.group.userData['baseY'] ?? (this.group.position.y);
    this.group.rotation.y += dt * 0.6;
    this.core.position.y = Math.sin(this.time * 1.4) * 0.1;
  }
}
