/**
 * 补给拾取系统 —— 在场景中放置 4 类补给盒，玩家走近自动拾取。
 *  - HEALTH  绿色十字  +30 HP
 *  - ARMOR   蓝色盾    +50 ARMOR
 *  - AMMO    黄色弹匣  +60 备弹
 *  - GRENADE 橄榄绿    +1 手雷
 *
 * 视觉：发光底环 + 浮动旋转的几何体 + 顶部光柱。
 * 触发：玩家进入半径 1.4m 时拾取，触发回调（由调用方接 PlayerHealth/ShootingSystem/GrenadeSystem）。
 */
import * as THREE from 'three';
import { synthAudio } from '../audio/SynthAudio';
import { EventBus } from '../core/EventBus';

export type PickupKind = 'HEALTH' | 'ARMOR' | 'AMMO' | 'GRENADE';

export interface PickupHandlers {
  onHealth: (amount: number) => void;
  onArmor: (amount: number) => void;
  onAmmo: (amount: number) => void;
  onGrenade: (count: number) => void;
}

interface Pickup {
  kind: PickupKind;
  group: THREE.Group;
  iconMat: THREE.MeshStandardMaterial;
  ringMat: THREE.MeshBasicMaterial;
  beamMat: THREE.MeshBasicMaterial;
  amount: number;
  born: number;
  basePos: THREE.Vector3;
}

const COLORS: Record<PickupKind, { primary: number; emissive: number; label: string }> = {
  HEALTH: { primary: 0x33ff7a, emissive: 0x33ff7a, label: '医疗包' },
  ARMOR: { primary: 0x6cb8ff, emissive: 0x6cb8ff, label: '护甲板' },
  AMMO: { primary: 0xffd84a, emissive: 0xffd84a, label: '弹药盒' },
  GRENADE: { primary: 0x7fa84a, emissive: 0x9bd060, label: '手雷补给' },
};

const DEFAULT_AMOUNTS: Record<PickupKind, number> = {
  HEALTH: 30,
  ARMOR: 50,
  AMMO: 60,
  GRENADE: 1,
};

export class PickupSystem {
  private readonly scene: THREE.Scene;
  private readonly handlers: PickupHandlers;
  private readonly getPlayerPos: () => THREE.Vector3;
  private items: Pickup[] = [];
  private readonly RADIUS = 1.4;

  constructor(
    scene: THREE.Scene,
    getPlayerPos: () => THREE.Vector3,
    handlers: PickupHandlers,
  ) {
    this.scene = scene;
    this.getPlayerPos = getPlayerPos;
    this.handlers = handlers;
  }

  /** 在指定位置投放一个补给盒。amount 不传则用默认值 */
  spawn(kind: PickupKind, position: [number, number, number], amount?: number): void {
    const c = COLORS[kind];
    const group = new THREE.Group();
    group.position.set(position[0], position[1], position[2]);

    // 1. 底盘（金属垫片）
    const baseMat = new THREE.MeshStandardMaterial({
      color: 0x222a36,
      metalness: 0.6,
      roughness: 0.4,
    });
    const base = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.34, 0.08, 16), baseMat);
    base.position.y = 0.04;
    group.add(base);

    // 2. 发光环
    const ringMat = new THREE.MeshBasicMaterial({
      color: c.primary,
      transparent: true,
      opacity: 0.85,
      side: THREE.DoubleSide,
    });
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.36, 0.025, 6, 28), ringMat);
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.02;
    group.add(ring);

    // 3. 主图标
    const iconMat = new THREE.MeshStandardMaterial({
      color: c.primary,
      emissive: c.emissive,
      emissiveIntensity: 1.2,
      metalness: 0.4,
      roughness: 0.35,
    });
    const icon = this.buildIcon(kind, iconMat);
    icon.position.y = 0.42;
    group.add(icon);

    // 4. 顶部光柱（指引）
    const beamMat = new THREE.MeshBasicMaterial({
      color: c.primary,
      transparent: true,
      opacity: 0.22,
      depthWrite: false,
    });
    const beam = new THREE.Mesh(
      new THREE.CylinderGeometry(0.08, 0.16, 2.4, 8, 1, true),
      beamMat,
    );
    beam.position.y = 1.4;
    group.add(beam);

    // 5. 点光源（淡淡的染色感）
    const light = new THREE.PointLight(c.primary, 1.1, 3.2);
    light.position.y = 0.6;
    group.add(light);

    this.scene.add(group);
    this.items.push({
      kind,
      group,
      iconMat,
      ringMat,
      beamMat,
      amount: amount ?? DEFAULT_AMOUNTS[kind],
      born: performance.now(),
      basePos: group.position.clone(),
    });
  }

  /** 构建图标几何 */
  private buildIcon(kind: PickupKind, mat: THREE.MeshStandardMaterial): THREE.Object3D {
    if (kind === 'HEALTH') {
      const g = new THREE.Group();
      const a = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.1, 0.1), mat);
      const b = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.32, 0.1), mat);
      g.add(a, b);
      return g;
    }
    if (kind === 'ARMOR') {
      // 盾牌：扁的圆角盒
      const m = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.34, 0.08), mat);
      return m;
    }
    if (kind === 'AMMO') {
      // 弹匣：扁长方体
      const g = new THREE.Group();
      const body = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.32, 0.12), mat);
      g.add(body);
      // 三发子弹（顶部）
      const bulletMat = new THREE.MeshStandardMaterial({
        color: 0xffe066,
        metalness: 0.7,
        roughness: 0.3,
      });
      for (let i = -1; i <= 1; i++) {
        const b = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, 0.06, 8), bulletMat);
        b.position.set(i * 0.05, 0.2, 0);
        g.add(b);
      }
      return g;
    }
    // GRENADE：迷你手雷
    const g = new THREE.Group();
    const body = new THREE.Mesh(new THREE.SphereGeometry(0.13, 9, 7), mat);
    body.scale.y = 0.88;
    g.add(body);
    const handleMat = new THREE.MeshStandardMaterial({
      color: 0x1c1f14,
      metalness: 0.8,
      roughness: 0.35,
    });
    const handle = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.16, 0.016), handleMat);
    handle.position.set(0.05, 0.05, 0);
    g.add(handle);
    return g;
  }

  /** 主循环：浮动 + 旋转 + 玩家拾取检测 */
  update(dt: number): void {
    const playerPos = this.getPlayerPos();
    const now = performance.now();
    for (let i = this.items.length - 1; i >= 0; i--) {
      const it = this.items[i];
      const t = (now - it.born) * 0.001;
      // 浮动
      it.group.position.y = it.basePos.y + Math.sin(t * 2.4) * 0.06;
      // 旋转图标（icon 是第 3 个 child：base, ring, icon）
      const icon = it.group.children[2];
      icon.rotation.y += dt * 1.6;
      // 环呼吸
      it.ringMat.opacity = 0.55 + 0.35 * (Math.sin(t * 3.0) + 1) * 0.5;
      // 光柱透明度
      it.beamMat.opacity = 0.16 + 0.12 * (Math.sin(t * 2.2) + 1) * 0.5;

      // 拾取检测（只看水平距离，避免 y 抖动误差）
      const dx = playerPos.x - it.basePos.x;
      const dz = playerPos.z - it.basePos.z;
      const dy = playerPos.y - it.basePos.y;
      const dist = Math.sqrt(dx * dx + dz * dz);
      if (dist < this.RADIUS && Math.abs(dy) < 2.2) {
        this.collect(i);
      }
    }
  }

  private collect(idx: number): void {
    const it = this.items[idx];
    switch (it.kind) {
      case 'HEALTH':
        this.handlers.onHealth(it.amount);
        EventBus.emit('pickup:health', { amount: it.amount });
        break;
      case 'ARMOR':
        this.handlers.onArmor(it.amount);
        EventBus.emit('pickup:armor', { amount: it.amount });
        break;
      case 'AMMO':
        this.handlers.onAmmo(it.amount);
        EventBus.emit('pickup:ammo', { amount: it.amount });
        break;
      case 'GRENADE':
        this.handlers.onGrenade(it.amount);
        EventBus.emit('pickup:grenade', { amount: it.amount });
        break;
    }
    synthAudio.play('objective_complete');
    this.dispose(it);
    this.items.splice(idx, 1);
  }

  private dispose(it: Pickup): void {
    this.scene.remove(it.group);
    it.group.traverse((child) => {
      const m = child as THREE.Mesh;
      if (m.isMesh) {
        m.geometry?.dispose?.();
        const mat = m.material as THREE.Material | THREE.Material[];
        if (Array.isArray(mat)) mat.forEach((x) => x.dispose());
        else mat?.dispose?.();
      }
    });
  }

  clearAll(): void {
    for (const it of this.items) this.dispose(it);
    this.items = [];
  }

  /** 检查指定位置附近是否已有同类（或任意）拾取物，用于补给重生去重 */
  hasNear(position: [number, number, number], radius = 1.6, kind?: PickupKind): boolean {
    for (const it of this.items) {
      if (kind && it.kind !== kind) continue;
      const dx = it.basePos.x - position[0];
      const dz = it.basePos.z - position[2];
      if (dx * dx + dz * dz <= radius * radius) return true;
    }
    return false;
  }

  get count(): number {
    return this.items.length;
  }
}
