/** 全局 bark 节流：避免多敌人同时喊话覆盖 */
let _lastBarkAt = 0;
function _pickLine(vendorKey: string, type: BarkType): string {
  const pool = VENDOR_LINES[vendorKey]?.[type];
  if (!pool || pool.length === 0) return '';
  return pool[(Math.random() * pool.length) | 0];
}

/** spotted 时头顶临时弹一个 "!" sprite，0.8s 自销毁 */
function makeAlertMark(): THREE.Sprite {
  const canvas = document.createElement('canvas');
  canvas.width = 128; canvas.height = 128;
  const ctx = canvas.getContext('2d')!;
  ctx.fillStyle = '#ff2a2a';
  ctx.beginPath();
  ctx.arc(64, 64, 58, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 96px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('!', 64, 70);
  const tex = new THREE.CanvasTexture(canvas);
  return new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
}

function makeVendorBadge(vendor: Vendor): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 128;
  const ctx = canvas.getContext('2d')!;
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, 256, 128);
  ctx.fillStyle = vendor.color;
  ctx.fillRect(0, 0, 256, 22);
  ctx.fillRect(0, 106, 256, 22);
  ctx.fillStyle = '#111';
  ctx.font = 'bold 48px "Helvetica Neue", Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(vendor.label, 128, 64);
  ctx.fillStyle = vendor.color;
  ctx.font = 'bold 13px monospace';
  ctx.fillText('COMPETITOR · HOSTILE', 128, 14);
  ctx.fillText('DO NOT MIGRATE HERE', 128, 117);
  const tex = new THREE.CanvasTexture(canvas);
  tex.anisotropy = 4;
  return tex;
}

function makeOverheadTag(vendor: Vendor): THREE.Sprite {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 140;
  const ctx = canvas.getContext('2d')!;
  ctx.fillStyle = 'rgba(0,0,0,0.35)';
  ctx.fillRect(0, 0, 512, 140);
  ctx.fillStyle = vendor.accent;
  ctx.fillRect(0, 0, 512, 6);
  ctx.fillRect(0, 134, 512, 6);
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 88px "Helvetica Neue", Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(vendor.label, 256, 78);
  const tex = new THREE.CanvasTexture(canvas);
  tex.anisotropy = 4;
  return new THREE.Sprite(
    new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: true }),
  );
}

