export class BugEnemies {
  private readonly scene: THREE.Scene;
  private bugs: BugEnemy[] = [];
  private respawnPool: BugSpawnSpec[];
  private difficulty: BanditDifficulty = 'normal';

  // SWAT glb 缓存：加载一次，后续 clone
  private static soldierGltf: { scene: THREE.Group; animations: THREE.AnimationClip[] } | null = null;
  private static soldierAimClip: THREE.AnimationClip | null = null;
  private static soldierShootClip: THREE.AnimationClip | null = null;
  private static soldierLoading = false;

  private static findClipByPattern(clips: THREE.AnimationClip[], pattern: RegExp): THREE.AnimationClip | null {
    for (const clip of clips) {
      if (pattern.test(clip.name)) return clip;
    }
    return null;
  }

  private static async tryLoadOverlayClip(
    loader: GLTFLoader,
    url: string,
    pattern: RegExp,
  ): Promise<THREE.AnimationClip | null> {
    try {
      const gltf = await loader.loadAsync(url);
      return BugEnemies.findClipByPattern(gltf.animations, pattern);
    } catch {
      return null;
    }
  }

  /** 预加载 SWAT 模型（在 BugEnemies 构造后调用一次） */
  static async preloadSoldier(): Promise<void> {
    if (BugEnemies.soldierGltf || BugEnemies.soldierLoading) return;
    BugEnemies.soldierLoading = true;
    try {
      const loader = new GLTFLoader();
      const gltf = await loader.loadAsync(SWAT_MODEL_PATH);
      if (gltf.animations.length === 0) {
        throw new Error('swat.glb does not contain animations');
      }
      BugEnemies.soldierGltf = { scene: gltf.scene as THREE.Group, animations: gltf.animations };

      // swat.glb 自带完整持枪动作：优先精确命中举枪/射击片段，避免落到“手臂下垂”的 idle。
      BugEnemies.soldierAimClip = THREE.AnimationClip.findByName(gltf.animations, 'CharacterArmature|Idle_Gun_Pointing')
        ?? THREE.AnimationClip.findByName(gltf.animations, 'CharacterArmature|Idle_Gun')
        ?? BugEnemies.findClipByPattern(gltf.animations, /(Idle_Gun_Pointing|Idle_Gun|aim|rifle[_ -]?aim|idle_aim)/i);
      BugEnemies.soldierShootClip = THREE.AnimationClip.findByName(gltf.animations, 'CharacterArmature|Gun_Shoot')
        ?? THREE.AnimationClip.findByName(gltf.animations, 'CharacterArmature|Idle_Gun_Shoot')
        ?? THREE.AnimationClip.findByName(gltf.animations, 'CharacterArmature|Run_Shoot')
        ?? BugEnemies.findClipByPattern(gltf.animations, /(Gun_Shoot|Idle_Gun_Shoot|Run_Shoot|shoot|fire|rifle[_ -]?shoot|rifle[_ -]?fire)/i);
      if (!BugEnemies.soldierAimClip) {
        BugEnemies.soldierAimClip = await BugEnemies.tryLoadOverlayClip(
          loader,
          '/assets/characters/animations/soldier_aim.glb',
          /(aim|rifle.?aim|idle_aim)/i,
        );
      }
      if (!BugEnemies.soldierShootClip) {
        BugEnemies.soldierShootClip = await BugEnemies.tryLoadOverlayClip(
          loader,
          '/assets/characters/animations/soldier_shoot.glb',
          /(shoot|fire|rifle.?shoot|rifle.?fire)/i,
        );
      }

      console.log('[BugEnemies] swat.glb 加载成功，动画:', gltf.animations.map(a => a.name));
      console.log('[BugEnemies] overlay clips:', {
        aim: BugEnemies.soldierAimClip?.name ?? 'fallback_pose',
        shoot: BugEnemies.soldierShootClip?.name ?? 'recoil_only',
      });
    } catch (e) {
      console.warn('[BugEnemies] swat.glb 加载失败，使用程序化几何体', e);
    } finally {
      BugEnemies.soldierLoading = false;
    }
  }

  /** 把现有程序化 bug 替换为 SWAT 外观（保留 hp/state 等数据） */
  private swapToGLB(bug: BugEnemy): void {
    const gltf = BugEnemies.soldierGltf;
    if (!gltf) {
      console.warn('[BugEnemies] soldierGltf 未加载，跳过 SWAT 替换');
      return;
    }
    if (gltf.animations.length === 0) {
      console.warn('[BugEnemies] swat.glb 无动画，跳过 SWAT 替换');
      return;
    }

    // 克隆模型（必须用 SkeletonUtils.clone 才能正确复制骨骼绑定，否则 SkinnedMesh.matrixWorld 卡在单位矩阵）
    const model = skeletonClone(gltf.scene) as THREE.Group;
    model.scale.setScalar(1.0);
    model.position.set(0, 0, 0);
    model.traverse((c) => {
      if ((c as THREE.Mesh).isMesh) {
        const mesh = c as THREE.Mesh;
        mesh.castShadow = true;
        mesh.frustumCulled = false; // 防止骨骼动画时被错误剔除
        // SkeletonUtils.clone 会复用材质；死亡淡出会改 opacity，必须给每个敌人独立材质实例。
        if (Array.isArray(mesh.material)) {
          mesh.material = mesh.material.map((material) => material.clone());
        } else {
          mesh.material = mesh.material.clone();
        }
      }
    });

    // 保留 SWAT 原始材质，避免整身染色把场景对比度和可视性拉坏。

    // 动画
    const mixer = new THREE.AnimationMixer(model);
    const runClip = THREE.AnimationClip.findByName(gltf.animations, 'CharacterArmature|Run_Shoot')
      ?? BugEnemies.findClipByPattern(gltf.animations, /(Run_Shoot|Run|Walk)/i)
      ?? gltf.animations[0];
    const idleClip = THREE.AnimationClip.findByName(gltf.animations, 'CharacterArmature|Idle_Gun_Pointing')
      ?? THREE.AnimationClip.findByName(gltf.animations, 'CharacterArmature|Idle_Gun')
      ?? BugEnemies.findClipByPattern(gltf.animations, /(Idle_Gun_Pointing|Idle_Gun|Idle)/i)
      ?? gltf.animations[0];

    const runAction  = runClip  ? mixer.clipAction(runClip)  : null;
    const idleAction = idleClip ? mixer.clipAction(idleClip) : null;
    const aimAction = BugEnemies.soldierAimClip ? mixer.clipAction(BugEnemies.soldierAimClip) : null;
    const shootAction = BugEnemies.soldierShootClip ? mixer.clipAction(BugEnemies.soldierShootClip) : null;

    runAction?.setLoop(THREE.LoopRepeat, Infinity);
    idleAction?.setLoop(THREE.LoopRepeat, Infinity);
    if (aimAction) {
      aimAction.enabled = true;
      aimAction.setLoop(THREE.LoopRepeat, Infinity);
      aimAction.setEffectiveWeight(0.85);
      aimAction.play();
    }
    if (shootAction) {
      shootAction.enabled = true;
      shootAction.clampWhenFinished = false;
      shootAction.setLoop(THREE.LoopOnce, 1);
      shootAction.setEffectiveWeight(0);
      shootAction.play();
    }
    idleAction?.play();

    // 替换 group 内容
    const pos = bug.group.position.clone();
    const rot = bug.group.rotation.clone();
    this.scene.remove(bug.group);

    const newGroup = new THREE.Group();
    newGroup.position.copy(pos);
    newGroup.rotation.copy(rot);
    newGroup.add(model);

    // 重建 hitbox（不可见碰撞体，raycaster 仍用它）
    const torsoHit = new THREE.Mesh(
      new THREE.CapsuleGeometry(0.28, 0.75, 4, 8),
      new THREE.MeshStandardMaterial({ visible: false }),
    );
    torsoHit.position.y = 1.0;
    torsoHit.userData['bugEnemy'] = true;
    torsoHit.userData['bugRef'] = bug;
    newGroup.add(torsoHit);

    const headHit = new THREE.Mesh(
      new THREE.SphereGeometry(0.18, 8, 6),
      new THREE.MeshStandardMaterial({ visible: false }),
    );
    headHit.position.y = 1.65;
    headHit.userData['bugEnemy'] = true;
    headHit.userData['isHead'] = true;
    headHit.userData['bugRef'] = bug;
    newGroup.add(headHit);

    this.scene.add(newGroup);

    // 更新 bug 引用
    bug.group = newGroup;
    bug.core  = torsoHit;
    bug.head  = headHit;

    // 把 mixer 和 actions 挂到 userData 供 update() 使用
    newGroup.userData['mixer']      = mixer;
    newGroup.userData['runAction']  = runAction;
    newGroup.userData['idleAction'] = idleAction;
    newGroup.userData['aimAction'] = aimAction;
    newGroup.userData['shootAction'] = shootAction;
    newGroup.userData['shootBlendPulse'] = 0;

    // 记录骨骼引用供后续动画或调试使用。
    const boneMap: Record<string, THREE.Bone> = {};
    model.traverse((c) => {
      if ((c as THREE.Bone).isBone) boneMap[(c as THREE.Bone).name] = c as THREE.Bone;
    });
    const rightHand = boneMap['WristR']
      || boneMap['RightHand']
      || boneMap['mixamorigRightHand']
      || boneMap['RightWrist'];
    const chest = boneMap['Chest']
      || boneMap['Torso']
      || boneMap['Abdomen']
      || boneMap['Body']
      || boneMap['mixamorigSpine2']
      || boneMap['mixamorigSpine1']
      || boneMap['mixamorigSpine'];
    const rightArm = boneMap['UpperArmR'] || boneMap['RightArm'] || boneMap['mixamorigRightArm'];
    const rightForeArm = boneMap['LowerArmR'] || boneMap['RightForeArm'] || boneMap['mixamorigRightForeArm'];
    const leftArm = boneMap['UpperArmL'] || boneMap['LeftArm'] || boneMap['mixamorigLeftArm'];
    const leftForeArm = boneMap['LowerArmL'] || boneMap['LeftForeArm'] || boneMap['mixamorigLeftForeArm'];
    const gunMount = rightHand || chest;
    const gunGroup = new THREE.Group();
    const gunBody = new THREE.Mesh(
      new THREE.BoxGeometry(0.9, 0.14, 0.12),
      new THREE.MeshStandardMaterial({ color: 0x2c2f33, roughness: 0.38, metalness: 0.82, emissive: 0x16181c, emissiveIntensity: 0.35 }),
    );
    const gunBarrel = new THREE.Mesh(
      new THREE.BoxGeometry(0.45, 0.06, 0.06),
      new THREE.MeshStandardMaterial({ color: 0x151515, roughness: 0.28, metalness: 0.9 }),
    );
    gunBarrel.position.set(0.62, 0.01, 0);
    const gunMag = new THREE.Mesh(
      new THREE.BoxGeometry(0.12, 0.28, 0.09),
      new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.55, metalness: 0.4 }),
    );
    gunMag.position.set(-0.08, -0.19, 0.01);
    const gunGrip = new THREE.Mesh(
      new THREE.BoxGeometry(0.1, 0.24, 0.1),
      new THREE.MeshStandardMaterial({ color: 0x121212, roughness: 0.72 }),
    );
    gunGrip.position.set(-0.28, -0.18, 0);
    gunGroup.add(gunBody, gunBarrel, gunMag, gunGrip);
    const newMuzzle = new THREE.Object3D();
    newMuzzle.position.set(0.84, 0.01, 0);
    gunGroup.add(newMuzzle);
    if (gunMount) {
      gunMount.add(gunGroup);
      if (rightHand) {
        gunGroup.position.set(0.12, -0.02, 0.06);
        gunGroup.rotation.set(-0.08, -Math.PI / 2, 0.18, 'XYZ');
      } else {
        gunGroup.position.set(-0.06, -0.18, 0.22);
        gunGroup.rotation.set(0.1, -Math.PI / 2, 0.14, 'XYZ');
      }
    } else {
      console.warn('[BugEnemies] 未找到持枪骨骼，回退到根节点挂枪', Object.keys(boneMap));
      newGroup.add(gunGroup);
      gunGroup.position.set(0.24, 1.18, 0.24);
      gunGroup.rotation.set(0.06, -Math.PI / 2, 0.1, 'XYZ');
    }
    bug.muzzle = newMuzzle;
    newGroup.userData['gunGroup'] = gunGroup;
    newGroup.userData['gunMountBone'] = gunMount ?? null;
    newGroup.userData['gunBaseX'] = gunGroup.position.x;
    newGroup.userData['gunBaseY'] = gunGroup.position.y;
    newGroup.userData['gunBaseZ'] = gunGroup.position.z;
    newGroup.userData['rightArm']     = rightArm;
    newGroup.userData['rightForeArm'] = rightForeArm;
    newGroup.userData['leftArm']      = leftArm;
    newGroup.userData['leftForeArm']  = leftForeArm;

    // 头顶厂商名称标签
    const overhead = makeOverheadTag(bug.vendor);
    overhead.position.set(0, 2.3, 0);
    overhead.scale.set(2.4, 0.7, 1);
    newGroup.add(overhead);
  }

  /** 在 preloadSoldier 完成后调用，把所有现有 bug 升级为 GLB 外观 */
  upgradeToGLB(): void {
    for (const b of this.bugs) {
      if (b.alive) this.swapToGLB(b);
    }
  }

  setDifficulty(d: BanditDifficulty): void {
    this.difficulty = d;
    // 立即把当前活着的敌人也按新难度刷新数值（HP 不缩水以免立刻死掉，只调战斗参数）
    const profile = DIFFICULTY_PROFILES[d];
    for (const b of this.bugs) {
      if (!b.alive) continue;
      const baseSpeed = b.variant === 'dirty' ? 2.6 : 2.0;
      const baseFireInterval = b.variant === 'dirty' ? 1.5 : 1.9;
      const baseAccuracy = b.variant === 'dirty' ? 0.55 : 0.42;
      b.speed = baseSpeed * profile.speedMul;
      b.fireInterval = baseFireInterval * profile.fireIntervalMul;
      b.aimAccuracy = Math.min(0.95, baseAccuracy * profile.accuracyMul);
      (b as unknown as { damageMul: number }).damageMul = profile.damageMul;
      (b.head.material as THREE.MeshStandardMaterial).emissive = new THREE.Color(profile.badgeColor);
    }
  }
  getDifficulty(): BanditDifficulty {
    return this.difficulty;
  }
  private readonly spawnCooldown = 6.0;
  private respawnTimer = 0;
  private vendorRotation = 0;
  private readonly opts: BanditOpts;
  private readonly tmpV = new THREE.Vector3();
  private readonly tmpV2 = new THREE.Vector3();
  private readonly tmpGunPos = new THREE.Vector3();
  private readonly tmpGunQuat = new THREE.Quaternion();
  private readonly tmpGroupQuat = new THREE.Quaternion();
  private readonly tmpGunRight = new THREE.Vector3();
  private readonly tmpGunUp = new THREE.Vector3();
  private readonly tmpGunForward = new THREE.Vector3();
  private obstacleList: THREE.Object3D[] = [];
  private respawnEnabled = false;
  private _collisionCheck: ((pos: THREE.Vector3, radius: number) => boolean) | null = null;

  constructor(scene: THREE.Scene, spawns: BugSpawnSpec[], opts: BanditOpts) {
    this.scene = scene;
    this.opts = opts;
    this.respawnPool = [...spawns];
    for (const s of spawns) this.spawn(s, 'normal');
  }

  setObstacles(list: THREE.Object3D[]): void {
    this.obstacleList = list;
  }

  /** 注入碰撞检测回调（通常传入 CollisionSystem.collides.bind(collision)） */
  setCollisionCheck(fn: (pos: THREE.Vector3, radius: number) => boolean): void {
    this._collisionCheck = fn;
  }

  setRespawnEnabled(on: boolean): void {
    this.respawnEnabled = on;
  }

  spawnWave(specs: BugSpawnSpec[], variant: BugVariant = 'normal', overrideDifficulty?: BanditDifficulty): void {
    for (const s of specs) {
      this.spawn(s, variant, false, overrideDifficulty);
      synthAudio.play('bug_spawn');
    }
  }

  clearAll(): void {
    for (const b of this.bugs) {
      if (b.group.parent) this.scene.remove(b.group);
    }
    this.bugs = [];
  }

  private pickVendor(variant: BugVariant): Vendor {
    const pool = variant === 'dirty' ? DIRTY_VENDORS : NORMAL_VENDORS;
    const v = pool[this.vendorRotation % pool.length];
    this.vendorRotation++;
    return v;
  }

  private spawn(spec: BugSpawnSpec, variant: BugVariant = 'normal', _pool = true, overrideDifficulty?: BanditDifficulty): void {
    const vendor = this.pickVendor(variant);
    const group = new THREE.Group();
    group.position.set(spec.position[0], 0, spec.position[2]);

    // R8.3：制服染色 = 厂商色 × 0.6（暗化以维持军服质感），dirty 仍偏紫
    const baseUniform = variant === 'dirty' ? new THREE.Color(0x4b2d6b) : new THREE.Color(0x3a4a2a);
    const vendorTint = new THREE.Color(vendor.color).multiplyScalar(0.6);
    const uniformCol = baseUniform.clone().lerp(vendorTint, 0.7);
    const bodyMat = new THREE.MeshStandardMaterial({
      color: uniformCol,
      roughness: 0.85,
      metalness: 0.05,
    });
    const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.28, 0.75, 4, 8), bodyMat);
    torso.position.y = 1.0;
    torso.userData['bugEnemy'] = true;
    group.add(torso);

    const head = new THREE.Mesh(
      new THREE.SphereGeometry(0.18, 14, 10),
      new THREE.MeshStandardMaterial({ color: 0xe7c79a, roughness: 0.7 }),
    );
    head.position.y = 1.62;
    head.userData['bugEnemy'] = true;
    head.userData['isHead'] = true;
    group.add(head);

    const mask = new THREE.Mesh(
      new THREE.SphereGeometry(0.185, 14, 10, 0, Math.PI * 2, 0, Math.PI * 0.62),
      new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.9 }),
    );
    mask.position.y = 1.62;
    mask.rotation.x = Math.PI * 0.1;
    group.add(mask);

    const eyeMat = new THREE.MeshBasicMaterial({ color: 0xf4f4f4 });
    const eyeL = new THREE.Mesh(new THREE.SphereGeometry(0.024, 8, 6), eyeMat);
    const eyeR = eyeL.clone();
    eyeL.position.set(-0.06, 1.63, 0.16);
    eyeR.position.set(0.06, 1.63, 0.16);
    group.add(eyeL, eyeR);

    const armMat = bodyMat.clone();
    const armL = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.5, 0.12), armMat);
    const armR = armL.clone();
    armL.position.set(-0.38, 1.15, 0.0);
    armR.position.set(0.38, 1.15, 0.15);
    armR.rotation.x = -0.35;
    group.add(armL, armR);

    const legMat = new THREE.MeshStandardMaterial({ color: 0x222826, roughness: 0.85 });
    const legL = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.7, 0.18), legMat);
    const legR = legL.clone();
    legL.position.set(-0.14, 0.35, 0);
    legR.position.set(0.14, 0.35, 0);
    group.add(legL, legR);

    const gun = new THREE.Group();
    const gunBody = new THREE.Mesh(
      new THREE.BoxGeometry(0.08, 0.08, 0.55),
      new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.45, metalness: 0.6 }),
    );
    const gunMag = new THREE.Mesh(
      new THREE.BoxGeometry(0.06, 0.16, 0.08),
      new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.5, metalness: 0.5 }),
    );
    gunMag.position.set(0, -0.1, 0.05);
    gun.add(gunBody, gunMag);
    gun.position.set(0.4, 1.18, 0.32);
    group.add(gun);

    const muzzle = new THREE.Object3D();
    muzzle.position.set(0.4, 1.2, 0.62);
    group.add(muzzle);

    const badgeTex = makeVendorBadge(vendor);
    const badgeMat = new THREE.MeshBasicMaterial({ map: badgeTex, side: THREE.DoubleSide });
    const frontBadge = new THREE.Mesh(new THREE.PlaneGeometry(0.48, 0.24), badgeMat);
    frontBadge.position.set(0, 1.15, 0.3);
    group.add(frontBadge);
    const backBadge = new THREE.Mesh(new THREE.PlaneGeometry(0.48, 0.24), badgeMat);
    backBadge.position.set(0, 1.15, -0.3);
    backBadge.rotation.y = Math.PI;
    group.add(backBadge);

    this.scene.add(group);

    const profile = DIFFICULTY_PROFILES[overrideDifficulty ?? this.difficulty];    const pers = vendor.personality;    // HP 配合武器伤害（步枪22/发）：normal需要5发，elite需要7发，dumb需要3发
    const baseHp = variant === 'dirty' ? 110 : 100;
    const baseSpeed = variant === 'dirty' ? 2.6 : 2.0;
    const baseFireInterval = variant === 'dirty' ? 1.5 : 1.9;
    const baseAccuracy = variant === 'dirty' ? 0.55 : 0.42;
    const finalHp = Math.max(1, Math.round(baseHp * profile.hpMul));

    // 难度小标牌：在头顶 sprite 旁追加难度色环（替换头部材质 emissive）
    (head.material as THREE.MeshStandardMaterial).emissive = new THREE.Color(profile.badgeColor);
    (head.material as THREE.MeshStandardMaterial).emissiveIntensity = 0.18;

    const bug: BugEnemy = {
      group,
      core: torso,
      head,
      hp: finalHp,
      maxHp: finalHp,
      center: new THREE.Vector3(...spec.position),
      radius: spec.patrolRadius ?? 3.0,
      alive: true,
      deathTimer: 0,
      variant,
      vendor,
      speed: baseSpeed * profile.speedMul * pers.speedMul,
      fireTimer: 1.2 + Math.random() * 1.2,
      fireInterval: baseFireInterval * profile.fireIntervalMul * pers.fireIntervalMul,
      aimAccuracy: Math.min(0.95, baseAccuracy * profile.accuracyMul * pers.accuracyMul),
      muzzle,
      deathFallRot: 0,
      aiState: 'idle',
      stateTimer: 0,
      burstRemaining: 0,
      burstShotTimer: 0,
      repositionSign: Math.random() < 0.5 ? 1 : -1,
      spottedFired: false,
      hitShakeTimer: 0,
      recoilTimer: 0,
    };
    // 把伤害倍数挂在 userData 上，fireAtPlayer 时取用
    (bug as unknown as { damageMul: number }).damageMul = profile.damageMul;
    torso.userData['bugRef'] = bug;
    head.userData['bugRef'] = bug;
    this.bugs.push(bug);
    // R8.1: 若 Soldier.glb 已加载，立即把这个新敌人升级为真人模型
    if (BugEnemies.soldierGltf) this.swapToGLB(bug);
  }

  getHitMeshes(): THREE.Object3D[] {
    const out: THREE.Object3D[] = [];
    for (const b of this.bugs) {
      if (b.alive) out.push(b.core, b.head);
    }
    return out;
  }

  damage(mesh: THREE.Object3D, amount: number): { killed: boolean; bug: BugEnemy } | null {
    const ref = mesh.userData['bugRef'] as BugEnemy | undefined;
    if (!ref || !ref.alive) return null;
    const isHead = mesh.userData['isHead'] === true;
    const finalAmount = isHead ? amount * 2 : amount;
    ref.hp -= finalAmount;

    const mat = ref.core.material as THREE.MeshStandardMaterial;
    const prev = mat.emissive.getHex();
    mat.emissive.setHex(0xff2020);
    setTimeout(() => {
      if (ref.alive) mat.emissive.setHex(prev);
    }, 80);

    // R8.3 受击抖动
    ref.hitShakeTimer = 0.12;

    if (ref.hp <= 0) {
      ref.alive = false;
      ref.deathTimer = 6.0; // R8.3 保留尸体更久（最后 1.2s 才淡出）
      ref.deathFallRot = 0;
      synthAudio.play('bug_kill');
      // sangfor 保留原惨叫音效；所有 vendor 走台词库
      if (ref.vendor.key === 'sangfor') synthAudio.play('sangfor_scream');
      this._bark(ref, 'death', /*priority*/ true);
      // 队友通报：附近 <10m 活敌触发 ally_killed
      const dyingPos = ref.group.position;
      let allyAnnounced = false;
      for (const other of this.bugs) {
        if (other === ref || !other.alive) continue;
        if (other.group.position.distanceTo(dyingPos) < 10 && !allyAnnounced) {
          this._bark(other, 'ally_killed', false);
          allyAnnounced = true; // 单次淘汰只播一句队友反应，避免轰炸
          // 队友进入 alert（被惊动）
          if (other.aiState === 'idle') {
            other.aiState = 'alert';
            other.stateTimer = 0.25 + Math.random() * 0.3;
            other.spottedFired = true;
          }
        }
      }
      this.opts.onEnemyDamaged?.(ref.group.position.clone(), true);
      return { killed: true, bug: ref };
    }
    synthAudio.play('bug_hit');
    // R8.3：受击 35% 概率喊一句
    if (Math.random() < 0.35) this._bark(ref, 'hurt', false);
    // R8.3：中弹后按 vendor 个性决定是否跳位（LC=0%不动，sangfor=80%必退，zstack=15%莽）
    if (ref.aiState === 'engage' && Math.random() < ref.vendor.personality.repositionOnHitChance) {
      ref.aiState = 'reposition';
      ref.stateTimer = 0.7 + Math.random() * 0.7;
      ref.burstRemaining = 0;
      ref.repositionSign = Math.random() < 0.5 ? 1 : -1;
    }
    this.opts.onEnemyDamaged?.(ref.group.position.clone(), false);
    return { killed: false, bug: ref };
  }

  /** R8.3：vendor 台词广播（带全局节流 + spotted 弹"!"sprite） */
  private _bark(b: BugEnemy, type: BarkType, priority: boolean): void {
    const now = performance.now();
    if (!priority && now - _lastBarkAt < 1200) return; // 1.2s 全局节流
    if (!priority) _lastBarkAt = now; // priority 不调节流戳，避免防碍随后的 ally_killed
    const line = _pickLine(b.vendor.key, type);
    if (line) synthAudio.speak(line, { priority });
    if (type === 'spotted') {
      // 弹"!"sprite
      const mark = makeAlertMark();
      mark.position.set(0, 2.7, 0);
      mark.scale.set(0.45, 0.45, 1);
      b.group.add(mark);
      setTimeout(() => {
        b.group.remove(mark);
        (mark.material as THREE.SpriteMaterial).map?.dispose();
        (mark.material as THREE.SpriteMaterial).dispose();
      }, 850);
    }
  }

  private fireAtPlayer(b: BugEnemy): void {
    if (this.opts.isPlayerInvulnerable?.()) return;
    b.recoilTimer = 0.18; // 开火触发后坐力（时长略增，让射击反馈更明显）
    const shootAction = b.group.userData['shootAction'] as THREE.AnimationAction | undefined;
    if (shootAction) {
      shootAction.reset();
      shootAction.play();
      b.group.userData['shootBlendPulse'] = 0.18;
    }
    const muzzleWorld = new THREE.Vector3();
    b.muzzle.getWorldPosition(muzzleWorld);
    const target = this.opts.getPlayerPosition().clone();
    target.y += 1.4;

    const dir = this.tmpV.copy(target).sub(muzzleWorld).normalize();
    const distToTarget = muzzleWorld.distanceTo(target);
    if (this.obstacleList.length > 0) {
      const rc = new THREE.Raycaster(muzzleWorld, dir, 0, distToTarget);
      const blocks = rc.intersectObjects(this.obstacleList, true);
      if (blocks.length > 0) return;
    }

    const tracerGeo = new THREE.BufferGeometry().setFromPoints([muzzleWorld, target]);
    const tracer = new THREE.Line(
      tracerGeo,
      new THREE.LineBasicMaterial({ color: 0xff2222, transparent: true, opacity: 0.9 }),
    );
    this.scene.add(tracer);
    setTimeout(() => {
      this.scene.remove(tracer);
      tracerGeo.dispose();
    }, 80);

    // 枪口闪光：用 sprite 代替 PointLight
    // （PointLight 添加/删除会触发全场 shader recompile，是性能杀手）
    const flashGeo = new THREE.PlaneGeometry(0.28, 0.28);
    const flashMat = new THREE.MeshBasicMaterial({ color: 0xffb45a, transparent: true, opacity: 0.55, depthWrite: false });
    const flash = new THREE.Mesh(flashGeo, flashMat);
    flash.position.copy(muzzleWorld);
    flash.lookAt(this.opts.getPlayerPosition());
    this.scene.add(flash);
    setTimeout(() => {
      this.scene.remove(flash);
      flashGeo.dispose();
      flashMat.dispose();
    }, 60);

    synthAudio.play('gunshot_pistol');

    const distFactor = THREE.MathUtils.clamp(1.0 - (distToTarget - 3) / 18, 0.2, 1);
    const hitChance = b.aimAccuracy * distFactor;
    if (Math.random() < hitChance) {
      const baseDmg = b.variant === 'dirty' ? 14 : 10;
      const dmgMul = (b as unknown as { damageMul?: number }).damageMul ?? 1;
      this.opts.onHitPlayer(Math.round(baseDmg * dmgMul));
    }
  }

  update(dt: number): void {
    const playerPos = this.opts.getPlayerPosition();
    const playerDisabled = this.opts.isPlayerInvulnerable?.() ?? false;
    for (const b of this.bugs) {
      // 驱动 GLB AnimationMixer（若有）
      const mixer = b.group.userData['mixer'] as THREE.AnimationMixer | undefined;
      if (mixer) mixer.update(dt);

      const aimAction = b.group.userData['aimAction'] as THREE.AnimationAction | undefined;
      const shootAction = b.group.userData['shootAction'] as THREE.AnimationAction | undefined;
      if (shootAction) {
        const pulse = (b.group.userData['shootBlendPulse'] as number | undefined) ?? 0;
        const nextPulse = Math.max(0, pulse - dt);
        b.group.userData['shootBlendPulse'] = nextPulse;
        shootAction.setEffectiveWeight(THREE.MathUtils.clamp(nextPulse / 0.18, 0, 1));
      }
      if (b.recoilTimer > 0) b.recoilTimer = Math.max(0, b.recoilTimer - dt);

      // 持枪：枪优先挂在右手骨骼，后坐力在基础偏移上叠加，避免把挂点冲掉。
      const gunGroup = b.group.userData['gunGroup'] as THREE.Group | undefined;
      if (gunGroup) {
        gunGroup.visible = b.alive;
        const baseX = (b.group.userData['gunBaseX'] as number | undefined) ?? gunGroup.position.x;
        const baseY = (b.group.userData['gunBaseY'] as number | undefined) ?? gunGroup.position.y;
        const baseZ = (b.group.userData['gunBaseZ'] as number | undefined) ?? gunGroup.position.z;
        // 后坐力：沿枪管方向（局部 -X）轻微后移，开火时给手感
        if (b.alive && b.recoilTimer > 0) {
          const k = b.recoilTimer / 0.18;
          gunGroup.position.set(baseX - 0.04 * k, baseY, baseZ);
        } else if (b.alive) {
          gunGroup.position.set(baseX, baseY, baseZ);
        }
      }

      // R8.3 受击抖动（活/死都生效，提供手感）
      if (b.hitShakeTimer > 0) {
        b.hitShakeTimer = Math.max(0, b.hitShakeTimer - dt);
        const k = b.hitShakeTimer / 0.12;
        b.group.position.x += (Math.random() - 0.5) * 0.04 * k;
        b.group.position.z += (Math.random() - 0.5) * 0.04 * k;
      }

      if (!b.alive) {
        b.deathTimer -= dt;
        if (b.deathFallRot < Math.PI / 2) {
          b.deathFallRot = Math.min(Math.PI / 2, b.deathFallRot + dt * 3.2);
          b.group.rotation.x = -b.deathFallRot;
          b.group.position.y = -b.deathFallRot * 0.1;
        } else if (b.deathTimer < 1.2) {
          b.group.traverse((obj) => {
            const mesh = obj as THREE.Mesh;
            if (mesh.material) {
              const m = mesh.material as THREE.Material | THREE.Material[];
              if (Array.isArray(m)) {
                for (const x of m) {
                  x.transparent = true;
                  (x as unknown as { opacity: number }).opacity = Math.max(0, b.deathTimer / 1.2);
                }
              } else {
                m.transparent = true;
                (m as unknown as { opacity: number }).opacity = Math.max(0, b.deathTimer / 1.2);
              }
            }
          });
        }
        if (b.deathTimer <= 0 && b.group.parent) this.scene.remove(b.group);
        continue;
      }

      const toPlayer = this.tmpV
        .copy(playerPos)
        .setY(0)
        .sub(this.tmpV2.copy(b.group.position).setY(0));
      const dist = toPlayer.length();
      if (dist > 0.001) toPlayer.multiplyScalar(1 / dist);

      if (aimAction) {
        // 保持常态举枪：即使 idle 也给较高权重，避免双臂自然下垂。
        const shouldAim = b.alive;
        const aimTarget = shouldAim
          ? THREE.MathUtils.clamp(1.08 - dist / 24, 0.7, 1)
          : 0;
        const w = aimAction.getEffectiveWeight();
        aimAction.setEffectiveWeight(THREE.MathUtils.lerp(w, aimTarget, 0.18));
      }

      // SWAT 模型在当前场景里不需要额外 +PI 翻转，否则会背对玩家。
      // idle 时不强制朝玩家；alert/engage/reposition 才转身。
      if (b.aiState !== 'idle') {
        const facingAngle = Math.atan2(toPlayer.x, toPlayer.z);
        // 平滑插值：每帧最多转 ~6 rad/s，避免瞬切
        let dy = facingAngle - b.group.rotation.y;
        // 归一化到 [-PI, PI]
        while (dy > Math.PI) dy -= Math.PI * 2;
        while (dy < -Math.PI) dy += Math.PI * 2;
        const maxStep = 6.0 * dt;
        if (Math.abs(dy) <= maxStep) b.group.rotation.y = facingAngle;
        else b.group.rotation.y += Math.sign(dy) * maxStep;
      }

      // 玩家死亡/无敌时，土匪原地站立不推进也不开火
      if (playerDisabled) {
        b.fireTimer = Math.max(b.fireTimer, 0.8);
        b.aiState = 'idle';
        b.burstRemaining = 0;
        continue;
      }

      // ============= AI 状态机 =============
      b.stateTimer = Math.max(0, b.stateTimer - dt);

      // idle → alert：发现玩家（仅距离判定，简化版）
      if (b.aiState === 'idle' && dist < 22) {
        b.aiState = 'alert';
        b.stateTimer = 0.45 + Math.random() * 0.4; // 反应延迟 0.45-0.85s
        b.burstRemaining = 0;
        // R8.3：首次发现玩家时喊话 + 弹"!"
        if (!b.spottedFired) {
          this._bark(b, 'spotted', false);
          b.spottedFired = true;
        }
      }
      // alert → engage：反应延迟结束
      if (b.aiState === 'alert' && b.stateTimer <= 0) {
        b.aiState = 'engage';
        b.fireTimer = 0.15 + Math.random() * 0.25; // 第一发短暂瞄准
        b.burstRemaining = 0;
      }
      // reposition → engage：跳位窗口结束
      if (b.aiState === 'reposition' && b.stateTimer <= 0) {
        b.aiState = 'engage';
        b.fireTimer = 0.4 + Math.random() * 0.4;
        b.burstRemaining = 0;
      }
      // 玩家跑远后回 idle（避免远距离仍被全图锁定开火）
      if (b.aiState !== 'idle' && dist > 26) {
        b.aiState = 'idle';
        b.burstRemaining = 0;
      }

      // ============= 移动逻辑 =============
      if (b.aiState === 'reposition') {
        // 强制侧向跳位（速度 ×1.4），不前进不后退
        const sideX = -toPlayer.z;
        const sideZ = toPlayer.x;
        const nx = b.group.position.x + sideX * b.repositionSign * b.speed * 1.4 * dt;
        const nz = b.group.position.z + sideZ * b.repositionSign * b.speed * 1.4 * dt;
        if (!this._collisionCheck || !this._collisionCheck(new THREE.Vector3(nx, 0, nz), 0.3)) {
          b.group.position.x = nx;
          b.group.position.z = nz;
        }
        const run  = b.group.userData['runAction']  as THREE.AnimationAction | null | undefined;
        const idle = b.group.userData['idleAction'] as THREE.AnimationAction | null | undefined;
        if (run && idle && !run.isRunning()) { idle.stop(); run.play(); }
      } else if (b.aiState === 'engage' || b.aiState === 'alert') {
        if (dist > 6.5) {
          const nx = b.group.position.x + toPlayer.x * b.speed * dt;
          const nz = b.group.position.z + toPlayer.z * b.speed * dt;
          if (!this._collisionCheck || !this._collisionCheck(new THREE.Vector3(nx, 0, nz), 0.3)) {
            b.group.position.x = nx;
            b.group.position.z = nz;
          }
          const run  = b.group.userData['runAction']  as THREE.AnimationAction | null | undefined;
          const idle = b.group.userData['idleAction'] as THREE.AnimationAction | null | undefined;
          if (run && idle && !run.isRunning()) { idle.stop(); run.play(); }
        } else if (dist < b.vendor.personality.minEngageDist) {
          // R8.3：LC（minEngageDist=3.5）正常后退；街溜子（0）不进这分支，贴脸打
          const retreat = b.vendor.personality.retreatMul;
          const nx = b.group.position.x - toPlayer.x * b.speed * 0.5 * retreat * dt;
          const nz = b.group.position.z - toPlayer.z * b.speed * 0.5 * retreat * dt;
          if (!this._collisionCheck || !this._collisionCheck(new THREE.Vector3(nx, 0, nz), 0.3)) {
            b.group.position.x = nx;
            b.group.position.z = nz;
          }
        } else {
          const sideX = -toPlayer.z;
          const sideZ = toPlayer.x;
          const sign = Math.sin((performance.now() / 1000 + b.center.x) * 0.8) > 0 ? 1 : -1;
          const nx = b.group.position.x + sideX * sign * b.speed * 0.4 * dt;
          const nz = b.group.position.z + sideZ * sign * b.speed * 0.4 * dt;
          if (!this._collisionCheck || !this._collisionCheck(new THREE.Vector3(nx, 0, nz), 0.3)) {
            b.group.position.x = nx;
            b.group.position.z = nz;
          }
          const run  = b.group.userData['runAction']  as THREE.AnimationAction | null | undefined;
          const idle = b.group.userData['idleAction'] as THREE.AnimationAction | null | undefined;
          if (run && idle && run.isRunning()) { run.stop(); idle.play(); }
        }
      }
      b.group.position.y = Math.abs(Math.sin(performance.now() / 180 + b.center.x)) * 0.04;

      // ============= 开火节奏（点射 burst） =============
      if (b.aiState === 'engage' && dist < 18 && dist > 2) {
        b.fireTimer -= dt;
        if (b.burstRemaining > 0) {
          // burst 中：按 burstShotTimer 节拍连发
          b.burstShotTimer -= dt;
          if (b.burstShotTimer <= 0) {
            this.fireAtPlayer(b);
            b.burstRemaining -= 1;
            b.burstShotTimer = 0.11 + Math.random() * 0.05; // 90-130ms 内连发
            if (b.burstRemaining <= 0) {
              // burst 结束，进入冷却
              b.fireTimer = b.fireInterval + (Math.random() - 0.5) * 0.5;
            }
          }
        } else if (b.fireTimer <= 0) {
          // 启动新的 burst：2-4 发
          b.burstRemaining = 2 + Math.floor(Math.random() * 3);
          b.burstShotTimer = 0;
          // R8.3：huawei 同伴 buff —— 10m 内有同 vendor 同伴时开火间隔 ×0.7
          if (b.vendor.personality.companionFireMul < 1) {
            let hasCompanion = false;
            for (const other of this.bugs) {
              if (other === b || !other.alive || other.vendor.key !== b.vendor.key) continue;
              const dx = other.group.position.x - b.group.position.x;
              const dz = other.group.position.z - b.group.position.z;
              if (dx * dx + dz * dz < 100) { hasCompanion = true; break; }
            }
            if (hasCompanion) {
              b.fireInterval *= b.vendor.personality.companionFireMul;
              // 只乘一次避免衰减：记录为已 buff
              b.vendor = { ...b.vendor, personality: { ...b.vendor.personality, companionFireMul: 1.0 } };
            }
          }
        }
      }
    }

    const aliveCount = this.bugs.filter((b) => b.alive).length;
    if (this.respawnEnabled && aliveCount < this.respawnPool.length) {
      this.respawnTimer -= dt;
      if (this.respawnTimer <= 0) {
        const missing = this.respawnPool.find((s) => {
          return !this.bugs.some(
            (b) =>
              b.alive &&
              Math.abs(b.center.x - s.position[0]) < 0.5 &&
              Math.abs(b.center.z - s.position[2]) < 0.5,
          );
        });
        if (missing) {
          this.spawn(missing, 'normal');
          EventBus.emit('bug:spawn', { position: missing.position });
        }
        this.respawnTimer = this.spawnCooldown;
      }
    }
  }

  get aliveCount(): number {
    return this.bugs.filter((b) => b.alive).length;
  }
  get dirtyAliveCount(): number {
    return this.bugs.filter((b) => b.alive && b.variant === 'dirty').length;
  }
  get aliveBandits(): BugEnemy[] {
    return this.bugs.filter((b) => b.alive);
  }
}

