/**
 * RealisticDataCenter —— 补充"真实机房"视觉层：
 *   · 服务器机柜阵列（冷通道/热通道双排）
 *   · 机柜指示灯脉冲
 *   · vCenter 大屏广告牌（正对指挥台）
 *   · 冷通道地面灯带
 *   · 屋顶 HVAC 管道与线缆桥架
 *
 * 实现策略：用程序化几何 + CanvasTexture 生成标签/屏幕；
 * 不引入外部 GLB/FBX 模型（避免许可与离线资产问题）。
 *
 * 返回：
 *   - rackMeshes: 敌人 LOS 判定用的障碍物列表
 *   - vcenterBillboard: vCenter 大屏 Mesh 引用（外部可动态修改文本）
 */
import * as THREE from 'three';
import type { CollisionSystem } from '../fps/CollisionSystem';

function makeRackTexture(rackId: string): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 512;
  const ctx = canvas.getContext('2d')!;
  // 机柜主体深灰
  ctx.fillStyle = '#1a1e24';
  ctx.fillRect(0, 0, 256, 512);
  // 顶部铭牌
  ctx.fillStyle = '#0d1117';
  ctx.fillRect(0, 0, 256, 36);
  ctx.fillStyle = '#4cdcff';
  ctx.font = 'bold 17px monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(`SMTX RACK · ${rackId}`, 128, 18);

  // 42 U 每层一块服务器面板
  for (let u = 0; u < 22; u++) {
    const y = 44 + u * 20;
    // 面板底
    ctx.fillStyle = u % 3 === 0 ? '#2a313b' : '#21262e';
    ctx.fillRect(6, y, 244, 17);
    // 散热孔
    ctx.fillStyle = '#0a0d11';
    for (let hx = 12; hx < 244; hx += 6) ctx.fillRect(hx, y + 4, 3, 9);
    // 状态灯（绿/琥珀）
    ctx.fillStyle = u % 7 === 3 ? '#ffb300' : '#33dd55';
    ctx.beginPath();
    ctx.arc(16, y + 8, 2.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#33dd55';
    ctx.beginPath();
    ctx.arc(24, y + 8, 2.2, 0, Math.PI * 2);
    ctx.fill();
    // 铭牌文字
    ctx.fillStyle = '#7a8391';
    ctx.font = '9px monospace';
    ctx.textAlign = 'left';
    ctx.fillText(`U${(42 - u).toString().padStart(2, '0')} ESXi-${u.toString(16)}`, 34, y + 12);
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.anisotropy = 4;
  return tex;
}

function makeVCenterScreen(): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 1024;
  canvas.height = 512;
  const ctx = canvas.getContext('2d')!;
  // 深蓝底 + 科技网格
  const grad = ctx.createLinearGradient(0, 0, 0, 512);
  grad.addColorStop(0, '#0a1628');
  grad.addColorStop(1, '#0f2a4a');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 1024, 512);

  ctx.strokeStyle = 'rgba(64,160,255,0.15)';
  ctx.lineWidth = 1;
  for (let x = 0; x < 1024; x += 48) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, 512);
    ctx.stroke();
  }
  for (let y = 0; y < 512; y += 48) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(1024, y);
    ctx.stroke();
  }

  // 顶部 VMWARE logo 条
  ctx.fillStyle = '#0a1220';
  ctx.fillRect(0, 0, 1024, 64);
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 32px "Helvetica Neue", Arial, sans-serif';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText('vmware', 32, 32);
  ctx.fillStyle = '#4cdcff';
  ctx.font = 'bold 22px "Helvetica Neue", Arial, sans-serif';
  ctx.fillText('vCenter Server 7.0', 168, 32);
  ctx.fillStyle = '#66ff9b';
  ctx.font = 'bold 16px monospace';
  ctx.textAlign = 'right';
  ctx.fillText('● ONLINE', 992, 32);

  // 中央标题
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 96px "Helvetica Neue", Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('vCenter', 512, 190);
  ctx.fillStyle = '#4cdcff';
  ctx.font = 'bold 64px "Helvetica Neue", Arial, sans-serif';
  ctx.fillText('SOURCE · VMWARE SIDE', 512, 268);

  // 下方连接信息
  ctx.fillStyle = 'rgba(255,255,255,0.92)';
  ctx.font = '24px monospace';
  ctx.fillText('HOST : vc.smartx.lab', 512, 350);
  ctx.fillText('IP   : 172.16.0.5', 512, 384);
  ctx.fillText('ESXi : 4 hosts · 16 datastores · 42 VMs', 512, 418);

  ctx.fillStyle = '#ffb300';
  ctx.font = 'bold 22px monospace';
  ctx.fillText('[ PRESS  E  TO LOGIN & SCAN ]', 512, 470);

  const tex = new THREE.CanvasTexture(canvas);
  tex.anisotropy = 8;
  return tex;
}

function makeSmartXScreen(): THREE.CanvasTexture {
  const canvas = document.createElement('canvas');
  canvas.width = 1024;
  canvas.height = 512;
  const ctx = canvas.getContext('2d')!;
  const grad = ctx.createLinearGradient(0, 0, 0, 512);
  grad.addColorStop(0, '#0a2818');
  grad.addColorStop(1, '#0f4a2a');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 1024, 512);
  ctx.strokeStyle = 'rgba(80,220,128,0.15)';
  ctx.lineWidth = 1;
  for (let x = 0; x < 1024; x += 48) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, 512);
    ctx.stroke();
  }
  for (let y = 0; y < 512; y += 48) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(1024, y);
    ctx.stroke();
  }
  ctx.fillStyle = '#0a1a14';
  ctx.fillRect(0, 0, 1024, 64);
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 32px "Helvetica Neue", Arial, sans-serif';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText('SmartX', 32, 32);
  ctx.fillStyle = '#66ff9b';
  ctx.font = 'bold 22px "Helvetica Neue", Arial, sans-serif';
  ctx.fillText('ELF Cluster · CloudTower', 200, 32);
  ctx.fillStyle = '#66ff9b';
  ctx.font = 'bold 16px monospace';
  ctx.textAlign = 'right';
  ctx.fillText('● READY FOR MIGRATION', 992, 32);

  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 96px "Helvetica Neue", Arial, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('SmartX ELF', 512, 190);
  ctx.fillStyle = '#66ff9b';
  ctx.font = 'bold 56px "Helvetica Neue", Arial, sans-serif';
  ctx.fillText('TARGET · HYPERCONVERGED', 512, 264);

  ctx.fillStyle = 'rgba(255,255,255,0.92)';
  ctx.font = '24px monospace';
  ctx.fillText('Nodes : 4 × H1800 · NVMe+SSD+HDD', 512, 346);
  ctx.fillText('Pools : nvme-01 / ssd-01 / hdd-01', 512, 380);
  ctx.fillText('Boss-Level Feature : I/O Locality · RDMA', 512, 414);

  const tex = new THREE.CanvasTexture(canvas);
  tex.anisotropy = 8;
  return tex;
}

/** 仅添加每个机柜独有的装饰层：面板贴图、LED 指示灯、碰撞盒。
 *  机柜主体/顶盖/底座已由 buildRealisticDataCenter 用 InstancedMesh 批量创建。
 */
function addRackDecorations(
  scene: THREE.Scene,
  collision: CollisionSystem,
  x: number,
  z: number,
  rackId: string,
  facing: number,
  outMeshes: THREE.Object3D[],
): void {
  const group = new THREE.Group();
  group.position.set(x, 0, z);
  group.rotation.y = facing;

  // 正面面板（贴图）
  const panelTex = makeRackTexture(rackId);
  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(0.76, 2.0),
    new THREE.MeshStandardMaterial({
      map: panelTex,
      roughness: 0.7,
      metalness: 0.3,
      emissiveMap: panelTex,
      emissive: 0x4a6080,
      emissiveIntensity: 0.22,
    }),
  );
  panel.position.set(0, 1.025, 0.501);
  group.add(panel);

  // —— 独立 LED 小灯（5 颗，面板右侧竖排）——
  const ledColors = [0x2a8844, 0x2a8844, 0xa07020, 0x2a8844, 0x883333];
  const ledEmissive = [0x1f6633, 0x1f6633, 0x704818, 0x1f6633, 0x662222];
  for (let i = 0; i < 5; i++) {
    const led = new THREE.Mesh(
      new THREE.PlaneGeometry(0.05, 0.05),
      new THREE.MeshStandardMaterial({
        color: ledColors[i],
        emissive: ledEmissive[i],
        emissiveIntensity: 0.1 + Math.random() * 0.06,
        roughness: 0.4,
      }),
    );
    led.position.set(0.3, 1.7 - i * 0.12, 0.503);
    led.userData['__rackLed'] = true;
    group.add(led);
  }

  // 顶部状态 LED（亮绿）
  const statusLed = new THREE.Mesh(
    new THREE.SphereGeometry(0.04, 6, 6),
    new THREE.MeshBasicMaterial({ color: 0x2a8844 }),
  );
  statusLed.position.set(0, 2.1, 0.6);
  group.add(statusLed);

  scene.add(group);

  // 碰撞盒（AABB，按朝向选取正确的 x/z 半宽）
  const hx = facing === 0 ? 0.45 : 0.55;
  const hz = facing === 0 ? 0.55 : 0.45;
  collision.add({
    box: new THREE.Box3(
      new THREE.Vector3(x - hx, 0, z - hz),
      new THREE.Vector3(x + hx, 2.08, z + hz),
    ),
    solid: true,
  });

  void outMeshes; // body 已由 InstancedMesh 负责，此处不再 push
}

function addCableTray(scene: THREE.Scene, x: number, z1: number, z2: number): void {
  const length = Math.abs(z2 - z1);
  const group = new THREE.Group();
  group.position.set(x, 2.45, (z1 + z2) / 2);

  // 桥架
  const tray = new THREE.Mesh(
    new THREE.BoxGeometry(0.35, 0.05, length),
    new THREE.MeshStandardMaterial({ color: 0x2b3240, metalness: 0.7, roughness: 0.4 }),
  );
  group.add(tray);

  // 线缆（多色扎束）
  const cableColors = [0xff5555, 0x55ff55, 0x5599ff, 0xffcc44, 0xcc88ff];
  for (let i = 0; i < 5; i++) {
    const c = new THREE.Mesh(
      new THREE.CylinderGeometry(0.025, 0.025, length, 8),
      new THREE.MeshStandardMaterial({ color: cableColors[i], roughness: 0.6 }),
    );
    c.rotation.x = Math.PI / 2;
    c.position.set(-0.12 + i * 0.06, -0.02, 0);
    group.add(c);
  }
  scene.add(group);
}

function addVCenterBillboard(scene: THREE.Scene, x: number, y: number, z: number): THREE.Mesh {
  const tex = makeVCenterScreen();
  const screen = new THREE.Mesh(
    new THREE.PlaneGeometry(3.2, 1.6),
    new THREE.MeshBasicMaterial({ map: tex }),
  );
  screen.position.set(x, y, z);

  // 画面边框
  const frame = new THREE.Mesh(
    new THREE.BoxGeometry(3.36, 1.76, 0.08),
    new THREE.MeshStandardMaterial({ color: 0x0a1220, metalness: 0.7, roughness: 0.4 }),
  );
  frame.position.set(x, y, z - 0.05);
  scene.add(frame);
  scene.add(screen);
  // glow PointLight 已移除（屏幕 MeshBasic 自带发光，不需要真实光源）

  return screen;
}

function addSmartXBillboard(scene: THREE.Scene, x: number, y: number, z: number): void {
  const tex = makeSmartXScreen();
  const screen = new THREE.Mesh(
    new THREE.PlaneGeometry(3.2, 1.6),
    new THREE.MeshBasicMaterial({ map: tex }),
  );
  screen.position.set(x, y, z);
  screen.rotation.y = Math.PI;

  const frame = new THREE.Mesh(
    new THREE.BoxGeometry(3.36, 1.76, 0.08),
    new THREE.MeshStandardMaterial({ color: 0x0a1a14, metalness: 0.7, roughness: 0.4 }),
  );
  frame.position.set(x, y, z + 0.05);
  scene.add(frame);
  scene.add(screen);
  // glow PointLight 已移除
}

function addFloorStrip(scene: THREE.Scene, x1: number, x2: number, z: number, color: number): void {
  const length = Math.abs(x2 - x1);
  const strip = new THREE.Mesh(
    new THREE.PlaneGeometry(length, 0.12),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.35 }),
  );
  strip.rotation.x = -Math.PI / 2;
  strip.position.set((x1 + x2) / 2, 0.02, z);
  scene.add(strip);
}

export interface RealisticDataCenterResult {
  rackMeshes: THREE.Object3D[]; // 供敌人 LOS 判定
  vcenterScreen: THREE.Mesh;
  /** 每帧调用，驱动 LED 闪烁 + 烟雾粒子 */
  update: (dt: number) => void;
  /** 在指定世界坐标喷一团烟 */
  emitSmoke: (x: number, y: number, z: number, amount?: number) => void;
}

export function buildRealisticDataCenter(
  scene: THREE.Scene,
  collision: CollisionSystem,
): RealisticDataCenterResult {
  const rackMeshes: THREE.Object3D[] = [];

  // 4行×8列热/冷通道布局，全部在机房范围内（x∈[-4.5,+4.5], z∈[-6.5,-13.5]）
  const RACK_X = [-3.5, -2.5, -1.5, -0.5, 0.5, 1.5, 2.5, 3.5];
  const rackSpecs: Array<{ x: number; z: number; id: string; facing: number }> = [
    // 行A（z=-7, 面朝南-入口方向，冷通道z=-6）
    ...RACK_X.map((x, i) => ({ x, z: -7.0, id: `A${(i + 1).toString().padStart(2, '0')}`, facing: 0 })),
    // 行B（z=-9, 背靠背A面朝北，热通道z=-8）
    ...RACK_X.map((x, i) => ({ x, z: -9.0, id: `B${(i + 1).toString().padStart(2, '0')}`, facing: Math.PI })),
    // 行C（z=-11, 面朝南，冷通道z=-10）
    ...RACK_X.map((x, i) => ({ x, z: -11.0, id: `C${(i + 1).toString().padStart(2, '0')}`, facing: 0 })),
    // 行D（z=-13, 背靠背C面朝北，热通道z=-12）
    ...RACK_X.map((x, i) => ({ x, z: -13.0, id: `D${(i + 1).toString().padStart(2, '0')}`, facing: Math.PI })),
  ];
  const RACK_N = rackSpecs.length; // 32

  // —— InstancedMesh：机柜主体 / 顶盖 / 底座（共享几何体，1 次 Draw Call 各自）——
  const bodyInstanced = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.8, 2.05, 1.0),
    new THREE.MeshStandardMaterial({ color: 0x5a6478, metalness: 0.45, roughness: 0.45, emissive: 0x1a2030, emissiveIntensity: 0.04 }),
    RACK_N,
  );
  const topInstanced = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.82, 0.03, 1.02),
    new THREE.MeshStandardMaterial({ color: 0x2a2f3a, roughness: 0.75 }),
    RACK_N,
  );
  const baseInstanced = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.88, 0.08, 1.08),
    new THREE.MeshStandardMaterial({ color: 0x252a35, roughness: 0.85 }),
    RACK_N,
  );
  bodyInstanced.frustumCulled = false;
  topInstanced.frustumCulled = false;
  baseInstanced.frustumCulled = false;

  const dummy = new THREE.Object3D();
  rackSpecs.forEach(({ x, z, id, facing }, i) => {
    dummy.rotation.set(0, facing, 0);

    dummy.position.set(x, 1.025, z);
    dummy.updateMatrix();
    bodyInstanced.setMatrixAt(i, dummy.matrix);

    dummy.position.set(x, 2.06, z);
    dummy.updateMatrix();
    topInstanced.setMatrixAt(i, dummy.matrix);

    dummy.position.set(x, 0.04, z);
    dummy.updateMatrix();
    baseInstanced.setMatrixAt(i, dummy.matrix);

    // 每个机柜的独有装饰（面板贴图 + LED + 碰撞盒）
    addRackDecorations(scene, collision, x, z, id, facing, rackMeshes);
  });
  bodyInstanced.instanceMatrix.needsUpdate = true;
  topInstanced.instanceMatrix.needsUpdate = true;
  baseInstanced.instanceMatrix.needsUpdate = true;

  scene.add(bodyInstanced);
  scene.add(topInstanced);
  scene.add(baseInstanced);

  // bodyInstanced 用于敌人 LOS 射线检测（Three.js 支持 InstancedMesh 射线拾取）
  rackMeshes.push(bodyInstanced);

  // —— 热/冷通道地面灯带 ——
  // 冷通道（蓝色）
  addFloorStrip(scene, -4.0, 4.0, -6.0,  0x1a3d5a); // 冷通道A（Row A 前方）
  addFloorStrip(scene, -4.0, 4.0, -10.0, 0x1a3d5a); // 冷通道B（Row C 前方）
  // 热通道（暗橙色）
  addFloorStrip(scene, -4.0, 4.0, -8.0,  0x5a2010); // 热通道A（Row A/B 之间）
  addFloorStrip(scene, -4.0, 4.0, -12.0, 0x5a2010); // 热通道B（Row C/D 之间）

  // —— 机柜区线缆桥架（正南北方向，覆盖全程） ——
  addCableTray(scene, -3.15, -14, -5); // 西侧桥架
  addCableTray(scene,  0,    -14, -5); // 中央桥架
  addCableTray(scene,  3.15, -14, -5); // 东侧桥架

  // —— vCenter 大屏（机柜区北墙，玩家走入机房右手可见） ——
  const vcenterScreen = addVCenterBillboard(scene, 0, 2.4, -13.5);

  // —— SmartX 目标端大屏（玩家身后背面，回头可见） ——
  addSmartXBillboard(scene, 0, 3.2, 9.4);

  // —— HVAC 排风管道（坐落在每排机柜正上方） ——
  for (const hz of [-7, -9, -11, -13]) {
    const pipe = new THREE.Mesh(
      new THREE.CylinderGeometry(0.14, 0.14, 8, 12),
      new THREE.MeshStandardMaterial({ color: 0x9aa3b0, metalness: 0.9, roughness: 0.35 }),
    );
    pipe.rotation.z = Math.PI / 2;
    pipe.position.set(0, 3.8, hz);
    scene.add(pipe);
  }

  // —— 吊顶射灯阵列：3排 × 2盏 = 6 盏（每像素遍历每个光源，不能多）
  // 灯具实体共享一份材质，减少 draw call
  const spotlights: THREE.SpotLight[] = [];
  const fixtureGeom = new THREE.CylinderGeometry(0.12, 0.18, 0.18, 8);
  const fixtureMat = new THREE.MeshStandardMaterial({ color: 0x1a1c20, metalness: 0.7, roughness: 0.4, emissive: 0xfff0d0, emissiveIntensity: 0.20 });
  const spotRows = [-6.0, -8.0, -10.0, -12.0, -2.5, 2.5];
  for (const sz of spotRows) {
    for (let i = 0; i < 2; i++) {
      const sx = -4.5 + i * 9;
      const fixture = new THREE.Mesh(fixtureGeom, fixtureMat);
      fixture.position.set(sx, 4.45, sz);
      scene.add(fixture);

      // range 加大到 14 覆盖更广区域，弥补盏数减少
      const spot = new THREE.SpotLight(0xfff0d0, 1.1, 14, Math.PI / 5, 0.7, 1.3);
      spot.position.set(sx, 4.4, sz);
      spot.target.position.set(sx, 0, sz);
      scene.add(spot);
      scene.add(spot.target);
      spotlights.push(spot);
    }
  }
  // 视觉填充：在没有 SpotLight 的位置加纯发光灯具（无光源开销）
  for (const sz of [-6.0, -8.0, -10.0, -12.0]) {
    for (let i = 0; i < 3; i++) {
      const sx = -3 + i * 3;
      const fixture = new THREE.Mesh(fixtureGeom, fixtureMat);
      fixture.position.set(sx, 4.45, sz);
      scene.add(fixture);
    }
  }

  // —— 收集所有机柜 LED 材质用于闪烁 ——
  const ledMaterials: THREE.MeshStandardMaterial[] = [];
  scene.traverse((obj) => {
    const mesh = obj as THREE.Mesh;
    if (mesh.isMesh && mesh.userData['__rackLed']) {
      const mat = mesh.material as THREE.MeshStandardMaterial;
      if (mat && 'emissiveIntensity' in mat) ledMaterials.push(mat);
    }
  });

  // —— 烟雾粒子系统 ——
  const SMOKE_MAX = 64;
  const smokePositions = new Float32Array(SMOKE_MAX * 3);
  const smokeVelocity: { vx: number; vy: number; vz: number; life: number; maxLife: number }[] = [];
  for (let i = 0; i < SMOKE_MAX; i++) {
    smokePositions[i * 3] = 0;
    smokePositions[i * 3 + 1] = -100; // 远离视野，未激活
    smokePositions[i * 3 + 2] = 0;
    smokeVelocity.push({ vx: 0, vy: 0, vz: 0, life: 0, maxLife: 1 });
  }
  const smokeGeo = new THREE.BufferGeometry();
  smokeGeo.setAttribute('position', new THREE.BufferAttribute(smokePositions, 3));
  // 软圆盘贴图
  const smokeCanvas = document.createElement('canvas');
  smokeCanvas.width = 64;
  smokeCanvas.height = 64;
  const sctx = smokeCanvas.getContext('2d')!;
  const grad = sctx.createRadialGradient(32, 32, 4, 32, 32, 32);
  grad.addColorStop(0, 'rgba(220,220,220,0.9)');
  grad.addColorStop(0.4, 'rgba(180,180,180,0.5)');
  grad.addColorStop(1, 'rgba(120,120,120,0)');
  sctx.fillStyle = grad;
  sctx.fillRect(0, 0, 64, 64);
  const smokeTex = new THREE.CanvasTexture(smokeCanvas);
  const smokeMat = new THREE.PointsMaterial({
    size: 0.9,
    map: smokeTex,
    transparent: true,
    opacity: 0.55,
    depthWrite: false,
    blending: THREE.NormalBlending,
    sizeAttenuation: true,
  });
  const smokePoints = new THREE.Points(smokeGeo, smokeMat);
  smokePoints.frustumCulled = false;
  scene.add(smokePoints);

  let smokeCursor = 0;
  const emitSmoke = (x: number, y: number, z: number, amount = 6): void => {
    for (let i = 0; i < amount; i++) {
      const idx = smokeCursor;
      smokeCursor = (smokeCursor + 1) % SMOKE_MAX;
      smokePositions[idx * 3] = x + (Math.random() - 0.5) * 0.4;
      smokePositions[idx * 3 + 1] = y + (Math.random() - 0.5) * 0.2;
      smokePositions[idx * 3 + 2] = z + (Math.random() - 0.5) * 0.4;
      const v = smokeVelocity[idx];
      v.vx = (Math.random() - 0.5) * 0.4;
      v.vy = 0.4 + Math.random() * 0.5;
      v.vz = (Math.random() - 0.5) * 0.4;
      v.maxLife = 1.4 + Math.random() * 1.0;
      v.life = v.maxLife;
    }
  };

  let ledTimer = 0;
  let alertTimer = 0;
  const update = (dt: number): void => {
    // LED 节奏闪烁：每 0.12s 随机刷新 ~6 个 LED 的 emissive 强度
    ledTimer += dt;
    if (ledTimer >= 0.12 && ledMaterials.length > 0) {
      ledTimer = 0;
      const n = Math.min(8, ledMaterials.length);
      for (let k = 0; k < n; k++) {
        const m = ledMaterials[(Math.random() * ledMaterials.length) | 0];
        m.emissiveIntensity = 0.06 + Math.random() * 0.12;
      }
    }
    // 警报灯脉冲（0.8s 一周期，十分柔和）
    alertTimer += dt;
    const alertPulse = Math.max(0, Math.sin(alertTimer * Math.PI / 0.8));
    for (const al of alertLights) al.intensity = alertPulse * 0.05;
    // 烟雾粒子推进
    let dirty = false;
    for (let i = 0; i < SMOKE_MAX; i++) {
      const v = smokeVelocity[i];
      if (v.life <= 0) continue;
      v.life -= dt;
      smokePositions[i * 3] += v.vx * dt;
      smokePositions[i * 3 + 1] += v.vy * dt;
      smokePositions[i * 3 + 2] += v.vz * dt;
      v.vy *= 0.96; // 上升衰减
      if (v.life <= 0) {
        smokePositions[i * 3 + 1] = -100;
      }
      dirty = true;
    }
    if (dirty) smokeGeo.attributes['position']!.needsUpdate = true;
  };

  // 注册到 spotlights 占位以避免未使用警告
  void spotlights;

  // —— 天光神射（God Rays）已移除：过于醒目的蓝色体积光与柔和灯泡风格不吻合
  void 0;

  // —— 地面：架空地板砖纹 + 轻微金属感 ——
  const floorCanvas = document.createElement('canvas');
  floorCanvas.width = 256; floorCanvas.height = 256;
  const fctx = floorCanvas.getContext('2d')!;
  // 砖块底色
  fctx.fillStyle = '#1a1e24';
  fctx.fillRect(0, 0, 256, 256);
  // 砖缝（每 64px 一块，模拟 60cm 架空地板）
  fctx.strokeStyle = '#0d1018';
  fctx.lineWidth = 2;
  for (let i = 0; i <= 256; i += 64) {
    fctx.beginPath(); fctx.moveTo(i, 0); fctx.lineTo(i, 256); fctx.stroke();
    fctx.beginPath(); fctx.moveTo(0, i); fctx.lineTo(256, i); fctx.stroke();
  }
  // 螺丝角点
  fctx.fillStyle = '#2a2f3a';
  for (let x = 0; x <= 256; x += 64) for (let y = 0; y <= 256; y += 64) {
    fctx.beginPath(); fctx.arc(x, y, 3, 0, Math.PI * 2); fctx.fill();
  }
  const floorTex = new THREE.CanvasTexture(floorCanvas);
  floorTex.wrapS = floorTex.wrapT = THREE.RepeatWrapping;
  floorTex.repeat.set(8, 8);
  floorTex.anisotropy = 8;
  const floorReflect = new THREE.Mesh(
    new THREE.PlaneGeometry(30, 30),
    new THREE.MeshStandardMaterial({
      map: floorTex,
      color: 0xffffff,
      metalness: 0.42,
      roughness: 0.55,
      envMapIntensity: 0.7,
    }),
  );
  floorReflect.rotation.x = -Math.PI / 2;
  floorReflect.position.y = 0.005;
  scene.add(floorReflect);

  // —— 紧急警报灯：两端各一盏红色 PointLight，周期脉冲 ——
  const alertLights: THREE.PointLight[] = [];
  for (const [ax, az] of [[-3.5, -8], [3.5, -8], [-3.5, -12], [3.5, -12]] as [number,number][]) {
    // 警报灯具体（红色发光球）
    const alertFixture = new THREE.Mesh(
      new THREE.SphereGeometry(0.08, 8, 6),
      new THREE.MeshBasicMaterial({ color: 0xff2020 }),
    );
    alertFixture.position.set(ax, 3.9, az);
    scene.add(alertFixture);
    // 红色点光源（intensity 在 update 中脉冲）
    const al = new THREE.PointLight(0xff1a1a, 0, 8, 1.8);
    al.position.set(ax, 3.7, az);
    scene.add(al);
    alertLights.push(al);
  }

  return { rackMeshes, vcenterScreen, update, emitSmoke };
}
