/**
 * 手雷系统 —— Q 键投掷手雷：
 *  - 真实外形（橄榄绿金属体 + 安全柄 + 引信管）
 *  - 抛物线物理 + 地面弹跳
 *  - 2 秒引信，最后 1 秒引信闪红光预警
 *  - 爆炸：白热核心 + 橙色火球 + 冲击波环 + 碎片粒子 + 烟雾
 */
import * as THREE from 'three';
import type { BugEnemies } from '../engine/BugEnemies';
import { synthAudio } from '../audio/SynthAudio';
import { EventBus } from '../core/EventBus';

interface Grenade {
  group: THREE.Group;
  bodyMat: THREE.MeshStandardMaterial;
  fuseMat: THREE.MeshStandardMaterial;
  velocity: THREE.Vector3;
  timeLeft: number;
  bounced: number;
  /** 危险圈（引信最后阶段才创建） */
  dangerRing?: THREE.Mesh;
  dangerRingMat?: THREE.MeshBasicMaterial;
}

interface Debris {
  mesh: THREE.Mesh;
  vel: THREE.Vector3;
  life: number;
  maxLife: number;
}

export class GrenadeSystem {
  private readonly scene: THREE.Scene;
  private readonly bugs: BugEnemies;
  private grenades: Grenade[] = [];
  private debris: Debris[] = [];
  private cooldown = 0;
  private readonly camera: THREE.Camera;
  private stock = 3;
  private maxStock = 3;
  private readonly onStockChange?: (stock: number, max: number) => void;
  private readonly onKillBurst?: (n: number) => void;
  private onPlayerDamage?: (dmg: number) => void;

  constructor(
    scene: THREE.Scene,
    camera: THREE.Camera,
    bugs: BugEnemies,
    onStockChange?: (stock: number, max: number) => void,
    onKillBurst?: (n: number) => void,
    onPlayerDamage?: (dmg: number) => void,
  ) {
    this.scene = scene;
    this.camera = camera;
    this.bugs = bugs;
    this.onStockChange = onStockChange;
    this.onKillBurst = onKillBurst;
    this.onPlayerDamage = onPlayerDamage;
  }

  attach(): void {
    window.addEventListener('keydown', this.onKey);
    this.onStockChange?.(this.stock, this.maxStock);
  }
  detach(): void {
    window.removeEventListener('keydown', this.onKey);
  }

  addStock(n = 1): void {
    this.stock = Math.min(this.maxStock, this.stock + n);
    this.onStockChange?.(this.stock, this.maxStock);
  }

  private onKey = (e: KeyboardEvent): void => {
    if (e.code === 'KeyQ' && !e.repeat) this.throw();
  };

  /** 构建真实手雷外形：主体 + 安全柄 + 引信管 */
  private buildGrenadeGroup(): {
    group: THREE.Group;
    bodyMat: THREE.MeshStandardMaterial;
    fuseMat: THREE.MeshStandardMaterial;
  } {
    const group = new THREE.Group();

    // 主体：橄榄绿金属球，略微压扁
    const bodyMat = new THREE.MeshStandardMaterial({
      color: 0x3d4a28,
      metalness: 0.55,
      roughness: 0.62,
    });
    const body = new THREE.Mesh(new THREE.SphereGeometry(0.11, 9, 7), bodyMat);
    body.scale.y = 0.88;
    group.add(body);

    // 安全柄（保险片）：侧面金属条
    const handleMat = new THREE.MeshStandardMaterial({
      color: 0x1c1f14,
      metalness: 0.8,
      roughness: 0.35,
    });
    const handle = new THREE.Mesh(
      new THREE.BoxGeometry(0.026, 0.13, 0.014),
      handleMat,
    );
    handle.position.set(0.045, 0.04, 0);
    group.add(handle);

    // 引信管：顶部细圆柱，最后 1 秒会发红光
    const fuseMat = new THREE.MeshStandardMaterial({
      color: 0x4a3c2a,
      metalness: 0.45,
      roughness: 0.65,
      emissive: 0x000000,
      emissiveIntensity: 0,
    });
    const fuse = new THREE.Mesh(
      new THREE.CylinderGeometry(0.013, 0.013, 0.07, 6),
      fuseMat,
    );
    fuse.position.y = 0.125;
    group.add(fuse);

    return { group, bodyMat, fuseMat };
  }

  throw(): void {
    if (this.cooldown > 0) return;
    if (this.stock <= 0) return;
    this.cooldown = 0.6;
    this.stock -= 1;
    this.onStockChange?.(this.stock, this.maxStock);

    const dir = new THREE.Vector3();
    this.camera.getWorldDirection(dir);
    const origin = this.camera.getWorldPosition(new THREE.Vector3());
    origin.addScaledVector(dir, 0.3);

    const { group, bodyMat, fuseMat } = this.buildGrenadeGroup();
    group.position.copy(origin);
    this.scene.add(group);

    // 投掷速度：前向 + 向上
    const vel = dir.clone().multiplyScalar(12);
    vel.y += 3.5;

    this.grenades.push({ group, bodyMat, fuseMat, velocity: vel, timeLeft: 2.0, bounced: 0 });
    synthAudio.play('grenade_throw');
    EventBus.emit('grenade:thrown', {});
  }

  update(dt: number): void {
    this.cooldown = Math.max(0, this.cooldown - dt);

    // ── 手雷飞行物理 ──────────────────────────────────────────────
    for (let i = this.grenades.length - 1; i >= 0; i--) {
      const g = this.grenades[i];
      g.timeLeft -= dt;
      g.velocity.y -= 9.8 * dt;
      g.group.position.addScaledVector(g.velocity, dt);

      // 翻滚感
      g.group.rotation.x += dt * 4.5;
      g.group.rotation.z += dt * 2.8;

      // 地面弹跳
      if (g.group.position.y <= 0.12) {
        g.group.position.y = 0.12;
        if (g.velocity.y < 0) {
          g.velocity.y = -g.velocity.y * 0.45;
          g.velocity.x *= 0.75;
          g.velocity.z *= 0.75;
          g.bounced += 1;
          if (Math.abs(g.velocity.y) > 0.6) synthAudio.play('grenade_bounce');
        }
      }

      // 最后 1 秒引信发红光脉冲 + 危险圈
      if (g.timeLeft < 1.0) {
        const pulse = (Math.sin(performance.now() * 0.018) + 1) / 2;
        g.fuseMat.emissive.setHex(0xff2200);
        g.fuseMat.emissiveIntensity = 0.5 + pulse * 2.5;

        // 危险圈：在地上投影爆炸范围，调用者能看到逃出
        if (!g.dangerRing) {
          const dmat = new THREE.MeshBasicMaterial({
            color: 0xff3322,
            transparent: true,
            opacity: 0.5,
            side: THREE.DoubleSide,
            depthWrite: false,
          });
          const dmesh = new THREE.Mesh(new THREE.RingGeometry(4.2, 4.5, 40), dmat);
          dmesh.rotation.x = -Math.PI / 2;
          dmesh.position.set(g.group.position.x, 0.03, g.group.position.z);
          this.scene.add(dmesh);
          g.dangerRing = dmesh;
          g.dangerRingMat = dmat;
        } else {
          g.dangerRing.position.set(g.group.position.x, 0.03, g.group.position.z);
          if (g.dangerRingMat) g.dangerRingMat.opacity = 0.35 + pulse * 0.45;
        }
      }

      if (g.timeLeft <= 0) {
        this.explode(g);
        if (g.dangerRing) {
          this.scene.remove(g.dangerRing);
          g.dangerRing.geometry.dispose();
          g.dangerRingMat?.dispose();
        }
        this.scene.remove(g.group);
        g.group.traverse((child) => {
          if ((child as THREE.Mesh).isMesh) {
            (child as THREE.Mesh).geometry.dispose();
            ((child as THREE.Mesh).material as THREE.Material).dispose();
          }
        });
        this.grenades.splice(i, 1);
      }
    }

    // ── 碎片粒子更新 ─────────────────────────────────────────────
    for (let i = this.debris.length - 1; i >= 0; i--) {
      const d = this.debris[i];
      d.life -= dt;
      if (d.life <= 0) {
        this.scene.remove(d.mesh);
        d.mesh.geometry.dispose();
        (d.mesh.material as THREE.Material).dispose();
        this.debris.splice(i, 1);
        continue;
      }
      d.vel.y -= 14 * dt;
      d.mesh.position.addScaledVector(d.vel, dt);
      if (d.mesh.position.y < 0.04) {
        d.mesh.position.y = 0.04;
        d.vel.y = 0;
        d.vel.x *= 0.5;
        d.vel.z *= 0.5;
      }
      const t = d.life / d.maxLife;
      const mat = d.mesh.material as THREE.MeshStandardMaterial;
      mat.emissiveIntensity = t * 2.5;
      mat.opacity = Math.min(1, t * 2.5);
    }
  }

  private explode(g: Grenade): void {
    synthAudio.play('grenade_explode');
    const center = g.group.position.clone();
    const radius = 4.5;

    // 1. 强烈闪光 PointLight
    const flash = new THREE.PointLight(0xffbb44, 45, 20);
    flash.position.copy(center);
    this.scene.add(flash);

    // 2. 核心白热（最内层）
    const coreMat = new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 1.0,
      depthWrite: false,
    });
    const core = new THREE.Mesh(new THREE.SphereGeometry(0.15, 8, 6), coreMat);
    core.position.copy(center);
    this.scene.add(core);

    // 3. 橙红火球
    const fireMat = new THREE.MeshBasicMaterial({
      color: 0xff5500,
      transparent: true,
      opacity: 0.92,
      depthWrite: false,
    });
    const fire = new THREE.Mesh(new THREE.SphereGeometry(0.2, 10, 8), fireMat);
    fire.position.copy(center);
    this.scene.add(fire);

    // 4. 冲击波环（水平扩散）
    const ringMat = new THREE.MeshBasicMaterial({
      color: 0xffcc66,
      transparent: true,
      opacity: 0.6,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.2, 0.06, 6, 24), ringMat);
    ring.position.copy(center);
    ring.rotation.x = Math.PI / 2;
    this.scene.add(ring);

    // 5. 烟雾球（深灰，缓慢扩散上升）
    const smokeMat = new THREE.MeshBasicMaterial({
      color: 0x333333,
      transparent: true,
      opacity: 0.55,
      depthWrite: false,
    });
    const smoke = new THREE.Mesh(new THREE.SphereGeometry(0.25, 10, 8), smokeMat);
    smoke.position.copy(center);
    smoke.position.y += 0.15;
    this.scene.add(smoke);

    // 6. 14 个碎片粒子（橙红小球飞散）
    for (let k = 0; k < 14; k++) {
      const debrisMat = new THREE.MeshStandardMaterial({
        color: 0xff3300,
        emissive: 0xff1100,
        emissiveIntensity: 2.5,
        transparent: true,
        opacity: 1.0,
      });
      const dm = new THREE.Mesh(
        new THREE.SphereGeometry(0.022 + Math.random() * 0.035, 4, 3),
        debrisMat,
      );
      dm.position.copy(center);
      const angle = Math.random() * Math.PI * 2;
      const elev = Math.random() * Math.PI * 0.55;
      const spd = 5 + Math.random() * 11;
      const vel = new THREE.Vector3(
        Math.cos(angle) * Math.cos(elev) * spd,
        Math.sin(elev) * spd + 1.5,
        Math.sin(angle) * Math.cos(elev) * spd,
      );
      this.scene.add(dm);
      const ml = 0.55 + Math.random() * 0.5;
      this.debris.push({ mesh: dm, vel, life: ml, maxLife: ml });
    }

    // 动画：火球扩散 + 冲击波环 + 烟雾上升 + 闪光衰减
    const start = performance.now();
    const step = (): void => {
      const t = performance.now() - start;
      const tf = Math.min(t / 320, 1); // 火球 320ms
      const tr = Math.min(t / 450, 1); // 冲击波环 450ms
      const ts = Math.min(t / 750, 1); // 烟雾 750ms

      flash.intensity = Math.max(0, 45 * (1 - tf * 1.6));

      core.scale.setScalar(1 + tf * 4);
      coreMat.opacity = Math.max(0, 1 - tf * 2.2);

      fire.scale.setScalar(1 + tf * 9);
      fireMat.opacity = Math.max(0, 0.92 - tf * 1.05);

      ring.scale.setScalar(1 + tr * 14);
      ringMat.opacity = Math.max(0, 0.6 * (1 - tr * 1.5));

      smoke.scale.setScalar(1 + ts * 10);
      smoke.position.y = center.y + 0.15 + ts * 2.0;
      smokeMat.opacity = Math.max(0, 0.55 * (1 - ts));

      if (ts < 1) {
        requestAnimationFrame(step);
      } else {
        this.scene.remove(flash, core, fire, ring, smoke);
        [coreMat, fireMat, ringMat, smokeMat].forEach((m) => m.dispose());
        [core, fire, ring, smoke].forEach((m) => m.geometry.dispose());
      }
    };
    requestAnimationFrame(step);

    // 伤害计算
    let kills = 0;
    const _wp = new THREE.Vector3();
    for (const mesh of this.bugs.getHitMeshes()) {
      mesh.getWorldPosition(_wp);
      if (_wp.distanceTo(center) <= radius) {
        const res = this.bugs.damage(mesh, 99);
        if (res?.killed) kills += 1;
      }
    }
    if (kills > 0) this.onKillBurst?.(kills);
    EventBus.emit('grenade:explode', { kills, pos: center });

    // 震屏：距离越近越犹，超过 12m 不震
    const camPos = this.camera.getWorldPosition(new THREE.Vector3());
    const dist = camPos.distanceTo(center);
    if (dist < 12) {
      const intensity = Math.max(0, 1 - dist / 12); // 0..1
      EventBus.emit('camera:shake', { intensity, durationMs: 350 + intensity * 250 });
    }
    // 玩家自伤：在 4.5m 半径内，按距离衰减最多 35 点
    if (this.onPlayerDamage && dist < radius) {
      const falloff = Math.max(0, 1 - dist / radius);
      const selfDmg = Math.round(35 * falloff);
      if (selfDmg > 0) this.onPlayerDamage(selfDmg);
    }
  }

  get currentStock(): number {
    return this.stock;
  }
}
