/**
 * IntroVideo —— 游戏开场宣传片播放器
 * ------------------------------------
 * 在 Briefing 面板之前播放 40 秒 SmartX 史诗开场视频。
 * 支持：自动播放、字幕、跳过、ESC 键、空格键、进度条。
 *
 * 集成示例（在 ReactUi.tsx 顶层，UIRoot 内，<Briefing /> 之前插入）：
 *
 *   const [introOpen, setIntroOpen] = React.useState(true);
 *   ...
 *   {introOpen && (
 *     <IntroVideo
 *       src="/intro.mp4"
 *       onComplete={() => setIntroOpen(false)}
 *     />
 *   )}
 *   <Briefing state={state} />
 *
 * 视频文件位置：client/public/intro.mp4 (Vite 会从根路径 / 提供)
 */
import React from 'react';

const C = {
  bg: '#0a0e1a',
  cyan: '#00d4ff',
  text: '#e8edf5',
  muted: '#7a8499',
  brand: '#00d4ff',
};

// 打字机版 intro：文字已渲染在视频中，无需重复的底部字幕
const SUBTITLES: { from: number; to: number; text: string }[] = [];

export interface IntroVideoProps {
  /** 视频源 URL，默认 /intro.mp4（client/public/intro.mp4） */
  src?: string;
  /** 视频播放完毕或被跳过时调用 */
  onComplete: () => void;
  /** 是否启用字幕，默认 true */
  showSubtitles?: boolean;
}

export const IntroVideo: React.FC<IntroVideoProps> = ({
  src = '/intro.mp4',
  onComplete,
  showSubtitles = true,
}) => {
  const videoRef = React.useRef<HTMLVideoElement | null>(null);
  const [progress, setProgress] = React.useState(0);
  const [duration, setDuration] = React.useState(40);
  const [currentTime, setCurrentTime] = React.useState(0);
  const [error, setError] = React.useState<string | null>(null);
  const [canPlay, setCanPlay] = React.useState(false);
  // 浏览器需要用户手势才能播放有声视频；先显示点击层，点击后再播
  const [gestureNeeded, setGestureNeeded] = React.useState(true);
  const completedRef = React.useRef(false);

  const handleSkip = React.useCallback(() => {
    if (completedRef.current) return;
    completedRef.current = true;
    const v = videoRef.current;
    if (v) {
      try { v.pause(); } catch { /* ignore */ }
    }
    onComplete();
  }, [onComplete]);

  // 键盘：ESC / 空格 跳过（仅在视频已开始播放时有效）
  React.useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        handleSkip();
      }
      if (e.code === 'Space' && !gestureNeeded) {
        e.preventDefault();
        handleSkip();
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [handleSkip, gestureNeeded]);

  // 用户点击/按键 → 提供手势 → 有声播放
  const startWithGesture = React.useCallback(() => {
    if (!gestureNeeded) return;
    setGestureNeeded(false);
    const v = videoRef.current;
    if (!v) return;
    v.muted = false;
    v.play().catch(() => {
      v.muted = true;
      v.play().catch((e) => setError(`视频无法播放：${(e as Error).message}`));
    });
  }, [gestureNeeded]);

  // 任意键也可触发开始（排除修饰键）
  React.useEffect(() => {
    if (!gestureNeeded) return;
    const onKey = (e: KeyboardEvent) => {
      if (['Control', 'Alt', 'Shift', 'Meta'].includes(e.key)) return;
      startWithGesture();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [gestureNeeded, startWithGesture]);

  // 字幕选择
  const currentSub = showSubtitles
    ? SUBTITLES.find((s) => currentTime >= s.from && currentTime <= s.to)
    : undefined;

  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        background: C.bg,
        zIndex: 9999,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        cursor: 'pointer',
      }}
      onClick={startWithGesture}
    >
      {/* 手势等待层：需要用户点击才能有声播放 */}
      {gestureNeeded && (
        <div
          style={{
            position: 'absolute',
            inset: 0,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            background: '#040810',
            zIndex: 10001,
            cursor: 'pointer',
            userSelect: 'none',
          }}
        >
          <div style={{
            fontSize: 13,
            letterSpacing: 6,
            color: '#00d4ff',
            fontFamily: 'Menlo, Consolas, monospace',
            marginBottom: 28,
            opacity: 0.7,
          }}>SmartX TACTICAL OPS</div>
          <div style={{
            fontSize: 22,
            letterSpacing: 4,
            color: '#e8edf5',
            fontFamily: 'Menlo, Consolas, monospace',
            animation: 'smartx-blink 1.1s step-end infinite',
          }}>▶  点击开始 / PRESS ANY KEY</div>
          <div style={{
            position: 'absolute',
            bottom: 18,
            right: 22,
            fontSize: 11,
            letterSpacing: 2,
            color: '#6ec1ff',
            fontFamily: 'Menlo, Consolas, monospace',
            opacity: 0.55,
          }}>R7 · HDRi · SSAO · ADS · ShellEject · Volumetric · Reverb</div>
          <style>{`
            @keyframes smartx-blink {
              0%, 100% { opacity: 1; }
              50% { opacity: 0.25; }
            }
          `}</style>
        </div>
      )}

      {/* 视频本体 */}
      <video
        ref={videoRef}
        src={src}
        playsInline
        preload="auto"
        style={{
          maxWidth: '100%',
          maxHeight: '100%',
          width: 'auto',
          height: 'auto',
          objectFit: 'contain',
          background: '#000',
        }}
        onLoadedMetadata={(e) => setDuration(e.currentTarget.duration || 40)}
        onCanPlay={() => setCanPlay(true)}
        onTimeUpdate={(e) => {
          const t = e.currentTarget.currentTime;
          setCurrentTime(t);
          setProgress(t / (e.currentTarget.duration || 40));
        }}
        onEnded={handleSkip}
        onError={() => setError('视频加载失败：请确认 client/public/intro.mp4 存在')}
      />

      {/* 顶部右上角：跳过按钮 */}
      <button
        onClick={(e) => {
          e.stopPropagation();
          handleSkip();
        }}
        style={{
          position: 'absolute',
          top: 24,
          right: 32,
          background: 'rgba(0, 0, 0, 0.55)',
          border: `1px solid ${C.cyan}40`,
          color: C.text,
          padding: '10px 20px',
          fontSize: 13,
          fontFamily: 'Menlo, Consolas, monospace',
          letterSpacing: 3,
          cursor: 'pointer',
          backdropFilter: 'blur(6px)',
          transition: 'all 0.2s',
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.background = `${C.cyan}30`;
          e.currentTarget.style.borderColor = C.cyan;
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.background = 'rgba(0, 0, 0, 0.55)';
          e.currentTarget.style.borderColor = `${C.cyan}40`;
        }}
      >
        跳过 [ESC] →
      </button>

      {/* 加载提示 */}
      {!canPlay && !error && (
        <div
          style={{
            position: 'absolute',
            color: C.muted,
            fontSize: 14,
            letterSpacing: 4,
            fontFamily: 'Menlo, monospace',
          }}
        >
          LOADING INTRO...
        </div>
      )}

      {/* 错误提示 */}
      {error && (
        <div
          style={{
            position: 'absolute',
            color: '#ff6b6b',
            fontSize: 14,
            letterSpacing: 2,
            fontFamily: 'Menlo, monospace',
            background: 'rgba(0,0,0,0.7)',
            padding: '20px 30px',
            border: '1px solid #ff6b6b',
            textAlign: 'center',
          }}
        >
          {error}
          <div style={{ marginTop: 12, color: C.muted, fontSize: 12 }}>
            点击任意位置或按 ESC 跳过
          </div>
        </div>
      )}

      {/* 字幕 */}
      {currentSub && (
        <div
          style={{
            position: 'absolute',
            bottom: 80,
            left: '50%',
            transform: 'translateX(-50%)',
            maxWidth: '80%',
            padding: '12px 28px',
            background: 'rgba(0, 0, 0, 0.65)',
            color: C.text,
            fontSize: 18,
            lineHeight: 1.6,
            letterSpacing: 1,
            textAlign: 'center',
            textShadow: '0 2px 4px rgba(0,0,0,0.9)',
            backdropFilter: 'blur(4px)',
            borderLeft: `3px solid ${C.cyan}`,
            borderRight: `3px solid ${C.cyan}`,
          }}
        >
          {currentSub.text}
        </div>
      )}

      {/* 底部进度条 */}
      <div
        style={{
          position: 'absolute',
          bottom: 0,
          left: 0,
          right: 0,
          height: 3,
          background: 'rgba(255,255,255,0.12)',
        }}
      >
        <div
          style={{
            height: '100%',
            width: `${progress * 100}%`,
            background: `linear-gradient(90deg, ${C.cyan}, #ffffff)`,
            boxShadow: `0 0 12px ${C.cyan}`,
            transition: 'width 0.2s linear',
          }}
        />
      </div>

      {/* 底部时间码 */}
      <div
        style={{
          position: 'absolute',
          bottom: 12,
          right: 24,
          color: C.muted,
          fontSize: 11,
          fontFamily: 'Menlo, monospace',
          letterSpacing: 2,
        }}
      >
        {formatTime(currentTime)} / {formatTime(duration)}
      </div>
    </div>
  );
};

function formatTime(s: number): string {
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${sec.toString().padStart(2, '0')}`;
}

export default IntroVideo;
