// 完整迁移管线（开始 FULL_SYNC 时前5步已完成）
const MIGRATION_PIPELINE_STEPS = [
  { key: 'ENV_SCAN',         label: '环境扫描',   desc: '收集 vCenter / ESXi 拓扑' },
  { key: 'COMPAT_CHECK',     label: '兼容性检查', desc: '检测 CPU / 磁盘 / 驱动兼容性' },
  { key: 'NETWORK_MAP',      label: '网络规划',   desc: '映射 vSwitch → SMTX vNet' },
  { key: 'STORAGE_MAP',      label: '存储映射',   desc: '规划 VMFS → SmartX Pool' },
  { key: 'SNAPSHOT',         label: '快照创建',   desc: '生成迁移基线快照' },
  { key: 'FULL_SYNC',        label: '全量同步',   desc: '传输磁盘全量数据到目标存储' },
  { key: 'INCREMENTAL_SYNC', label: '增量同步',   desc: '同步快照期间产生的差量数据' },
  { key: 'DRIVER_INJECT',    label: '驱动注入',   desc: '注入 VirtIO / SMTX Guest Agent' },
  { key: 'CUTOVER',          label: '停机切换',   desc: '关机→最终同步→在目标端启动' },
];

// phase → 当前正在执行的步骤下标（0-indexed）
const PHASE_STEP_IDX: Record<string, number> = {
  FULL_SYNC:        5,
  INCREMENTAL_SYNC: 6,
  PRE_QUIZ_WAIT:    7,
  QUIZ_RUNNING:     7,
  DONE:             9, // 全部完成
};

const LOG_COLOR: Record<string, string> = {
  info:    '#7A9CC0',
  success: '#00E676',
  warn:    '#FFB300',
  danger:  '#FF1744',
};

const MigrationViz: React.FC<{ state: UiState }> = ({ state }) => {
  const m = state.migrationViz;
  if (!m.open) return null;

  const pct = Math.max(0, Math.min(100, m.progress.fullSyncPercent));
  const activeIdx = PHASE_STEP_IDX[m.phase] ?? 5;
  const hasBlocker = m.blocker.type !== 'NONE';

  return (
    <div
      style={{
        position: 'fixed',
        top: 12,
        right: 12,
        width: 390,
        background: 'linear-gradient(160deg, rgba(3,9,20,0.94) 0%, rgba(1,5,14,0.90) 100%)',
        border: `1px solid ${hasBlocker ? 'rgba(255,179,0,0.4)' : C.bg.panelBorder}`,
        boxShadow: hasBlocker
          ? '0 0 28px rgba(255,140,0,0.18)'
          : '0 0 32px rgba(0,180,255,0.2), inset 0 1px 0 rgba(255,255,255,0.04)',
        borderRadius: 10,
        padding: '12px 14px',
        pointerEvents: 'none',
        zIndex: 14,
        fontFamily: CLOUDTOWER_THEME.typography.fontMono,
      }}
    >
      {/* ── 标题行 ── */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
        <div style={{ fontSize: 10, letterSpacing: 3, color: C.accent.primary }}>▶ MIGRATION PIPELINE</div>
        <div style={{
          fontSize: 10,
          padding: '2px 8px',
          borderRadius: 4,
          background: hasBlocker ? 'rgba(255,120,0,0.15)' : 'rgba(0,180,255,0.1)',
          border: `1px solid ${hasBlocker ? 'rgba(255,190,80,0.4)' : 'rgba(0,180,255,0.28)'}`,
          color: hasBlocker ? C.accent.warning : C.accent.primary,
          letterSpacing: 1,
        }}>
          {hasBlocker ? '⚠ 等待清场' : (m.phase === 'FULL_SYNC' ? `${pct.toFixed(0)}%` : m.phase === 'INCREMENTAL_SYNC' ? `增量 ×${m.progress.incrementalRounds}` : m.phase === 'QUIZ_RUNNING' ? '知识考核' : '驱动注入')}
        </div>
      </div>

      {/* VM 名称 */}
      {m.vmName && (
        <div style={{ marginBottom: 10, fontSize: 11, color: C.text.secondary }}>
          迁移目标：<span style={{ color: C.text.primary }}>{m.vmName}</span>
        </div>
      )}

      {/* ── 管线步骤列表 ── */}
      <div style={{ marginBottom: 6 }}>
        {MIGRATION_PIPELINE_STEPS.map((step, i) => {
          const isDone    = i < activeIdx;
          const isActive  = i === activeIdx;
          const isPending = i > activeIdx;
          const lineColor = isDone ? 'rgba(0,230,118,0.35)' : 'rgba(255,255,255,0.08)';

          return (
            <div key={step.key} style={{ display: 'flex', alignItems: 'flex-start', gap: 8 }}>
              {/* 竖线 + 节点 */}
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', width: 20, flexShrink: 0 }}>
                <div style={{
                  width: 18, height: 18, borderRadius: '50%',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 9, fontWeight: 700, flexShrink: 0,
                  background: isDone ? 'rgba(0,230,118,0.18)' : isActive ? 'rgba(0,180,255,0.18)' : 'rgba(255,255,255,0.04)',
                  border: `1.5px solid ${isDone ? '#00E676' : isActive ? '#00B4FF' : 'rgba(255,255,255,0.12)'}`,
                  color: isDone ? '#00E676' : isActive ? '#00B4FF' : 'rgba(255,255,255,0.25)',
                }}>
                  {isDone ? '✓' : isActive ? '▶' : String(i + 1)}
                </div>
                {i < MIGRATION_PIPELINE_STEPS.length - 1 && (
                  <div style={{
                    width: 1.5,
                    minHeight: isActive ? 8 : 5,
                    flex: 1,
                    background: lineColor,
                  }} />
                )}
              </div>

              {/* 步骤内容 */}
              <div style={{ flex: 1, paddingBottom: isActive ? 2 : 1 }}>
                <div style={{
                  display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                  fontSize: isActive ? 12 : 11,
                  color: isDone ? '#00E676' : isActive ? C.text.primary : 'rgba(255,255,255,0.25)',
                  fontWeight: isActive ? 600 : 400,
                  lineHeight: '18px',
                }}>
                  <span>{step.label}</span>
                  {isDone && <span style={{ fontSize: 9, color: 'rgba(0,230,118,0.5)' }}>已完成</span>}
                  {isPending && <span style={{ fontSize: 9, color: 'rgba(255,255,255,0.2)' }}>{step.desc}</span>}
                </div>

                {/* 当前步骤展开详情 */}
                {isActive && (
                  <div style={{ marginTop: 6, marginBottom: 10 }}>
                    {m.phase === 'FULL_SYNC' && (
                      <>
                        {/* 进度条 */}
                        <div style={{
                          background: 'rgba(255,255,255,0.07)',
                          height: 8, borderRadius: 4,
                          marginBottom: 7, overflow: 'hidden',
                        }}>
                          <div style={{
                            width: `${pct}%`, height: '100%', borderRadius: 4,
                            background: hasBlocker
                              ? 'linear-gradient(90deg, #883300, #FF6600)'
                              : 'linear-gradient(90deg, #0055BB, #00B4FF 60%, #00FFD5)',
                            transition: 'width 0.5s ease',
                          }} />
                        </div>
                        {/* 3列指标 */}
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 6, marginBottom: 5 }}>
                          {[
                            { label: '进度', value: `${pct.toFixed(1)}%`, big: true },
                            { label: '速率', value: `${m.progress.transferSpeedMbps.toFixed(0)} Mbps` },
                            { label: '预计剩余', value: `${Math.max(0, Math.floor(m.progress.etaSeconds))} s` },
                          ].map(({ label, value, big }) => (
                            <div key={label}>
                              <div style={{ color: 'rgba(255,255,255,0.35)', fontSize: 9, marginBottom: 2 }}>{label}</div>
                              <div style={{ color: C.text.primary, fontSize: big ? 15 : 12, fontWeight: big ? 700 : 400 }}>{value}</div>
                            </div>
                          ))}
                        </div>
                        <div style={{ color: 'rgba(255,255,255,0.4)', fontSize: 10 }}>
                          已传输{' '}
                          <span style={{ color: C.text.secondary }}>{m.progress.dataTransferredGB.toFixed(1)}</span>
                          {' '}/{' '}
                          <span style={{ color: C.text.secondary }}>{m.progress.dataTotalGB.toFixed(1)}</span>
                          {' '}GB
                        </div>
                      </>
                    )}
                    {m.phase === 'INCREMENTAL_SYNC' && (
                      <div style={{ fontSize: 11 }}>
                        <div style={{ color: C.text.secondary, marginBottom: 4 }}>
                          已完成{' '}
                          <span style={{ color: C.accent.primary, fontWeight: 700 }}>{m.progress.incrementalRounds}</span>
                          {' '}轮增量同步
                        </div>
                        <div style={{ color: 'rgba(255,255,255,0.35)', fontSize: 10 }}>
                          速率 {m.progress.transferSpeedMbps.toFixed(0)} Mbps
                          {' · '}累计传输 {m.progress.dataTransferredGB.toFixed(1)} GB
                        </div>
                      </div>
                    )}
                    {(m.phase === 'PRE_QUIZ_WAIT' || m.phase === 'QUIZ_RUNNING') && (
                      <div style={{ color: C.text.secondary, fontSize: 11 }}>
                        {m.phase === 'QUIZ_RUNNING'
                          ? '▶ 迁移知识考核进行中…'
                          : '等待注入 VirtIO + SmartX Guest Agent'}
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* ── 阻塞警告 ── */}
      {hasBlocker && (
        <div style={{
          marginBottom: 8,
          background: 'rgba(255,120,0,0.12)',
          border: '1px solid rgba(255,190,80,0.45)',
          color: C.accent.warning,
          borderRadius: 6, fontSize: 11,
          padding: '6px 10px',
        }}>
          {m.blocker.message}
        </div>
      )}

      {/* ── 事件流 ── */}
      <div style={{ borderTop: `1px solid ${C.bg.panelBorder}`, paddingTop: 7, marginTop: 2 }}>
        <div style={{ fontSize: 9, letterSpacing: 2, color: 'rgba(255,255,255,0.25)', marginBottom: 5 }}>
          EVENT STREAM
        </div>
        {m.timeline.length === 0
          ? <div style={{ color: 'rgba(255,255,255,0.18)', fontSize: 10 }}>—</div>
          : m.timeline.map((t) => (
            <div key={t.id} style={{ marginTop: 3, display: 'flex', gap: 7, alignItems: 'baseline' }}>
              <span style={{ color: 'rgba(255,255,255,0.25)', fontSize: 9, flexShrink: 0 }}>
                {new Date(t.ts).toLocaleTimeString([], { hour12: false })}
              </span>
              <span style={{ color: LOG_COLOR[t.level] ?? C.text.secondary, fontSize: 10, lineHeight: 1.4 }}>
                {t.text}
              </span>
            </div>
          ))
        }
      </div>
    </div>
  );
};

