const Crosshair: React.FC<{ state: UiState }> = ({ state }) => {
  const flash = state.combat.hitFlash;
  const marker = state.combat.hitMarker;
  // 击杀=红、爆头=橙红、普通=白
  const markerColor =
    marker === 'kill' || marker === 'kill_headshot'
      ? '#ff2244'
      : marker === 'headshot'
        ? '#ff7733'
        : '#ffffff';
  const markerSize = marker === 'kill_headshot' ? 18 : marker === 'kill' ? 16 : marker === 'headshot' ? 13 : 11;
  const markerThick = marker === 'kill' || marker === 'kill_headshot' ? 3 : 2;
  const color = flash > 0 ? '#ff3355' : C.accent.primary;
  const armLen = 10;
  const gap = 4;
  const thick = 2;
  const arm = (pos: React.CSSProperties): React.CSSProperties => ({
    position: 'absolute',
    background: color,
    boxShadow: `0 0 6px ${color}`,
    ...pos,
  });
  return (
    <div
      style={{
        position: 'fixed',
        left: '50%',
        top: '50%',
        width: 0,
        height: 0,
        pointerEvents: 'none',
      }}
    >
      {/* 上下左右 4 根短条 + 中心点 */}
      <div style={arm({ top: -(gap + armLen), left: -thick / 2, width: thick, height: armLen })} />
      <div style={arm({ top: gap, left: -thick / 2, width: thick, height: armLen })} />
      <div style={arm({ left: -(gap + armLen), top: -thick / 2, height: thick, width: armLen })} />
      <div style={arm({ left: gap, top: -thick / 2, height: thick, width: armLen })} />
      <div
        style={{
          position: 'absolute',
          left: -1,
          top: -1,
          width: 2,
          height: 2,
          background: color,
          boxShadow: `0 0 4px ${color}`,
        }}
      />
      {/* HitMarker X 形（命中/爆头/击杀） */}
      {marker && (
        <>
          {[0, 1].map((i) => (
            <div
              key={`hm${i}`}
              style={{
                position: 'absolute',
                left: -markerSize / 2,
                top: -markerThick / 2,
                width: markerSize,
                height: markerThick,
                background: markerColor,
                boxShadow: `0 0 8px ${markerColor}`,
                transform: i === 0 ? 'rotate(45deg)' : 'rotate(-45deg)',
                opacity: 0.95,
              }}
            />
          ))}
        </>
      )}
      {flash > 0 && (
        <div
          style={{
            position: 'fixed',
            inset: 0,
            background: 'radial-gradient(ellipse at center, rgba(255,51,85,0.15) 0%, rgba(255,51,85,0) 40%)',
            pointerEvents: 'none',
          }}
        />
      )}
    </div>
  );
};

// ---------------- 浮动伤害数字 ----------------
interface DamagePopupItem {
  id: number;
  x: number;
  y: number;
  amount: number;
  kind: 'normal' | 'headshot' | 'kill' | 'kill_headshot';
  bornAt: number;
}

const DamagePopups: React.FC = () => {
  const [items, setItems] = React.useState<DamagePopupItem[]>([]);
  const seqRef = React.useRef(0);

  React.useEffect(() => {
    const onPopup = (ev: Event): void => {
      const ce = ev as CustomEvent<{ x: number; y: number; amount: number; kind: DamagePopupItem['kind'] }>;
      const d = ce.detail;
      if (!d) return;
      seqRef.current += 1;
      const item: DamagePopupItem = {
        id: seqRef.current,
        x: d.x + (Math.random() - 0.5) * 24,
        y: d.y + (Math.random() - 0.5) * 12,
        amount: d.amount,
        kind: d.kind,
        bornAt: performance.now(),
      };
      setItems((prev) => [...prev.slice(-7), item]);
      window.setTimeout(() => {
        setItems((prev) => prev.filter((it) => it.id !== item.id));
      }, 900);
    };
    document.addEventListener('smartx:damage_popup', onPopup);
    return () => document.removeEventListener('smartx:damage_popup', onPopup);
  }, []);

  return (
    <div style={{ position: 'fixed', inset: 0, pointerEvents: 'none', zIndex: 13 }}>
      {items.map((it) => {
        const age = (performance.now() - it.bornAt) / 900;
        const isHead = it.kind === 'headshot' || it.kind === 'kill_headshot';
        const isKill = it.kind === 'kill' || it.kind === 'kill_headshot';
        const color = isKill ? '#ff2244' : isHead ? '#ff8833' : '#ffe066';
        const size = isKill ? 26 : isHead ? 22 : 18;
        return (
          <div
            key={it.id}
            style={{
              position: 'absolute',
              left: it.x,
              top: it.y - age * 60,
              transform: 'translate(-50%, -50%)',
              color,
              fontFamily: CLOUDTOWER_THEME.typography.fontDisplay,
              fontSize: size,
              fontWeight: 800,
              textShadow: '0 0 6px rgba(0,0,0,0.9), 0 1px 0 #000',
              opacity: Math.max(0, 1 - age),
              letterSpacing: 1,
            }}
          >
            {isHead && <span style={{ fontSize: size * 0.55, marginRight: 4 }}>HEAD</span>}
            {isKill && !isHead && <span style={{ fontSize: size * 0.55, marginRight: 4 }}>KILL</span>}
            {it.amount.toFixed(0)}
          </div>
        );
      })}
    </div>
  );
};

