// ---------------- 迁移知识考核 Quiz 弹窗 ----------------
const QuizModal: React.FC<{
  state: UiState;
  onAnswer: (key: string) => void;
  onNext: () => void;
  onClose: () => void;
}> = ({ state, onAnswer, onNext, onClose }) => {
  const q = state.quiz;
  if (!q.open) return null;
  return (
    <div style={overlayStyle}>
      <div style={{ ...panelBase, width: 720 }}>
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'baseline',
            marginBottom: 14,
          }}
        >
          <div style={{ fontSize: 20, fontWeight: 700, color: '#4cdcff' }}>
            {q.title}
          </div>
          <div style={{ fontSize: 13, color: '#7da3c5' }}>
            {q.finalScore ? '结果' : `第 ${q.index + 1} / ${q.total} 题`}
          </div>
        </div>

        {q.finalScore && (
          <div>
            <div
              style={{
                fontSize: 36,
                fontWeight: 800,
                color: q.finalScore.pct >= 0.8 ? '#66ff9b' : q.finalScore.pct >= 0.5 ? '#ffcc3d' : '#ff5555',
                textAlign: 'center',
                marginBottom: 10,
              }}
            >
              {q.finalScore.correct} / {q.finalScore.total}
            </div>
            <div style={{ textAlign: 'center', color: '#cfd8e3', fontSize: 14, marginBottom: 20 }}>
              {q.finalScore.pct >= 0.8
                ? '✓ 考核通过。你已掌握从 VMware 迁移到 SmartX ELF 的核心流程。'
                : q.finalScore.pct >= 0.5
                  ? '△ 基本合格，但有些关键原理还需要再看一遍实施手册。'
                  : '✗ 未达标。建议重读 VDDK、CBT、VirtIO 三个核心章节后再继续。'}
            </div>
            <div style={{ textAlign: 'center' }}>
              <button style={btn(true)} onClick={onClose}>
                回到指挥台
              </button>
            </div>
          </div>
        )}

        {!q.finalScore && q.question && (
          <>
            <div
              style={{
                fontSize: 17,
                color: '#ffffff',
                marginBottom: 20,
                lineHeight: 1.55,
              }}
            >
              {q.question.stem}
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {q.question.options.map((opt) => {
                const fb = q.feedback;
                const isChosen = fb?.chosenKey === opt.key;
                const isCorrectKey = fb?.correctKey === opt.key;
                let bg = 'rgba(40,52,70,0.65)';
                let border = 'rgba(120,160,200,0.3)';
                if (fb) {
                  if (isCorrectKey) {
                    bg = 'rgba(40,180,100,0.25)';
                    border = '#66ff9b';
                  } else if (isChosen) {
                    bg = 'rgba(200,60,60,0.22)';
                    border = '#ff5555';
                  }
                }
                return (
                  <button
                    key={opt.key}
                    disabled={!!fb}
                    onClick={() => onAnswer(opt.key)}
                    style={{
                      textAlign: 'left',
                      padding: '12px 16px',
                      background: bg,
                      border: `1px solid ${border}`,
                      borderRadius: 4,
                      color: '#e8eef5',
                      fontSize: 14,
                      fontFamily: 'inherit',
                      cursor: fb ? 'default' : 'pointer',
                    }}
                  >
                    <b style={{ color: '#4cdcff', marginRight: 10 }}>{opt.key}.</b>
                    {opt.text}
                  </button>
                );
              })}
            </div>
            {q.feedback && (
              <div
                style={{
                  marginTop: 16,
                  padding: '12px 14px',
                  background: q.feedback.correct ? 'rgba(40,180,100,0.14)' : 'rgba(200,100,40,0.14)',
                  border: `1px solid ${q.feedback.correct ? '#66ff9b' : '#ffb050'}`,
                  borderRadius: 4,
                  color: '#cfd8e3',
                  fontSize: 13,
                  lineHeight: 1.55,
                }}
              >
                <div
                  style={{
                    color: q.feedback.correct ? '#66ff9b' : '#ffb050',
                    fontWeight: 700,
                    marginBottom: 6,
                  }}
                >
                  {q.feedback.correct
                    ? `✓ 正确  ·  答案是 ${q.feedback.correctKey}`
                    : `✗ 错误  ·  正确答案是 ${q.feedback.correctKey}`}
                </div>
                {q.feedback.explanation}
              </div>
            )}
            {q.feedback && (
              <div style={{ textAlign: 'right', marginTop: 14 }}>
                <button style={btn(true)} onClick={onNext}>
                  {q.index + 1 >= q.total ? '提交考核' : '下一题 →'}
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

