/**
 * PostFxPasses — 自定义 ShaderPass 集合
 *
 * 1. VignetteCAGrainPass —— 三合一：暗角 + 色散 + 胶片颗粒（一遍合成，省 2 个 fbo）
 * 2. ScreenSpaceReflectiveAccentPass —— 暗部加冷调蓝 + 亮部加暖调橙（电影感分级）
 *
 * 都用 three/examples 的 ShaderPass，无新增依赖。
 */
import * as THREE from 'three';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass.js';

export const VignetteCAGrainShader = {
  uniforms: {
    tDiffuse: { value: null as THREE.Texture | null },
    time: { value: 0 },
    vignetteOffset: { value: 0.95 },     // 越小暗角越广
    vignetteDarkness: { value: 0.85 },   // 暗角强度
    chromaticAberration: { value: 0.0028 }, // 色散像素偏移
    grainAmount: { value: 0.045 },       // 颗粒强度
    grainSize: { value: 1.6 },           // 颗粒粒度
  },
  vertexShader: `
    varying vec2 vUv;
    void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform sampler2D tDiffuse;
    uniform float time;
    uniform float vignetteOffset;
    uniform float vignetteDarkness;
    uniform float chromaticAberration;
    uniform float grainAmount;
    uniform float grainSize;
    varying vec2 vUv;

    float hash(vec2 p) {
      p = fract(p * vec2(123.34, 456.21));
      p += dot(p, p + 45.32);
      return fract(p.x * p.y);
    }

    void main() {
      vec2 uv = vUv;
      vec2 center = uv - 0.5;
      float dist = length(center);

      // 1) Chromatic aberration —— 越靠边偏移越大（径向）
      vec2 dir = center * dist;
      float ca = chromaticAberration;
      float r = texture2D(tDiffuse, uv - dir * ca).r;
      float g = texture2D(tDiffuse, uv).g;
      float b = texture2D(tDiffuse, uv + dir * ca).b;
      vec3 col = vec3(r, g, b);

      // 2) 影调分级（暗部冷、亮部暖）—— 极轻量电影感
      float lum = dot(col, vec3(0.299, 0.587, 0.114));
      vec3 cool = vec3(0.92, 0.97, 1.10);
      vec3 warm = vec3(1.06, 1.00, 0.92);
      vec3 grade = mix(cool, warm, smoothstep(0.0, 0.7, lum));
      col *= grade;

      // 3) Vignette
      float vig = smoothstep(vignetteOffset, vignetteOffset - 0.45, dist);
      col *= mix(1.0 - vignetteDarkness, 1.0, vig);

      // 4) Film grain（伪噪 + 时间扰动）
      vec2 gp = uv * vec2(textureSize(tDiffuse, 0)) / grainSize;
      float n = hash(gp + fract(time * 60.0));
      col += (n - 0.5) * grainAmount;

      gl_FragColor = vec4(col, 1.0);
    }
  `,
};

export class VignetteCAGrainPass extends ShaderPass {
  constructor() {
    super(VignetteCAGrainShader);
  }
  setTime(t: number): void {
    this.uniforms.time.value = t;
  }
}
