/**
 * UI Store —— 轻量发布订阅状态容器。
 * 由 `UIManager` 单例改成"命令发布者 + 状态可订阅"，React UI 层订阅此状态进行渲染。
 * 各阶段逻辑通过 `UIManager.show*` 返回 Promise，UI 层提交后 Promise resolve。
 */
import type { VCenterCredential } from '../core/credential';
import type { ESXiScanResult, DiscoveredVM } from '../simulation/phases/EnvScanPhase';
import type {
  VSwitchNode,
  BridgeNode,
  NetworkMapping,
} from '../simulation/phases/NetworkMappingPhase';
import type {
  StoragePool,
  StorageMapping,
  VMWorkloadType,
  StorageMismatchWarning,
} from '../simulation/phases/StorageMappingPhase';
import type { SyncChallenge, ChallengeResponse } from '../simulation/phases/DataSyncPhase';
import type { MigrationState } from '../simulation/MigrationStateMachine';
import type { ScoreBreakdown } from '../engine/ScoringSystem';
import type { DataCenterZone } from '../fps/PlayerController';

export interface ScanPanel {
  open: boolean;
}
export interface LoginPanel {
  open: boolean;
  defaultHost?: string;
}
export interface EnvResultPanel {
  open: boolean;
  result: ESXiScanResult | null;
}
export interface CompatPanel {
  open: boolean;
  vms: DiscoveredVM[];
  issues: { vmName: string; severity: 'warn' | 'error'; message: string }[];
}
export interface NetworkPanel {
  open: boolean;
  sources: VSwitchNode[];
  targets: BridgeNode[];
  completed: NetworkMapping[];
}
export interface StoragePanel {
  open: boolean;
  vm: (DiscoveredVM & { workloadType: VMWorkloadType }) | null;
  pools: StoragePool[];
  mapping: StorageMapping | null;
  warning: StorageMismatchWarning | null;
}
export interface ChallengePanel {
  open: boolean;
  challenge: SyncChallenge | null;
}
export interface ScorePanel {
  open: boolean;
  breakdown: ScoreBreakdown | null;
}

export interface LeaderboardEntry {
  rank: number;
  playerName: string;
  score: number;
  grade?: string;
  durationMs?: number;
  completedAt: number;
}
export interface LeaderboardPanel {
  open: boolean;
  entries: LeaderboardEntry[];
  myRank: number | null;
  loading: boolean;
  error: string | null;
}

export interface HudState {
  zone: DataCenterZone;
  stamina: number;
  tool: string;
  hoverHint: string | null;
  state: MigrationState;
  objective: string;
  fullSyncPercent: number;
  incrementalRounds: number;
  score: number;
}

/** 剖头反馈类型。normal=身体，headshot=爆头，kill/kill_headshot=击杀 */
export type HitMarkerKind = 'normal' | 'headshot' | 'kill' | 'kill_headshot';

/** 浮动伤害数字（屏幕坐标由主循环推入、自动衰减） */
export interface DamagePopup {
  id: number;
  x: number;
  y: number;
  amount: number;
  kind: HitMarkerKind;
  ts: number;
}

/** 战斗/FPS 相关 HUD 状态（CS 风格） */
export interface CombatHudState {
  ammo: number;
  reserve: number;
  reloading: boolean;
  kills: number;
  bugsAlive: number;
  hitFlash: number;
  hitMarker: HitMarkerKind | null;
  damageFlash: number;
  weaponName: string;
  weaponId: 'pistol' | 'rifle' | 'scanner';
  grenadeStock: number;
  grenadeMax: number;
}

/** 任务 Mission HUD */
export interface MissionHudState {
  act: {
    id: string;
    index: number;
    title: string;
    subtitle: string;
    objective: string;
    briefing: string;
    hint: string;
  } | null;
  visible: boolean;
  completedFlash: number; // timestamp
  extra: string; // 动态额外信息，如同步进度/剩余距离
}

/** 事件日志（左上角刷屏消息） */
export interface EventLogItem {
  id: number;
  ts: number;
  level: 'info' | 'warn' | 'success' | 'danger';
  text: string;
}

/** 玩家生命值 HUD */
export interface PlayerHealthState {
  hp: number;
  max: number;
  armor: number;
  armorMax: number;
  dead: boolean;
  damageFlash: number; // 0..1，屏幕红暗角
}

/** 迁移知识考核 Quiz 弹窗 */
export interface QuizUiQuestion {
  id: string;
  stem: string;
  options: { key: string; text: string }[];
}
export interface QuizFeedback {
  correct: boolean;
  explanation: string;
  chosenKey: string;
  correctKey: string;
}
export interface QuizPanelState {
  open: boolean;
  title: string;
  question: QuizUiQuestion | null;
  index: number; // 0-based
  total: number;
  feedback: QuizFeedback | null; // 回答后的解析
  finalScore: { correct: number; total: number; pct: number } | null;
}

/** 开场/锁定引导遮罩 */
export interface BriefingState {
  open: boolean;
}

export type MigrationVizPhase =
  | 'FULL_SYNC'
  | 'INCREMENTAL_SYNC'
  | 'PRE_QUIZ_WAIT'
  | 'QUIZ_RUNNING'
  | 'DONE';

export interface MigrationVizLogItem {
  id: number;
  ts: number;
  level: 'info' | 'warn' | 'success' | 'danger';
  text: string;
}

export interface MigrationVizState {
  open: boolean;
  vmName: string;
  phase: MigrationVizPhase;
  progress: {
    fullSyncPercent: number;
    dataTransferredGB: number;
    dataTotalGB: number;
    transferSpeedMbps: number;
    etaSeconds: number;
    incrementalRounds: number;
  };
  blocker: {
    type: 'NONE' | 'ENEMIES_REMAIN' | 'QUIZ_NOT_STARTED';
    message: string;
    remainingEnemies: number | null;
  };
  timeline: MigrationVizLogItem[];
}

/** 路点指示器状态：屏幕上提示玩家下一个交互点位置、距离、边缘箭头 */
export interface WaypointHud {
  active: boolean;
  /** 视口像素坐标，仅 onscreen=true 时有意义 */
  x: number;
  y: number;
  /** 距离（米） */
  distance: number;
  /** 文字标签，例如 "按 E · 连接 vCenter" */
  label: string;
  /** 目标是否在屏幕中（false 时渲染边缘箭头） */
  onscreen: boolean;
  /** 边缘箭头方向（弧度，以屏幕中心为原点，0=右、PI/2=下） */
  edgeAngle: number;
}

/** 教学提示卡（屏幕底部居中），首次操作 / 关键 SOP 节点出现，几秒后自动隐藏 */
export interface TutorialTipState {
  /** 唯一 id，用于 React key + 去重 */
  id: number;
  /** 主标题（例如 "切换工具"） */
  title: string;
  /** 详细描述（例如 "按 1~6 切换武器与扫描枪"） */
  body: string;
  /** 显示时间（ms） */
  ts: number;
  /** 持续显示毫秒数 */
  durationMs: number;
}

export interface UiState {
  login: LoginPanel;
  scanProgress: ScanPanel;
  envResult: EnvResultPanel;
  compat: CompatPanel;
  network: NetworkPanel;
  storage: StoragePanel;
  challenge: ChallengePanel;
  score: ScorePanel;
  leaderboard: LeaderboardPanel;
  hud: HudState;
  combat: CombatHudState;
  mission: MissionHudState;
  health: PlayerHealthState;
  quiz: QuizPanelState;
  briefing: BriefingState;
  migrationViz: MigrationVizState;
  waypoint: WaypointHud;
  tutorialTip: TutorialTipState | null;
  toast: { id: number; level: 'info' | 'warn' | 'error'; text: string }[];
  eventLog: EventLogItem[];
}

